window.STORIES = {"themes": {"origins": {"label": "Before the grid", "color": "#9b7b4f"}, "victorian": {"label": "Victorian San Francisco", "color": "#b4556b"}, "quake1906": {"label": "1906 & rebuilding", "color": "#c0602f"}, "communities": {"label": "Many communities", "color": "#5f7f4f"}, "harlem": {"label": "Harlem of the West", "color": "#3f5f9c"}, "redevelopment": {"label": "Redevelopment", "color": "#6c6f76"}, "institutions": {"label": "Landmarks & institutions", "color": "#8a6d3b"}, "modern": {"label": "Counterculture to today", "color": "#7a4f9c"}}, "stories": [{"id": "origins-hayes-valley-oaks-springs", "theme": "origins", "title": "Oaks and Springs in a Sheltered Hollow", "year": 1776, "yearEnd": null, "place": "Hayes Valley (around Hayes and Buchanan streets)", "precision": "area", "c": [1684.2, 872.8], "block": "0805", "hook": "Most of the peninsula was shifting sand. Hayes Valley was different: a shallow hollow of coast live oaks and natural springs, in Yelamu Ohlone territory.", "story": "Before Spanish settlers arrived in 1776, most of the northern San Francisco peninsula was shifting sand dunes and coastal sage scrub. The planners' historic context statement for this area describes Hayes Valley as different: \"a shallow hollow containing groves of coast live oaks and natural springs\" [1][2]. Shelter and fresh water made it attractive.\n\nThe land lay within the territory of the Yelamu, a group of the Ohlone people. The same report says the nearest known Ohlone village was Chutchui, on Mission Creek and probably not far from Mission Dolores. Its people moved with the seasons to another village, Sitlintac, to gather shellfish on the tidal flats of what is now Mission Bay [1]. Ohlone life centred on extended families and seasonal camps, with acorns among the most important foods [1].\n\nNo major prehistoric site has been recorded in the Market and Octavia plan area, which takes in the eastern edge of this map. The land was heavily disturbed long before archaeologists took an interest. The report still concludes that, with abundant water and food nearby, prehistoric deposits probably remain intact under parts of the area [1].\n\nThe dunes came back into the story later. In the 1850s, fog, wind and shifting sand defeated Thomas Hayes's attempts to farm the valley [1][2].", "people": [], "sources": [{"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area", "publisher": "Page & Turnbull for the San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Pre-1776 oaks, springs, dunes and scrub; Yelamu territory; Chutchui and Sitlintac; Ohlone diet; archaeological potential; Hayes's failed farming"}, {"title": "Hayes Valley Residential Historic District Update (DPR 523D District Record)", "publisher": "Page & Turnbull / San Francisco Planning Department", "year": 2008, "url": "https://sfplanning.org/sites/default/files/documents/preserv/DPRforms/DPR%20523D_Hayes%20Valley%20Residential%20Update%206_6_08.pdf", "supports": "Hollow of coast live oaks and natural springs contrasting with dunes and chaparral; fog, wind and sand defeated farming"}], "photo": null}, {"id": "origins-phelps-house-origins", "theme": "origins", "title": "The Oldest House and Its Rival Origin Stories", "year": 1850, "yearEnd": null, "place": "Abner Phelps House, 1111 Oak Street", "precision": "building", "c": [745.4, 1113.7], "block": "1218", "hook": "San Francisco's oldest house has at least three birth stories: shipped from New Orleans, framed from Maine lumber, or built from California redwood.", "story": "At 1111 Oak Street stands a Gothic Revival cottage that its 1971 National Register nomination calls \"generally considered to be the oldest unaltered residence in San Francisco\", dating from 1850-51 [1]. The same nomination admits that \"accounts vary as to its date and builder\" [1].\n\nThe earliest published account, from 1934, said John Middleton & Sons built it in 1850 from lumber framed into sections and shipped \"round the Horn from Maine, there being no sawmills here at the time\" [1][2]. In 1961 Abner Phelps's great-granddaughter told another story. The house had been bought in New Orleans and shipped around the Horn to ease the homesickness of his bride, Augusta Roussell [1]. The raised foundation and veranda do recall Louisiana cottages [1]. A 1907 San Francisco Call interview with the family agreed that it \"was built in Louisiana and came around the Horn all ready to be put up\" [3]. Then a 1970s analysis of the wood by UC Berkeley scientists suggested California redwood [3].\n\nThe Junior League book Here Today states with certainty that Phelps, a Mexican War colonel and lawyer, lived there in 1851, well outside a city whose limits did not reach Divisadero until 1854 [1]. When it sold in 2024, the Chronicle still called it \"widely believed to be the city's oldest house\" [4].", "people": [{"name": "Abner Phelps", "role": "Lawyer and Mexican War colonel; the house's first owner"}, {"name": "Augusta Roussell", "role": "Phelps's wife, from Louisiana (named in the National Register nomination)"}], "sources": [{"title": "National Register of Historic Places Inventory-Nomination Form: Abner Phelps House", "publisher": "National Park Service", "year": 1971, "url": "https://npgallery.nps.gov/GetAsset/767f3ec8-efbd-4257-a9aa-f64bca198257/", "supports": "'Oldest unaltered residence'; 1850-51; 1934 and 1961 accounts; Louisiana features; Phelps living there in 1851; city limits"}, {"title": "San Francisco Landmark #32: Abner Phelps House", "publisher": "NoeHill in San Francisco (quoting the Landmarks Preservation Advisory Board case report, 1969)", "year": 2003, "url": "https://noehill.com/sf/landmarks/sf032.asp", "supports": "Landmark #32 case report text on the 1934 Maine-lumber account"}, {"title": "The history and many origin stories of San Francisco's oldest home", "publisher": "SFGATE (Andrew Chamings)", "year": 2024, "url": "https://www.sfgate.com/obscuresf/article/SF-oldest-house-for-lease-17222878.php", "supports": "1907 Call interview; 1970s UC Berkeley redwood analysis"}, {"title": "San Francisco music mogul buys city's oldest house at 1111 Oak Street", "publisher": "San Francisco Chronicle", "year": 2024, "url": "https://www.sfchronicle.com/sf/article/abner-phelps-house-sale-19731884.php", "supports": "2024 sale; 'widely believed to be the city's oldest house'"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/c/c1/Abner_Phelps_House_%28San_Francisco%29.JPG", "page": "https://commons.wikimedia.org/wiki/File:Abner_Phelps_House_(San_Francisco).JPG", "credit": "Sanfranman59 / Wikimedia Commons", "license": "CC BY-SA 3.0", "year": 2008}}, {"id": "origins-phelps-homestead", "theme": "origins", "title": "A Homestead With a Duck-Hunting Lake", "year": 1851, "yearEnd": 1904, "place": "Abner Phelps House, 1111 Oak Street", "precision": "building", "c": [759.4, 1113.7], "block": "1218", "hook": "Abner Phelps rode his horse to a downtown law office from a 160-acre homestead with its own lake. As the grid closed in, his family kept moving the house.", "story": "In the 1850s the Phelps house stood in the middle of a 160-acre homestead at the foot of Buena Vista Hill. Part of today's Panhandle belonged to it [1]. Abner Phelps kept a law office in the Montgomery Block downtown. The National Register nomination says he made \"a long dusty journey to town daily by horseback\", when Divisadero was \"no more than a path\" [1].\n\nA 1907 San Francisco Call profile, quoted by SFGATE, described a ranch lake, 100 feet deep, \"for the boys who were devoted to swimming and duck-hunting\" [2]. The Call said it flooded in heavy rain. After one flood, a neighbour's piano and a barrel of his whiskey \"were found out in the Mission\" [2].\n\nWhen Divisadero was graded in the 1890s, the house was repositioned, and in 1904 it was moved back to the middle of the block so the family could build stores on Divisadero [1][3]. SFGATE reports that two Phelps sisters ran a haberdashery there. The house could only be reached by a 75-foot alley, and Phelps's son Walter told the Call: \"It has cost us more than building a new house, but we like to keep the old place\" [2]. His brother George lived there until he died in 1940. The house was turned to face Oak Street in 1977 [2].", "people": [{"name": "Abner Phelps", "role": "Lawyer and homesteader"}, {"name": "Walter Phelps", "role": "Son, quoted on moving the house in 1904"}, {"name": "George Phelps", "role": "Son, last Phelps to live in the house (died 1940)"}], "sources": [{"title": "National Register of Historic Places Inventory-Nomination Form: Abner Phelps House", "publisher": "National Park Service", "year": 1971, "url": "https://npgallery.nps.gov/GetAsset/767f3ec8-efbd-4257-a9aa-f64bca198257/", "supports": "160-acre homestead; Panhandle; Montgomery Block office; horseback commute; Divisadero a path; moves in the 1890s and 1904"}, {"title": "The history and many origin stories of San Francisco's oldest home", "publisher": "SFGATE (Andrew Chamings)", "year": 2024, "url": "https://www.sfgate.com/obscuresf/article/SF-oldest-house-for-lease-17222878.php", "supports": "1907 Call quotations on the lake, flood and Walter Phelps; haberdashery; alley; George Phelps; 1977 move"}, {"title": "San Francisco Landmark #32: Abner Phelps House", "publisher": "NoeHill in San Francisco (quoting the Landmarks Preservation Advisory Board case report, 1969)", "year": 2003, "url": "https://noehill.com/sf/landmarks/sf032.asp", "supports": "1890s repositioning and 1904 move to build stores on Divisadero"}], "photo": null}, {"id": "origins-sans-souci-roadhouse", "theme": "origins", "title": "The Roadhouse by a Vanished Lake", "year": 1853, "yearEnd": null, "place": "Near Fulton and Divisadero streets (site of 1333 Fulton St)", "precision": "block", "c": [787.9, 684.8], "block": "1182", "hook": "On the old Mission-to-Presidio trail stood the San Souci roadhouse, a refuge from the wind beside a lake that may have washed away in one night.", "story": "Where Fulton meets Divisadero today, early travellers found a roadhouse. Historian Joel Pomerantz found a building at this spot on an 1853 map by City Surveyor Clement Humphreys. It stood on the city line of the time, now Divisadero Street, beside the dotted trail from the Mission to the Presidio [1]. It was the San Souci roadhouse, a refuge from the wind in sandy, hard country [1].\n\nThe best-known description comes from journalist Edward Morphy, writing around 1919: \"probably the best known landmark of Divisadero street in the pioneer days was the old San Souci roadhouse which stood on the east side of a pretty little lake that then filled the space from Fulton to about midway between Hayes and Fell streets\" [2]. Morphy said the lake broke its sandy banks in the very wet winter of 1861-62 and mostly drained away down the valley. Pomerantz points out that the lake rests on Morphy's word alone, and that parts of the flood story don't add up [2].\n\nMuch altered, the roadhouse survived until the 1920s [1]. Historian Joe Pecora counts it among the neighbourhood's lost landmarks [3]. Pomerantz found a reference crediting the roadhouse as the source of the name San Souci Valley, used for the Lower Haight and Panhandle area until about the 1920s [1].", "people": [{"name": "Edward Morphy", "role": "Journalist whose c. 1919 columns described the roadhouse and lake"}, {"name": "Clement Humphreys", "role": "City surveyor whose 1853 map shows the building"}], "sources": [{"title": "San Souci Roadhouse", "publisher": "Thinkwalks (Joel Pomerantz)", "year": 2010, "url": "http://thinkwalks.org/2010/12/03/san-souci-roadhouse/", "supports": "1853 Humphreys map showing the building on the city line and trail; San Souci Valley name; demolition in the 1920s"}, {"title": "The San Souci Lake-Pioche Mystery", "publisher": "Thinkwalks (Joel Pomerantz)", "year": 2010, "url": "https://thinkwalks.org/2010/10/19/the-san-souci-lake%E2%80%93pioche-mystery/", "supports": "Morphy quotation; 1861-62 overflow; lake attested only by Morphy; site at 1333 Fulton"}, {"title": "Alamo Square and the families who lived there", "publisher": "The New Fillmore (Joe Pecora)", "year": 2014, "url": "https://newfillmore.com/2014/10/03/alamo-square-and-the-families-who-lived-there/", "supports": "Pecora lists the Sans Souci Roadhouse among the demolished landmarks of the Alamo Square neighbourhood"}], "photo": null}, {"id": "origins-orphan-asylum", "theme": "origins", "title": "Thirty Children in the Middle of Nowhere", "year": 1854, "yearEnd": 1919, "place": "Haight and Laguna streets (south side, the former asylum grounds)", "precision": "block", "c": [1761.9, 1334.8], "block": "0851", "hook": "In 1854 a group of San Francisco women moved thirty orphans into a stone building among the sandhills, two blocks they had bought for $100.", "story": "In 1851 several San Francisco women, most of them wives of Protestant clergymen, formed the San Francisco Orphan Asylum Society to care for children whose parents had died in an epidemic [1]. They soon needed a permanent home. Their own history describes the land they found as \"far beyond the city limits and basically in the middle of nowhere\" [2]. They bought two blocks bounded by today's Laguna, Hermann, Buchanan and Haight streets for $100 [2][3].\n\nThey raised building money by going door to door and still had to borrow $5,000 [2]. The masonry dormitory went up in 1853-54, from stone quarried on nearby Mint Hill [3][4]. It opened on March 22, 1854, and about thirty children and staff moved in [1][2]. \nThe asylum took in more than 3,500 children in its first fifty years, and at its peak housed as many as 300 [1]. By the 1890s the children went to local public schools [2]. The building was damaged in 1906, and in 1919 the children moved out [2]. The site later became a state teachers' college, then the UC Berkeley Extension campus at 55 Laguna [3][4].", "people": [{"name": "Elizabeth Waller", "role": "Founding leader of the orphan asylum society"}], "sources": [{"title": "Edgewood - Former Protestant Orphanage", "publisher": "Western Neighborhoods Project (outsidelands.org)", "year": null, "url": "https://www.outsidelands.org/edgewood.php", "supports": "1851 founding by clergymen's wives; about thirty children moved in March 1854; 3,500 children; up to 300 residents"}, {"title": "The Old 55 Laguna: San Francisco's Orphan Asylum", "publisher": "Hoodline", "year": 2012, "url": "https://hoodline.com/2012/07/the-old-55-laguna-san-franciscos-orphan-asylum/", "supports": "'Middle of nowhere'; $100 land; door-to-door fundraising and $5,000 loan; March 22, 1854 opening; public schools; 1919 move"}, {"title": "Naming of Haight Street, Part 4: The Last Haight Standing", "publisher": "FoundSF (Angus MacFarlane)", "year": 2017, "url": "https://www.foundsf.org/Naming_of_Haight_Street,_Part_4:_The_Last_Haight_Standing", "supports": "Asylum boundaries; stone quarried at Mint Hill; later UC Extension site"}, {"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area", "publisher": "Page & Turnbull for the San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Masonry building 1853-54; later San Francisco State Teachers College site"}], "photo": null}, {"id": "origins-alamo-cottonwood", "theme": "origins", "title": "A Lone Cottonwood Marked the Water", "year": 1856, "yearEnd": null, "place": "Alamo Square (Hayes, Steiner, Fulton and Scott streets)", "precision": "area", "c": [1105.9, 790.6], "block": "0799", "hook": "Before the Painted Ladies, before streets, the hilltop was a trailside watering hole marked by a single tree. That tree gave Alamo Square its name.", "story": "Long before anyone called it a square, the hill at the centre of this map was Alamo Hill. According to the San Francisco Parks Alliance, in the early 1800s a lone cottonwood on the hill marked a watering hole on the horseback trail between Mission Dolores and the Presidio [1]. Álamo is Spanish for poplar. Hoodline's history says the name most likely came from poplar trees on the land, and calls the hill a stopping point on the trail [2].\n\nThe Gold Rush city soon spread toward the hill. In 1856 Mayor James Van Ness set aside 12.7 acres around the watering hole and named it Alamo Square, and the state legislature confirmed it as a public park the following year [1][3]. City records from 1857 describe the reservation as \"Alamo, bounded by Hayes, Steiner, Fulton and Scott streets\", the same four streets that frame the park today [2].\n\nFor decades the reservation stayed what Hoodline calls \"little more than a rocky knoll\", far from the city's edge [2]. The cottonwood is long gone, but the Spanish name for it has stuck to the hill, the park and the whole neighbourhood.", "people": [{"name": "James Van Ness", "role": "Mayor of San Francisco who set the square aside in 1856"}], "sources": [{"title": "Alamo Square (park history page, archived)", "publisher": "San Francisco Parks Alliance", "year": 2015, "url": "https://web.archive.org/web/2015/http://www.sfparksalliance.org/our-parks/parks/alamo-square", "supports": "Lone cottonwood, watering hole on Mission Dolores-Presidio trail; 1856 reservation of 12.7 acres; legislature confirmation"}, {"title": "Alamo Square: From 'Primeval Forest Of Rocks' To Iconic Park", "publisher": "Hoodline", "year": 2015, "url": "https://hoodline.com/2015/06/alamo-square-park/", "supports": "Stopping point on the trail; name likely from poplar trees; 1857 reservation wording; rocky knoll"}, {"title": "Park History", "publisher": "Alamo Square Neighborhood Association", "year": 2024, "url": "https://alamosquare.org/park-history/", "supports": "Same account of the cottonwood, the 1856 reservation and the 1857 confirmation"}], "photo": null}, {"id": "origins-haight-waller-names", "theme": "origins", "title": "Haight Street Was Named for a Woman", "year": 1856, "yearEnd": null, "place": "Haight Street at Laguna", "precision": "street", "c": [1759.8, 1285.4], "block": "0851", "hook": "Plaques credit a banker or a governor. The only first-hand account says Haight and Waller streets honoured two women who ran the orphan asylum.", "story": "Ask who Haight Street is named for and you may hear a banker, Henry W. Haight, or a governor, Henry H. Haight. A mural and a plaque in the Haight-Ashbury name one man each [1]. Local historian Angus MacFarlane argues that both are wrong.\n\nWeltha Ann Buell Haight arrived in San Francisco on December 6, 1852. Within months she was on the board and the building committee of the Protestant Orphan Asylum, alongside its founding leader, Elizabeth Waller [1][2]. The asylum's two blocks were first mapped on a paper street plan. When the Western Addition was resurveyed in 1855-56, those blocks ended up bounded by a new Haight Street to the north, with a new Waller Street running through them [2].\n\nThe only first-hand explanation comes from Weltha herself, in a pamphlet dated May 1, 1900. Once the land had been surveyed, she wrote, \"out of compliment to two of the Managers, Waller street and Haight street were named\" [1][2]. In 1928 a Chronicle writer heard the same story from the asylum's secretary and brushed it aside, suggesting the streets were more likely named for the women's husbands [1]. That version is the one that stuck. MacFarlane notes there is no record that Henry Haight gave the land [2].", "people": [{"name": "Weltha Ann Buell Haight", "role": "Orphan asylum manager for whom Haight Street was named, by her own account"}, {"name": "Elizabeth Waller", "role": "Orphan asylum leader, namesake of Waller Street"}, {"name": "Angus MacFarlane", "role": "Historian who researched the naming"}], "sources": [{"title": "Local Herstory: Who Is Haight St. Really Named After?", "publisher": "Hoodline", "year": 2017, "url": "https://hoodline.com/2017/08/local-herstory-who-is-haight-st-really-named-after/", "supports": "Competing plaques; Weltha's biography and board roles; her 1900 memoir quotation; 1928 Chronicle dismissal"}, {"title": "Naming of Haight Street, Part 4: The Last Haight Standing", "publisher": "FoundSF (Angus MacFarlane)", "year": 2017, "url": "https://www.foundsf.org/Naming_of_Haight_Street,_Part_4:_The_Last_Haight_Standing", "supports": "December 6, 1852 arrival; building committee; resurvey and street renaming; memoir; no record of a land donation"}], "photo": null}, {"id": "origins-western-addition-grid", "theme": "origins", "title": "Streets Drawn on Sand", "year": 1856, "yearEnd": null, "place": "Linden Street, Hayes Valley", "precision": "street", "c": [1965.2, 942.4], "block": "0818", "hook": "In 1856 three commissioners drew a grid across empty dunes west of Larkin Street. Their plan created the Western Addition, and its odd tree-named alleys.", "story": "In the early 1850s the land west of Larkin Street was dunes, scrub and conflicting land claims. The Van Ness Ordinance of 1855 settled those claims largely in favour of squatters. Anyone in actual possession of land on or before January 1, 1855 got title. A new map then set out the streets and reserved lots for parks, schools and hospitals [1].\n\nOn November 12, 1855, the city council named Horace Hawes, Michael Hayes and Charles Gough to \"lay off the streets in the Western Addition\" [2]. They reported on April 21, 1856, having made \"a patient and thorough examination of the land\" [2]. Only four street names from earlier, unofficial surveys survived into the new era, Webster, Laguna, Haight and Hays, and three of those were moved to new lines [2].\n\nThe southern Western Addition came out with a quirk you can still walk through. Many blocks are cut in half by narrow east-west streets named for plants, such as Ivy, Linden, Rose and Hickory [3]. That created \"through blocks\" whose lots, often 25 feet by 120, front two streets. Builders put a house at each end, stretched one building between both frontages, or put stables at the back [3]. Linden Street is one of those alleys.", "people": [{"name": "Horace Hawes", "role": "Street commissioner, 1855-56"}, {"name": "Michael Hayes", "role": "Street commissioner, brother of Thomas Hayes"}, {"name": "Charles Gough", "role": "Street commissioner, 1855-56"}], "sources": [{"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area", "publisher": "Page & Turnbull for the San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Van Ness Ordinance terms (possession by January 1, 1855); Van Ness Map reservations; 1856 platting of the Western Addition"}, {"title": "Naming of Haight Street, Part 4: The Last Haight Standing", "publisher": "FoundSF (Angus MacFarlane)", "year": 2017, "url": "https://www.foundsf.org/Naming_of_Haight_Street,_Part_4:_The_Last_Haight_Standing", "supports": "November 12, 1855 commission; April 21, 1856 report quotation; four surviving street names"}, {"title": "Hayes Valley Residential Historic District Update (DPR 523D District Record)", "publisher": "Page & Turnbull / San Francisco Planning Department", "year": 2008, "url": "https://sfplanning.org/sites/default/files/documents/preserv/DPRforms/DPR%20523D_Hayes%20Valley%20Residential%20Update%206_6_08.pdf", "supports": "Botanical half-block streets; through blocks; lot sizes; how builders used them"}], "photo": null}, {"id": "origins-sixteen-dollar-lots", "theme": "origins", "title": "Lots for Sixteen Dollars Apiece", "year": 1859, "yearEnd": 1861, "place": "Near Oak and Webster streets", "precision": "block", "c": [1531.7, 1078.1], "block": "0828", "hook": "When Hayes first sold his valley, a 25-foot lot cost sixteen dollars. A banker nicknamed Big John bought a stack of them and built a farm-like estate.", "story": "Thomas Hayes surveyed and subdivided his tract in three rounds, in 1859, 1860 and 1861 [1][2]. At first he sold whole blocks to speculators, who waited for demand to catch up [1]. The prices look unreal now. A 1928 Chronicle history said that \"cabin lots of 25-foot frontage were sold by Hayes at $16 each\", even after the city limits had moved out past them [3].\n\nOne early buyer was \"Big John\" Sullivan, president of the Hibernia Loan and Savings Society. He bought a number of 25-foot lots at $16 apiece [1][2]. Near Oak and Webster streets, at the western edge of the Hayes tract, he built a large frame house with extensive gardens, a stable and a henhouse [1]. Mayor James Van Ness also built himself a villa somewhere in Hayes Valley [1][2]. Sullivan's house is long gone.\n\nThe streets were laid out but mostly ungraded and unpaved; an 1860s lithograph shows how raw it was [2]. The valley filled in quickly anyway. By 1869 the U.S. Coast Survey map showed its core built up along Hayes Street, reaching about a block north to Grove and south to Fell [1].", "people": [{"name": "John Sullivan (\"Big John\")", "role": "President of the Hibernia Loan and Savings Society; early lot buyer"}, {"name": "Thomas Hayes", "role": "Subdivider of the Hayes tract"}, {"name": "James Van Ness", "role": "Mayor who built a villa in Hayes Valley"}], "sources": [{"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area", "publisher": "Page & Turnbull for the San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Surveys of 1859-61; block sales to speculators; Sullivan's $16 lots and estate near Oak and Webster; Van Ness villa; 1869 Coast Survey"}, {"title": "Hayes Valley Residential Historic District Update (DPR 523D District Record)", "publisher": "Page & Turnbull / San Francisco Planning Department", "year": 2008, "url": "https://sfplanning.org/sites/default/files/documents/preserv/DPRforms/DPR%20523D_Hayes%20Valley%20Residential%20Update%206_6_08.pdf", "supports": "Surveys; Sullivan; Van Ness villa; ungraded streets and 1860s lithograph"}, {"title": "Hayes Valley In The 1860s: A Day Trip To The Hayes Park And Pavilion", "publisher": "Hoodline", "year": 2014, "url": "https://hoodline.com/2014/07/hayes-valley-in-the-1860s-a-day-trip-to-the-hayes-park-and-pavilion/", "supports": "Fitzhamon's 1928 quotation on $16 cabin lots"}], "photo": null}, {"id": "origins-goodall-captain", "theme": "origins", "title": "The Captain Who Carried Dutch Charley Away", "year": 1859, "yearEnd": null, "place": "Pierce and McAllister streets", "precision": "block", "c": [1121.7, 603.9], "block": "0778", "hook": "In 1856 tugboat captain Charles Goodall carried the banished Dutch Charley Duane out to an exile ship. Goodall later built a mansion on this corner.", "story": "In June 1856 San Francisco's Vigilance Committee banished Charles \"Dutch Charley\" Duane. The man who carried him from the wharf to the steamer Golden Age was Charles Goodall, master of the steam tug Hercules [1]. Duane did not forget it. Duane later sued Goodall for damages, first asking $25,000 and later $2,000. In 1862, according to the Daily Alta California, Judge Hoffman ruled that the tug itself was not liable, so any judgment could only fall on Goodall personally [1].\n\nGoodall did well for himself. He founded the Pacific Coast Steamship Company, whose ships called at ports from Alaska to San Diego [1]. His home stood at Pierce and McAllister streets, a block or two east of the land Duane squatted on. A 2017 Planning Department report dates the Goodall mansion to 1859 [2]. Accounts of his estate in 1899 place the \"home place\" on the west side of Pierce between Fulton and McAllister, and list a large improved lot on the southeast corner of Pierce and McAllister [1].\n\nThe mansion is gone. In 1950 Third Baptist Church, founded in 1852, bought the corner and built its present church there in 1952 [2]. Historian Joe Pecora counts the Goodall Mansion among the neighbourhood's lost landmarks [3].", "people": [{"name": "Charles Goodall", "role": "Tugboat master, later steamship magnate"}, {"name": "Charles P. \"Dutch Charley\" Duane", "role": "Exile who sued him"}], "sources": [{"title": "Captain Charles Goodall", "publisher": "The Maritime Heritage Project (transcribing the Daily Alta California, 1862, and San Francisco Call, 1899)", "year": null, "url": "https://www.maritimeheritage.org/captains/Charles-Goodall.html", "supports": "Daily Alta report of the Duane v. Goodall suit (tug Hercules, Golden Age, damages, Judge Hoffman); Pacific Coast Steamship Company; 1899 will and estate inventory"}, {"title": "Landmark Designation Case Report: Third Baptist Church Complex, 1399 McAllister Street", "publisher": "San Francisco Planning Department", "year": 2017, "url": "https://commissions.sfplanning.org/hpcpackets/2017-004024DES_071917.pdf", "supports": "'Former mansion of Charles Goodall (built 1859)' at Pierce and McAllister; church purchase in 1950 and construction in 1952"}, {"title": "Alamo Square and the families who lived there", "publisher": "The New Fillmore (Joe Pecora)", "year": 2014, "url": "https://newfillmore.com/2014/10/03/alamo-square-and-the-families-who-lived-there/", "supports": "Pecora lists the Goodall Mansion among the neighbourhood's demolished landmarks"}], "photo": null}, {"id": "origins-hayes-steam-railroad", "theme": "origins", "title": "A Steam Train Against the Sand", "year": 1860, "yearEnd": null, "place": "Hayes Street between Octavia and Laguna", "precision": "street", "c": [1954.9, 923.6], "block": "0818", "hook": "On July 4, 1860, steam trains began running out Market Street toward Hayes Valley. Blowing sand beat the engines, and horses took over.", "story": "Thomas Hayes knew his lots would only sell if people could reach them. In 1857 he got a franchise from the state legislature for a steam railroad along Market Street, with a spur six blocks out Hayes Street to his pleasure garden, Hayes Park [1][2]. It followed roughly the route of today's 21-Hayes bus [1].\n\nThe Market Street line opened with steam dummies on July 4, 1860, running from Third and Kearny out Market Street toward the Mission [3]. Planners say the Hayes line was completed the same year [1][2]. The dunes fought back from the start. Drifting sand covered the tracks, and the operators planted windbreaks of brush and scrub oak [1]. Grit still wore out the engines. After public complaints about the steam dummies, the company switched to horses on March 6, 1867 [1][3].\n\nIn a 1948 Examiner column, Dick Nolan said the old-timers \"thought Hayes' newfangled contraption was downright effeminate\" and would rather walk or ride [4]. Hayes ran into money trouble and lost the franchise, and the line became part of the Market Street Railway [2][4]. It had done its job, though. Planners say the investment paid off, and building took off in Hayes Valley during the 1860s [1][2].", "people": [{"name": "Thomas Hayes", "role": "Holder of the 1857 railroad franchise"}, {"name": "Dick Nolan", "role": "Examiner columnist who retold the line's history in 1948"}], "sources": [{"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area", "publisher": "Page & Turnbull for the San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "1857 franchise; spur to Hayes Park; 21-Hayes route; sand, windbreaks, engines; horse cars in 1867; building boom"}, {"title": "Hayes Valley Residential Historic District Update (DPR 523D District Record)", "publisher": "Page & Turnbull / San Francisco Planning Department", "year": 2008, "url": "https://sfplanning.org/sites/default/files/documents/preserv/DPRforms/DPR%20523D_Hayes%20Valley%20Residential%20Update%206_6_08.pdf", "supports": "Franchise, six-block Hayes Street spur, completion in 1860, Market Street Railway takeover"}, {"title": "Market Street Cable Railway", "publisher": "The Cable Car Home Page (Joe Thompson)", "year": null, "url": "http://www.cable-car-guy.com/html/ccsfmsr.html", "supports": "Steam dummy opened July 4, 1860; replaced by horses March 6, 1867 after public complaints"}, {"title": "Hayes Valley In The 1860s: A Day Trip To The Hayes Park And Pavilion", "publisher": "Hoodline", "year": 2014, "url": "https://hoodline.com/2014/07/hayes-valley-in-the-1860s-a-day-trip-to-the-hayes-park-and-pavilion/", "supports": "Nolan's 1948 quotation; Hayes's financial trouble and loss of the franchise"}], "photo": null}, {"id": "origins-hayes-park", "theme": "origins", "title": "Colonel Hayes's Pleasure Garden", "year": 1864, "yearEnd": null, "place": "Near Hayes and Laguna streets", "precision": "block", "c": [1820.4, 878.9], "block": "0806", "hook": "To sell lots in a sandy hollow, Tom Hayes built a day-trip resort with a concert hall, gymnasium, shooting gallery and bar.", "story": "Thomas Hayes was an Irish-born politician who sailed for San Francisco in January 1849 with two of his brothers. He got a 160-acre tract through a preemption deed, in effect a squatter's claim, and the Van Ness Ordinance confirmed it in 1855 [1]. A 1928 Chronicle writer called him \"a rather picturesque but shrewd figure in early San Francisco politics and in state military affairs\" [2].\n\nFarming failed in the fog, wind and sand, so Hayes started selling his land for homes instead [1][3]. To bring buyers out, he opened what planners describe as a \"come-on\" attraction: Hayes Park, near today's Hayes and Laguna streets, with a picnic ground, restaurant and bar [3]. Sources give different opening dates. The city's context statement says around 1856, and other accounts say the early 1860s [1].\n\nBy 1864 the San Francisco Directory was advertising Hayes' Park, Pavilion and Garden as a \"suburban resort\" with a garden, concert hall, gymnasium and shooting gallery [2]. Townspeople made a day or half-day trip of it. A photograph of Hayes Valley taken that year shows the semicircular pavilion in the distance, with the Protestant Orphan Asylum in one corner [2].", "people": [{"name": "Thomas Hayes", "role": "Landowner, county clerk and developer of Hayes Valley"}], "sources": [{"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area", "publisher": "Page & Turnbull for the San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Hayes's arrival in 1849; preemption claim confirmed 1855; failed farming; pavilion around 1856 near Hayes and Laguna"}, {"title": "Hayes Valley In The 1860s: A Day Trip To The Hayes Park And Pavilion", "publisher": "Hoodline", "year": 2014, "url": "https://hoodline.com/2014/07/hayes-valley-in-the-1860s-a-day-trip-to-the-hayes-park-and-pavilion/", "supports": "Fitzhamon 1928 quotation; 1864 directory advertisement; day trips; 1864 photograph"}, {"title": "Hayes Valley Residential Historic District Update (DPR 523D District Record)", "publisher": "Page & Turnbull / San Francisco Planning Department", "year": 2008, "url": "https://sfplanning.org/sites/default/files/documents/preserv/DPRforms/DPR%20523D_Hayes%20Valley%20Residential%20Update%206_6_08.pdf", "supports": "'Come-on' attraction; picnic ground, restaurant and bar; location"}], "photo": null}, {"id": "origins-dutch-charley", "theme": "origins", "title": "Dutch Charley's Squatter Headquarters", "year": 1866, "yearEnd": null, "place": "Block bounded by Divisadero, Fulton, Scott and McAllister streets", "precision": "block", "c": [897.0, 592.1], "block": "1180", "hook": "Twice banished by vigilantes, fire chief Dutch Charley Duane ran a squatter operation from a cottage just west of Alamo Square, and killed a man over land.", "story": "Charles P. \"Dutch Charley\" Duane was a Gold Rush fireman, political enforcer and brawler. He was chief engineer of the volunteer fire department from 1853 to 1855 [1]. The Vigilance Committees banished him from the city in 1851 and again in 1856, threatening death if he came back. He returned early in 1860 anyway [2].\n\nIn a 1918 series, journalist Edward Morphy described how Charlie and his brother Jack built a little one-story cottage in the middle of the block bounded by Divisadero, Fulton, Scott and McAllister. From there, Morphy wrote, they hired \"desperadoes\" to defend \"various properties [they] unlawfully preempted from being taken over or built upon by their legitimate owners\" [3].\n\nColonel William G. Ross lived nearby, on the block bounded by Divisadero, McAllister, Broderick and today's Golden Gate Avenue [3]. On May 23, 1866, Duane shot Ross dead in a dispute over who owned a piece of land. He was tried in the 12th District Court and acquitted on October 31, 1866 [1]. The Parks Alliance's history of Alamo Square calls Duane \"a known killer and tenacious squatter\" and says the city finally ousted him from the land in 1868 [4]. He died in San Francisco on May 13, 1887 [1].", "people": [{"name": "Charles P. \"Dutch Charley\" Duane", "role": "Fireman, political enforcer and squatter"}, {"name": "Jack (John) Duane", "role": "His brother"}, {"name": "William G. Ross", "role": "Neighbour shot by Duane in a land dispute, 1866"}], "sources": [{"title": "SFFD Chiefs: Charles P. Duane", "publisher": "Guardians of the City (San Francisco Fire Department Museum)", "year": null, "url": "https://guardiansofthecity.org/sffd/chiefs/duane.html", "supports": "Chief engineer 1853-55; fatal shooting of Col. Wm. G. Ross on May 23, 1866; acquittal October 31, 1866; death May 13, 1887"}, {"title": "Book Review: Against the Vigilantes, edited by John Boessenecker", "publisher": "HistoryNet (Wild West magazine)", "year": null, "url": "https://historynet.com/book-review-against-the-vigilantes-edited-and-introduction-by-john-boessenecker-ww/", "supports": "Banishments of 1851 and 1856; return in 1860"}, {"title": "Alamo Square: From 'Primeval Forest Of Rocks' To Iconic Park", "publisher": "Hoodline", "year": 2015, "url": "https://hoodline.com/2015/06/alamo-square-park/", "supports": "Morphy's 1918 account of the cottage and 'desperadoes'; location of Ross's home"}, {"title": "Alamo Square (park history page, archived)", "publisher": "San Francisco Parks Alliance", "year": 2015, "url": "https://web.archive.org/web/2015/http://www.sfparksalliance.org/our-parks/parks/alamo-square", "supports": "'Dangerously inaccessible'; ousted in 1868"}], "photo": null}, {"id": "origins-nightingale-claim", "theme": "origins", "title": "The Forty-Niner Who Wanted the Park", "year": 1882, "yearEnd": null, "place": "Nightingale House, 201 Buchanan Street", "precision": "building", "c": [1674.5, 1390.9], "block": "0858", "hook": "John Nightingale, Forty-Niner and pioneer booster, tried to claim part of Alamo Square in court. He lost, and built himself a picturesque villa instead.", "story": "The city's title to Alamo Square was fought over in court for years. Hoodline, drawing on historian Joe Pecora and on Anne Bloomfield's 1983 research for the historic district, lists several claimants besides the Duane brothers. They included captain of detectives Isaiah W. Less, City Hall saloon keeper Michael Keeney and real estate man John Nightingale [1]. San Francisco's municipal reports record a ruling against Nightingale after he took the city to court. In 1918 journalist Edward Morphy credited a line of city attorneys with saving the park from such claims [1].\n\nLosing did not slow Nightingale down. He was a Forty-Niner, real estate dealer and property manager, and served as president of the Society of California Pioneers [2]. He built speculative housing in Hayes Valley [3]. In 1882 he took a large lot on the west side of Buchanan Street between Laussat and Waller and built a Stick/Eastlake villa designed by John Marquis [3]. Its large lot and picturesque shape set it apart from the row houses around it [3].\n\nThe Landmarks Board noted that this \"cottage\" is all that remains of Nightingale's extensive holdings in the area [2]. It is now San Francisco City Landmark No. 47 [2][3].", "people": [{"name": "John Nightingale", "role": "Forty-Niner, developer and claimant to Alamo Square land"}, {"name": "Isaiah W. Less", "role": "Captain of detectives and claimant"}, {"name": "Michael Keeney", "role": "City Hall saloon keeper and claimant"}, {"name": "John Marquis", "role": "Architect of the Nightingale House"}], "sources": [{"title": "Alamo Square: From 'Primeval Forest Of Rocks' To Iconic Park", "publisher": "Hoodline", "year": 2015, "url": "https://hoodline.com/2015/06/alamo-square-park/", "supports": "Claimants Less, Keeney and Nightingale (after Pecora and Bloomfield); ruling against Nightingale; Morphy on city attorneys"}, {"title": "San Francisco Landmark #47: Nightingale House", "publisher": "NoeHill in San Francisco (quoting the Landmarks Preservation Advisory Board)", "year": 2003, "url": "https://noehill.com/sf/landmarks/sf047.asp", "supports": "Built 1882; Forty-Niner, real estate dealer, Society of California Pioneers president; 'all that remains'; Landmark #47"}, {"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area", "publisher": "Page & Turnbull for the San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Speculative builder; 1882 lot on Buchanan between Laussat and Waller; John Marquis; Stick/Eastlake; Landmark No. 47"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/9/9f/Nightingale_House_San_Francisco.jpeg", "page": "https://commons.wikimedia.org/wiki/File:Nightingale_House_San_Francisco.jpeg", "credit": "Tfinc / Wikimedia Commons", "license": "CC BY-SA 3.0", "year": null}}, {"id": "institutions-mcmorry-lagan", "theme": "institutions", "title": "Gaslights Still Burning on Haight Street", "year": 1883, "yearEnd": 1983, "place": "188-198 Haight Street", "precision": "building", "c": [1862.4, 1289.9], "block": "0852", "hook": "Two Victorian houses and a barn stayed in one family for a century, with working gaslights, a copper bathtub and Army blankets from 1906.", "story": "At 188 and 198 Haight Street stand two single-family houses and a barn, built in 1883 and 1889 and kept by the same family for about a century, until 1983 [1]. One is Italianate with a mansard roof and Eastlake detail, and the other is fully Eastlake [1]. The real surprise is inside. The landmark record calls the interiors a virtual time capsule of late-19th-century life. The upstairs bedrooms still have working gaslights, and the kitchen and baths keep their original fixtures, including a copper bathtub, along with the original carpets, wallpaper and custom-made furniture [1]. Only partial electrification was ever added [1]. The houses also hold a memory of 1906. At 2:00 a.m. on April 19, as the fire spread west, the Lagan family was ordered to leave, and the flames were stopped two blocks to the east [1]. Soldiers from the Presidio then slept in the barn, and the landmark record says blankets marked 'U.S. Army' are still there [1]. The complex became city Landmark No. 164 on November 6, 1983, the same year the family's ownership ended [1][2].", "people": [{"name": "The Lagan family", "role": "owners for about a century"}], "sources": [{"title": "San Francisco Landmark #164: McMorry-Lagan Residence", "publisher": "NoeHill in San Francisco", "year": null, "url": "https://noehill.com/sf/landmarks/sf164.asp", "supports": "dates, styles, intact interiors, 1906 evacuation and Army blankets, century of ownership"}, {"title": "San Francisco Preservation Bulletin No. 9: San Francisco Landmarks", "publisher": "San Francisco Planning Department", "year": 2014, "url": "https://default.sfplanning.org/Preservation/bulletins/HistPres_Bulletin_09.PDF", "supports": "Landmark No. 164 (listed as McMorry-Lagen House), effective November 6, 1983"}], "photo": null}, {"id": "origins-yellow-green-cable-cars", "theme": "origins", "title": "Yellow Cars and Green Cars to the Park", "year": 1883, "yearEnd": 1886, "place": "McAllister cable powerhouse block (McAllister, Central, Fulton and Masonic)", "precision": "block", "c": [210.3, 512.4], "block": "1160", "hook": "In the 1880s, bright yellow cable cars on McAllister and green ones on Hayes turned a windy fringe into a place where the wealthy wanted to live.", "story": "Cable traction reached the Western Addition in 1883. That year the old horse-drawn Market Street Railway became the Market Street Cable Railway [1][2]. Its McAllister Street line opened in late 1883. It ran from the Ferry Building out Market and McAllister to Central Avenue, then crossed its own powerhouse block on a private right of way and continued out Fulton to Golden Gate Park [2]. The powerhouse and car barn filled most of the block bounded by Fulton, McAllister, Masonic and Central [1].\n\nOn May 26, 1886, a Hayes Street line followed. It had its own powerhouse and a 33-car barn very near the McAllister plant [1][2]. Each line had its own colour, so riders could spot their car on crowded Market Street. McAllister cars were bright yellow, Hayes cars green and Haight Street cars red [1].\n\nThe effect on the neighbourhood was fast. Historian Joe Pecora writes that the 1880s building boom around Alamo Square \"coincided with the arrival of the cable and horse cars down Hayes and McAllister Streets\" [3]. The Planning Department credits the cable car with drawing the wealthy to the park's views and weather [4]. The McAllister powerhouse later served as a streetcar barn until 1948 [2].", "people": [], "sources": [{"title": "The Market Street Cable Railway - 1883", "publisher": "San Francisco Cable Car Museum", "year": null, "url": "http://www.cablecarmuseum.org/co-market-st.html", "supports": "Origin in the 1867 horsecar company; 1883 cable company; McAllister powerhouse block; Hayes line of May 26, 1886 with 33-car barn; car colours"}, {"title": "Market Street Cable Railway", "publisher": "The Cable Car Home Page (Joe Thompson)", "year": null, "url": "http://www.cable-car-guy.com/html/ccsfmsr.html", "supports": "McAllister line late 1883 and its route; Hayes line date; powerhouse at Hayes and Masonic; streetcar barn until 1948"}, {"title": "Alamo Square and the families who lived there", "publisher": "The New Fillmore (Joe Pecora)", "year": 2014, "url": "https://newfillmore.com/2014/10/03/alamo-square-and-the-families-who-lived-there/", "supports": "Pecora: 1880s building boom coincided with cable and horse cars on Hayes and McAllister"}, {"title": "Alamo Square Landmark District Historic Walking Tour Guide", "publisher": "San Francisco Planning Department", "year": null, "url": "https://default.sfplanning.org/Preservation/walking_tours/Walking_Tour_ALAMO_SQUARE.pdf", "supports": "Cable car from the 1880s attracted the wealthy to the park's views and weather"}], "photo": null}, {"id": "victorian-hinkel-house", "theme": "victorian", "title": "A Row-House Builder Builds for Himself", "year": 1885, "yearEnd": null, "place": "280 Divisadero Street (Charles L. Hinkel House)", "precision": "building", "c": [846.0, 1243.2], "block": "1238", "hook": "The Hinkels built rows of Italianate houses from Pacific Heights to Eureka Valley. For his own home, Charles Lewis Hinkel took a double lot and went big.", "story": "The Hinkel family built houses for four generations. Charles E. Hinkel, a German immigrant, set up as a residential builder in San Francisco. His son Charles Lewis Hinkel (1847–1908) carried on the trade, and later his three sons and a grandson did too. Rows of Hinkel-built Italianates still stand from Pacific Heights through the Western Addition to Eureka Valley [1]. Hoodline reports that the Hinkel brothers bought up lots, built well-made homes and sold them to middle- and upper-class buyers, and together put up hundreds of houses [2]. In 1885 Charles Lewis built his own house at 280 Divisadero, between Haight and Page, as one of the earliest buildings on the street [1][2]. He used a 50-by-137.5-foot lot, twice the standard 25-by-100, which left room for landscaping and a carriage house. The house rises four storeys in a transitional Second Empire style, finished even on its side and rear walls [1][2]. Hard times came later: a 4-inch concrete slab was poured over the hardwood floors, but brass speaking tubes linking the carriage house, kitchen and laundry still worked [2]. The house became a city landmark in 1988 [3].", "people": [{"name": "Charles Lewis Hinkel", "role": "builder, owner"}, {"name": "Charles E. Hinkel", "role": "his father, residential builder"}], "sources": [{"title": "San Francisco Landmark #190: Charles L. Hinkel House and Carriage House (adapted from Planning Commission Resolution 11390)", "publisher": "NoeHill", "year": 2023, "url": "https://noehill.com/sf/landmarks/sf190.asp", "supports": "Family of builders, four generations, Hinkel rows, lot size, carriage house, Second Empire"}, {"title": "All About The Charles L. Hinkel House, A Victorian Architect's Home", "publisher": "Hoodline (Nuala Sawyer)", "year": 2014, "url": "https://hoodline.com/2014/10/the-charles-l-hinkel-house-a-victorian-architect-s-home/", "supports": "1885, earliest on Divisadero, brothers built hundreds of houses, concrete slab, speaking tubes"}, {"title": "Preservation Bulletin No. 9: San Francisco Designated Landmarks", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://sfplanning.org/sites/default/files/documents/preserv/bulletins/HistPres_Bulletin_09.PDF", "supports": "Landmark No. 190, designated 1988"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/5/57/Charles_L._Hinkel_House_and_Carriage_House%2C_exterior%2C_San_Francisco_%28January_2024%29_01.jpg", "page": "https://commons.wikimedia.org/wiki/File:Charles_L._Hinkel_House_and_Carriage_House,_exterior,_San_Francisco_(January_2024)_01.jpg", "credit": "BriefEdits / Wikimedia Commons", "license": "CC BY-SA 4.0", "year": 2024}}, {"id": "institutions-mish-house", "theme": "institutions", "title": "The Milliner's House That Moved Around the Corner", "year": 1885, "yearEnd": 1975, "place": "1153 Oak Street", "precision": "building", "c": [737.3, 1119.8], "block": "1218", "hook": "Sarah Mish, a downtown milliner since 1854, had her $15,000 Stick-Eastlake house moved off its Divisadero corner and onto Oak Street.", "story": "From 1854 Sarah Mish ran a dressmaking and millinery business downtown, moving between premises on Kearny, Geary, Market and Dupont Streets, and she also sold wholesale along the coast [1]. Her husband Phenes imported dry goods and was president of Congregation Sherith Israel from 1881 to 1885 [1]. In 1885 the couple built a Stick-Eastlake house on the corner of Oak and Divisadero, designed by McDougall and Son at a cost of $15,000, and the city directory listed them at 407 Divisadero [1]. Phenes died in 1895. In 1897 Sarah had the house moved onto another lot she owned on Oak Street, at a cost of $1,700, and shops and flats went up on the old corner. Some later accounts date the move to 1889 [1][2]. Sarah died on January 2, 1916, and her heirs sold the house in 1928 [1]. It became a rooming house, then as many as 14 apartments, and part of it housed a dance school in 1930 [1][2]. Along the way it lost its mansard roof, and it was damaged by a fire in the 1950s [1]. The city made it Landmark No. 62 in 1974 [3]. The next year the Preservation Group restored it, fitting fifty new windows and restoring its 14-foot ceilings [1].", "people": [{"name": "Sarah Mish", "role": "milliner and dressmaker, owner"}, {"name": "Phenes Mish", "role": "dry-goods importer, president of Congregation Sherith Israel"}, {"name": "McDougall and Son", "role": "architects"}], "sources": [{"title": "National Register of Historic Places Inventory-Nomination Form: Mish House", "publisher": "National Park Service", "year": 1979, "url": "https://npgallery.nps.gov/NRHP/GetAsset/NRHP/79000534_text", "supports": "Mish family, 1885 cost and architect, 1897 move and cost, 1916 death, 1928 sale, apartments, 1950s fire, 1975 restoration"}, {"title": "All About The Mish House At 1153 Oak Street", "publisher": "Hoodline", "year": 2014, "url": "https://hoodline.com/2014/09/the-mish-house-of-oak-street/", "supports": "1930 dance school; alternative 1889 move date"}, {"title": "San Francisco Preservation Bulletin No. 9: San Francisco Landmarks", "publisher": "San Francisco Planning Department", "year": 2014, "url": "https://default.sfplanning.org/Preservation/bulletins/HistPres_Bulletin_09.PDF", "supports": "Landmark No. 62, effective July 6, 1974"}], "photo": null}, {"id": "origins-omnibus-powerhouse", "theme": "origins", "title": "The Engine House at Oak and Broderick", "year": 1889, "yearEnd": 1895, "place": "Oak and Broderick streets", "precision": "block", "c": [629.1, 1101.4], "block": "1219", "hook": "In 1889 a powerhouse at Oak and Broderick began pulling cables under two new lines to Golden Gate Park. Within six years both had been converted.", "story": "The Omnibus Railroad started in 1861 as a horse-car company. In 1889 it went into cable [1]. Two of its new lines met at Oak and Broderick streets, where the company built a powerhouse to drive their cables [1].\n\nThe Oak Street line opened in late 1889. It ran from Howard up 10th Street to Fell, jogged along Fell and Franklin, then ran straight out Oak Street and Stanyan to the Haight Street entrance of Golden Gate Park [1][2]. The Ellis Street line came out Ellis to Broderick, turned south to Oak and joined the same route to the park [1]. The cars gripped the cable from below with an Eppelsheimer bottom grip [1]. A photograph taken between 1889 and early 1894 shows Oak Street car No. 6 at the Stanyan terminal while crowds wait at the park gate [1].\n\nCable-car historian Joe Thompson argues that the company \"made the wrong choice\" in picking cable over electricity, since only the Oak Street line had significant hills [1]. The Market Street Railway took over the Omnibus company on August 13, 1893, and the Oak and Ellis lines were converted in late 1895 [1]. By 1890 cable cars ran on Market, Hayes, Oak and Haight streets, and planners say such lines \"ushered in waves of new construction\" [2].", "people": [], "sources": [{"title": "Omnibus Railroad & Cable Company", "publisher": "The Cable Car Home Page (Joe Thompson)", "year": null, "url": "http://www.cable-car-guy.com/html/ccsfomni.html", "supports": "1861 horse-car origins; Oak and Ellis routes; powerhouse at Oak and Broderick; bottom grip; photo; Thompson's assessment; 1893 takeover; 1895 conversion"}, {"title": "Hayes Valley Residential Historic District Update (DPR 523D District Record)", "publisher": "Page & Turnbull / San Francisco Planning Department", "year": 2008, "url": "https://sfplanning.org/sites/default/files/documents/preserv/DPRforms/DPR%20523D_Hayes%20Valley%20Residential%20Update%206_6_08.pdf", "supports": "Oak Street line opened 1889 by the Omnibus Railroad & Cable Company; route; cable lines on Market, Hayes, Oak and Haight by 1890"}], "photo": null}, {"id": "victorian-westerfeld-house", "theme": "victorian", "title": "The Many Lives of the 'Russian Embassy'", "year": 1889, "yearEnd": 1986, "place": "1198 Fulton Street (Westerfeld House), at Scott", "precision": "building", "c": [987.6, 650.6], "block": "0777", "hook": "A candy maker's mansion that became a Russian émigré club, a home for jazz musicians, and the place where Kenneth Anger filmed an occult movie.", "story": "In 1889 the German-born confectioner William Westerfeld had Henry Geilfuss build him a towered Stick-style Italian villa at Fulton and Scott [1][2]. Six years later the house passed to John Mahony of the Mahony Brothers building firm, who added a garage for his Stanley Steamer [1][2]. Mahony died in 1918, and about a decade later the house became a community centre for Russian émigrés. The ballroom turned into the Dark Eyes nightclub and the house picked up a nickname, the \"Russian Embassy\" [2][1]. After the club closed in the late 1930s, the apartments carved out of the house were rented for about two decades to African American jazz musicians [2][3]. In 1965 Charles Fracchia bought it and leased it to the filmmaker Kenneth Anger, who shot parts of \"Invocation of My Demon Brother\" there [2][4]. Anton LaVey came to the house often, and Tom Wolfe described it in 1968 as \"a great shambling old Gothic house, a freaking decayed giant\" [2][4]. Jim Siegel bought the house in 1986 and restored its Victorian interiors [4].", "people": [{"name": "William Westerfeld", "role": "confectioner, original owner"}, {"name": "Henry Geilfuss", "role": "architect"}, {"name": "John Mahony", "role": "builder, second owner"}, {"name": "Kenneth Anger", "role": "filmmaker and tenant"}, {"name": "Jim Siegel", "role": "owner and restorer from 1986"}], "sources": [{"title": "San Francisco Landmark #135: Westerfeld House", "publisher": "NoeHill", "year": 2008, "url": "https://noehill.com/sf/landmarks/sf135.asp", "supports": "1889, Geilfuss, Westerfeld, Mahony, Stanley Steamer garage, Russian Club and Dark Eyes"}, {"title": "This Alamo Square Victorian holds 100 years of SF counterculture history", "publisher": "SFGATE (Ana Leorne)", "year": 2020, "url": "https://www.sfgate.com/characters/article/This-Alamo-Square-Victorian-holds-100-years-of-SF-15651657.php", "supports": "Mahony purchase; Russian émigré centre and Dark Eyes; jazz musicians; Fracchia 1965; Anger lease and filming; Tom Wolfe quote"}, {"title": "Explore", "publisher": "Alamo Square Neighborhood Association", "year": 2025, "url": "https://alamosquare.org/explore/", "supports": "Russian club in the 1930s, haven for African American jazz musicians in the 1950s"}, {"title": "'Snaggletooth' fits right into Westerfeld House's horror heritage in SF", "publisher": "San Francisco Chronicle (Brandon Yu)", "year": 2018, "url": "https://www.sfchronicle.com/entertainment/article/Snaggletooth-fits-right-into-Westerfeld-13048440.php", "supports": "Anger lived there while filming; LaVey visits; Siegel bought 1986 and restored"}], "photo": null}, {"id": "victorian-green-apothecary", "theme": "victorian", "title": "The Toxicologist's Corner Drugstore", "year": 1889, "yearEnd": null, "place": "500–502 Divisadero Street (Theodore Green Apothecary), at Fell", "precision": "building", "c": [841.1, 972.6], "block": "1203", "hook": "Behind the owl-eyed oval windows at Divisadero and Fell, a pharmacist who later ran the coroner's poison tests counselled students and did target practice.", "story": "Samuel Newsom, the Queen Anne architect best known for the Carson Mansion in Eureka, designed this corner pharmacy in 1889. It is one of the few unaltered 19th-century storefronts left in San Francisco, and it became a city landmark in 1986 [1][4]. The business opened as Theodore Green and Son, and by 1896 the son, Frank T. Green, ran it [2]. Green was born in Nevada County in 1863 and graduated from the California College of Pharmacy in 1880. He rose to professor of pharmaceutical chemistry and was dean from 1909 to 1927. Along the way he worked as a toxicologist for the San Francisco coroner's office and counted John Muir as a friend [3]. Former students remembered him breaking off a lecture to shout \"OPEN THE WINDOWS!\" [2]. A trade journal described the shop as a \"little laboratory\" where he examined precious stones or practised with his revolver [2]. Green's Pharmacy stayed in business for decades. When a Burger King tried to take the corner, neighbours fought it off, and Madrone opened in the space in 2004. The tiled \"Green's Pharmacy\" doorway is still there [2].", "people": [{"name": "Franklin Theodore (Frank T.) Green", "role": "pharmacist, dean, coroner's toxicologist"}, {"name": "Samuel Newsom", "role": "architect"}], "sources": [{"title": "San Francisco Landmark #182: Theodore Green Apothecary", "publisher": "NoeHill", "year": 2008, "url": "https://noehill.com/sf/landmarks/sf182.asp", "supports": "1889; Samuel Newsom; rare unaltered storefront"}, {"title": "Poison! Murder! Car Chase! The History Of Divisadero's Green's Pharmacy", "publisher": "Hoodline", "year": 2016, "url": "https://hoodline.com/2016/03/poison-murder-car-chase-the-history-of-divisadero-s-green-s-pharmacy/", "supports": "Theodore Green and Son; Frank T. Green by 1896; student quote; 'little laboratory'; Burger King fight; Madrone 2004; tiles"}, {"title": "Dean Franklin T. Green", "publisher": "UCSF School of Pharmacy", "year": null, "url": "https://pharmacy.ucsf.edu/about/history/dean-franklin-green", "supports": "Born 1863 Nevada County; graduated 1880; dean 1909–1927; coroner's toxicologist; owned Green's Pharmacy at Divisadero and Fell; friend of John Muir"}, {"title": "Preservation Bulletin No. 9: San Francisco Designated Landmarks", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://sfplanning.org/sites/default/files/documents/preserv/bulletins/HistPres_Bulletin_09.PDF", "supports": "Landmark No. 182, 500–502 Divisadero, 1986"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/6/6a/Green%27s_Pharmacy%2C_July_2022_-1.jpg", "page": "https://commons.wikimedia.org/wiki/File:Green%27s_Pharmacy,_July_2022_-1.jpg", "credit": "HaeB / Wikimedia Commons", "license": "CC BY-SA 4.0", "year": 2022}}, {"id": "communities-old-st-patricks", "theme": "communities", "title": "The Church That Moved Twice", "year": 1891, "yearEnd": 1899, "place": "Old St. Patrick's Church / Holy Cross Parish Hall, 1820 Eddy St", "precision": "building", "c": [925.3, 224.3], "block": "1127", "hook": "The city's oldest wooden church started out on Market Street, where the Palace Hotel now stands. It was carted across town twice before it came to rest on Eddy Street.", "story": "The plain Classical Revival building on the north side of Eddy between Scott and Divisadero began life downtown, as St. Patrick's Church in Happy Valley on Market Street [1]. Its exact age is disputed. The parish historian Luke Carroll dated it to 1854 and said it was brought around the Horn in a sailing vessel. The Historic American Buildings Survey argued that it more likely dated to 1851, and another account gives 1852 [1][2]. The Palace Hotel was going up on its site, so in 1873 the church was moved to Eddy Street between Octavia and Laguna and reconsecrated as St. John the Baptist. From 1885 to 1891 Archbishop Riordan used it as his pro-cathedral [1]. When St. Mary's Cathedral opened on Van Ness in 1891, the little church moved again, this time to Eddy near Divisadero. It was rededicated on May 24, 1891 as the first home of Holy Cross Parish [1][2]. Holy Cross laid the cornerstone of a larger church next door on April 3, 1898 and dedicated it on August 13, 1899, under pastor Rev. John McGinty. The old building became the parish hall [2]. It was named San Francisco Landmark No. 6 in 1968 and is considered the oldest frame church building in the city [3][4].", "people": [{"name": "Archbishop Patrick Riordan", "role": "used the building as his pro-cathedral, 1885–1891"}, {"name": "Rev. John McGinty", "role": "pastor of Holy Cross"}, {"name": "Luke Carroll", "role": "Holy Cross parish historian"}], "sources": [{"title": "Holy Cross Parish Hall (Original St. Patrick's Church), HABS No. CAL-1908, Photograph-Data Book Report", "publisher": "Historic American Buildings Survey / Library of Congress", "year": null, "url": "https://tile.loc.gov/storage-services/master/pnp/habshaer/ca/ca0600/ca0655/data/ca0655data.pdf", "supports": "Origins on Market Street, the disputed dates, the 1873 and 1891 moves, the pro-cathedral years, becoming the parish hall in 1899"}, {"title": "Holy Cross Church: A Closer Look", "publisher": "OpenSFHistory / Western Neighborhoods Project", "year": 2017, "url": "https://www.opensfhistory.org/osfhcrucible/2017/02/06/holy-cross-church-a-closer-look/", "supports": "The 1852 date, rededication as Holy Cross on May 24, 1891, 1898 cornerstone, 1899 dedication, Rev. John McGinty"}, {"title": "San Francisco Landmark #6: Old St. Patrick's Church", "publisher": "NoeHill", "year": null, "url": "https://noehill.com/sf/landmarks/sf006.asp", "supports": "City Landmark No. 6"}, {"title": "Old St. Patrick's Church (San Francisco)", "publisher": "Wikipedia (pointer)", "year": null, "url": "https://en.wikipedia.org/wiki/Old_St._Patrick%27s_Church_(San_Francisco)", "supports": "Oldest frame church building in the city; landmark dates of 1968"}], "photo": null}, {"id": "origins-alamo-grading", "theme": "origins", "title": "Taming a Primeval Forest of Rocks", "year": 1892, "yearEnd": 1896, "place": "Alamo Square", "precision": "area", "c": [1114.5, 779.7], "block": "0799", "hook": "For decades the city's reserved square was bare rock. In 1892 the city spent $25,333 grading the hill, and in 1896 it added the masonry wall.", "story": "Saving Alamo Square from squatters did not make it a park. In 1918 journalist Edward Morphy recalled that the block stayed \"a primeval forest of rocks at the top of hill\" for decades [1]. The rock is still there. In 2018 historian Joel Pomerantz pointed to serpentinite bedrock showing in an open lot at 804 Steiner, part of a ridge of that rock [2].\n\nThe work finally began in 1892. According to Hoodline, the park was \"graded and tamed\" that year at a cost of $25,333 [1]. The Parks Alliance history says crews graded and landscaped the rocky hill, laid out the curving paths, and built stairways and a masonry wall [3]. Hoodline dates the wall to 1896 and credits it to the California Concrete Company [1].\n\nHouses were rising around the park at the same time. Across Steiner Street, the row of Queen Anne houses now called the Painted Ladies went up between 1892 and 1895, facing a view that Planning calls probably the most photographed view of Victorians in the world [4]. The trailside watering hole of the early 1800s had become a landscaped park at the centre of a new neighbourhood.", "people": [{"name": "Edward Morphy", "role": "Journalist who described the ungraded hill"}], "sources": [{"title": "Alamo Square: From 'Primeval Forest Of Rocks' To Iconic Park", "publisher": "Hoodline", "year": 2015, "url": "https://hoodline.com/2015/06/alamo-square-park/", "supports": "Morphy quotation; 1892 grading at $25,333; paths and stairs; 1896 wall by the California Concrete Company"}, {"title": "The San Souci Lake-Pioche Mystery", "publisher": "Thinkwalks (Joel Pomerantz)", "year": 2010, "url": "https://thinkwalks.org/2010/10/19/the-san-souci-lake%E2%80%93pioche-mystery/", "supports": "Pomerantz comment on serpentinite bedrock exposed at 804 Steiner"}, {"title": "Alamo Square (park history page, archived)", "publisher": "San Francisco Parks Alliance", "year": 2015, "url": "https://web.archive.org/web/2015/http://www.sfparksalliance.org/our-parks/parks/alamo-square", "supports": "1892 grading and landscaping, curving paths, stairways and masonry wall"}, {"title": "Alamo Square Landmark District Historic Walking Tour Guide", "publisher": "San Francisco Planning Department", "year": null, "url": "https://default.sfplanning.org/Preservation/walking_tours/Walking_Tour_ALAMO_SQUARE.pdf", "supports": "700 block of Steiner built 1892-1895; most-photographed view of Victorians"}], "photo": null}, {"id": "victorian-kavanaugh-postcard-row", "theme": "victorian", "title": "The Builder Who Lived Next Door", "year": 1892, "yearEnd": 1896, "place": "710–720 Steiner Street (Postcard Row)", "precision": "block", "c": [1272.1, 820.7], "block": "0803", "hook": "The world's most photographed row of Victorians began as one contractor's gamble: build three houses on spec, see if they sell, then finish the block.", "story": "Between 1892 and 1896, the contractor Matthew Kavanaugh developed the 700 block of Steiner Street, the uphill row facing Alamo Square that the world now calls Postcard Row [1][2]. He started with his own house on the corner at Grove Street in 1892. It is the biggest of the group and breaks the pattern of the other six [1][3]. According to a 2010 article quoted by SFGATE, once Kavanaugh's own place was done he built the three matching houses at the far end on spec. When those sold for around $8,000 apiece, he finished the strip in 1896 [1]. The result, 710 to 720 Steiner, is a matching run of houses, also nicknamed the Seven Sisters, with downtown rising behind them [1][4]. They started out as a builder's speculation, not as monuments. More than a century later the Alamo Square Neighborhood Association still credits Kavanaugh as their builder, and the row still houses locals [4].", "people": [{"name": "Matthew Kavanaugh", "role": "contractor and developer of Postcard Row"}], "sources": [{"title": "One of San Francisco's iconic Painted Ladies on Alamo Square could be yours for $5.75M", "publisher": "SFGATE (Anna Marie Erwert)", "year": 2022, "url": "https://www.sfgate.com/realestate/article/Iconic-Painted-Lady-for-sale-17009758.php", "supports": "Kavanaugh built the row; own house 1892; three houses on spec sold for about $8,000 each; row finished 1896; Seven Sisters"}, {"title": "Postcard Row's Postman's Home Hits The Market (722 Steiner)", "publisher": "SocketSite", "year": 2010, "url": "https://socketsite.com/archives/2010/02/722_steiner_postcard_rows_postmans_home_hits_the_market.html", "supports": "Kavanaugh developed the 700 block of Steiner 1892–1896; his own home at Steiner and Grove"}, {"title": "Painted Ladies' Corner Cousin Is Yours For $5.75M", "publisher": "The Front Steps", "year": 2022, "url": "https://thefrontsteps.com/2022/03/23/722-steiner-painted-ladies/", "supports": "722 breaks the pattern of the other six; same developer"}, {"title": "Explore", "publisher": "Alamo Square Neighborhood Association", "year": 2025, "url": "https://alamosquare.org/explore/", "supports": "Painted Ladies at 710–720 Steiner built by Kavanaugh 1892–1896; still house locals"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/8/8d/Painted_Ladies%2C_from_Alamo_Square_Park%2C_San_Francisco_%28September_2018%29.jpg", "page": "https://commons.wikimedia.org/wiki/File:Painted_Ladies,_from_Alamo_Square_Park,_San_Francisco_(September_2018).jpg", "credit": "Another Believer / Wikimedia Commons", "license": "CC BY-SA 4.0", "year": 2018}}, {"id": "victorian-chateau-tivoli", "theme": "victorian", "title": "The Opera Impresario's Chateau", "year": 1892, "yearEnd": 1985, "place": "1057 Steiner Street (Chateau Tivoli), at Golden Gate Avenue", "precision": "building", "c": [1244.7, 491.5], "block": "0775", "hook": "A lumber baron built it and an opera-house owner gave it her theatre's name. By the 1970s the towered house on Steiner rang with New Age drumming.", "story": "In 1892 the architect William H. Armitage designed a towered house at Steiner and Golden Gate for the lumber baron Daniel B. Jackson [1]. Jackson also built three apartment buildings next door on Golden Gate Avenue. All four were painted alike so they read as one huge facade, and together they were known as the Seattle Block [1]. Jackson later sold the house to Ernestine Kreling, founder and owner of the Tivoli Opera House on Eddy Street, and the house still carries the Tivoli name [1]. By the 1970s the house had become a New Age centre, \"bringing drum beats and chanting to its halls\" [1]. In 1985 Rodney Karr and William Gersbach began a long restoration. They put on a new slate roof in stripe and diamond patterns, stripped many layers of paint and hung hand-printed Bradbury & Bradbury wallpaper [1]. The pair ran Chateau Tivoli and later restored the Hinkel House on Divisadero too, repainting it in \"empire colors\" such as aubergine, turquoise, mustard and teal [2].", "people": [{"name": "Daniel B. Jackson", "role": "lumber baron, original owner"}, {"name": "William H. Armitage", "role": "architect"}, {"name": "Ernestine Kreling", "role": "owner of the Tivoli Opera House, later owner"}, {"name": "Rodney Karr", "role": "restorer"}, {"name": "William Gersbach", "role": "restorer"}], "sources": [{"title": "In San Francisco, a Victorian's Reign", "publisher": "Inhabit (Corcoran)", "year": null, "url": "https://inhabit.corcoran.com/in-san-francisco-a-victorians-reign/", "supports": "Armitage, Jackson, 1892, Seattle Block, Kreling, New Age centre, 1985 restoration details"}, {"title": "All About The Charles L. Hinkel House, A Victorian Architect's Home", "publisher": "Hoodline (Nuala Sawyer)", "year": 2014, "url": "https://hoodline.com/2014/10/the-charles-l-hinkel-house-a-victorian-architect-s-home/", "supports": "Karr and Gersbach as Chateau Tivoli proprietors; Hinkel House 'empire colors'"}], "photo": null}, {"id": "institutions-engine-21-firehouse", "theme": "institutions", "title": "Fifty-Four Hours on Duty from Oak Street", "year": 1893, "yearEnd": 1958, "place": "1152 Oak Street", "precision": "building", "c": [736.4, 1057.3], "block": "1215", "hook": "From this Victorian station, now the city's oldest fire department-owned firehouse, Engine Company 21 fought the 1906 Hayes Valley fires for 54 hours straight.", "story": "Behind its Victorian facade, 1152 Oak Street is the oldest firehouse still owned by the San Francisco Fire Department [1]. Henrikson & Mahoney designed it and R. Doyle & Sons built it in 1893. The architects also designed two near-twin stations: one survives on Washington Street, and the other, on Folsom Street, was demolished [2]. The Oak Street house opened just before the California Midwinter International Exposition of 1894 began nearby in Golden Gate Park [1]. When the city burned in April 1906, its crew, Engine Company 21, 'sought out and fought the Hayes Valley conflagrations, remaining on-duty for 54 hours' [1]. The horses went in 1915 when the department switched to motors, Truck Company 6 moved out in 1916, and Engine 21 left in 1958 for its current station a few blocks north on Grove Street [1]. A giant blue whale was painted on the western wall from the 1970s until the early 2000s [1]. The building's identity has always been a little muddled. The '27' painted on it is, as Hoodline put it, 'a goof' [1], and the city's official landmark list names it 'Old Firehouse, Engine Company No. 2 and Truck No. 6'. It became Landmark No. 89 in 1977 [3].", "people": [{"name": "Henrikson & Mahoney", "role": "architects"}, {"name": "R. Doyle & Sons", "role": "builders"}], "sources": [{"title": "Inside Old Station 21, San Francisco's Landmark Victorian Firehouse", "publisher": "Hoodline", "year": 2016, "url": "https://hoodline.com/2016/04/inside-old-station-21-landmark-firehouse/", "supports": "oldest SFFD-owned firehouse, 1894 opening, 54 hours in 1906, 1915 motorization, 1916 and 1958 moves, whale mural, '27' error"}, {"title": "San Francisco Landmark #89: Engine Company No. 21", "publisher": "NoeHill in San Francisco", "year": null, "url": "https://noehill.com/sf/landmarks/sf089.asp", "supports": "1893 construction, architects and builder, sister firehouses"}, {"title": "San Francisco Preservation Bulletin No. 9: San Francisco Landmarks", "publisher": "San Francisco Planning Department", "year": 2014, "url": "https://default.sfplanning.org/Preservation/bulletins/HistPres_Bulletin_09.PDF", "supports": "official landmark name and 1977 designation as No. 89"}], "photo": null}, {"id": "victorian-clunie-house", "theme": "victorian", "title": "The Mansion at the Edge of the Dunes", "year": 1897, "yearEnd": 1992, "place": "301 Lyon Street (Clunie House), at Fell", "precision": "building", "c": [360.4, 952.2], "block": "1207", "hook": "When Congressman Thomas Clunie built his turreted mansion in 1897, only sand dunes lay between it and the Pacific. Seventy years later, R. Crumb painted \"Keep on Truckin'\" upstairs.", "story": "Architect William Curlett designed 301 Lyon in 1897 for Thomas Jefferson Clunie, a lawyer, state senator, congressman and real estate speculator [1][2]. The house stood at what was then the western edge of the city, with nothing but dunes between it and the ocean [2]. Clunie spared no expense and even put in a telephone [1][2]. The city made it Landmark No. 128 in 1981 [3]. Curlett stacked a concrete-block base, a brick first floor and wooden upper storeys, and capped the corner bay with an open belvedere, one of only two left in San Francisco [1]. From 1945 the house changed hands quickly and served as a nursing home, a boarding house and then apartments [2]. By the 1967 Summer of Love as many as 40 \"flower children\" lived there, among them the cartoonist R. Crumb, who painted his \"Keep on Truckin'\" cartoon on a top-floor wall [2]. \"Word got around that it was a good place to crash,\" the Examiner's Walter Blum wrote in 1976 [2]. In 1973 Theta Seminars bought the house for rebirthing sessions [1]. It later became a bed-and-breakfast, and its owners told the New York Times in 1992, \"We found lots of pills in the walls\" [2].", "people": [{"name": "Thomas Jefferson Clunie", "role": "lawyer, congressman, original owner"}, {"name": "William Curlett", "role": "architect"}, {"name": "R. Crumb", "role": "cartoonist, 1960s resident"}], "sources": [{"title": "San Francisco Landmark #128: Thomas Jefferson Clunie House", "publisher": "NoeHill", "year": 2008, "url": "https://noehill.com/sf/landmarks/sf128.asp", "supports": "Curlett, Clunie, telephone, materials, belvedere, Theta Seminars 1973"}, {"title": "Stately mansion neighboring Panhandle contains volumes of SF history", "publisher": "San Francisco Examiner (Keith Menconi)", "year": 2025, "url": "https://www.sfexaminer.com/news/the-city/landmark-clunie-house-has-lived-at-forefront-of-sf-history/article_c62e3339-8606-45d2-9082-7050ead9c46e.html", "supports": "Dunes, Clunie's offices, uses after 1945, 40 flower children, R. Crumb mural, Blum and NYT quotes"}, {"title": "Preservation Bulletin No. 9: San Francisco Designated Landmarks", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://sfplanning.org/sites/default/files/documents/preserv/bulletins/HistPres_Bulletin_09.PDF", "supports": "Landmark No. 128, designated 1981"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/c/c9/301_Lyon_Street%2C_exterior%2C_San_Francisco_%28March_2024%29_02.jpg", "page": "https://commons.wikimedia.org/wiki/File:301_Lyon_Street,_exterior,_San_Francisco_(March_2024)_02.jpg", "credit": "BriefEdits / Wikimedia Commons", "license": "CC BY-SA 4.0", "year": 2024}}, {"id": "institutions-sacred-heart-cornerstone", "theme": "institutions", "title": "A Stone From Tara in a Fillmore Cornerstone", "year": 1898, "yearEnd": 2004, "place": "Sacred Heart Church, 554 Fillmore Street at Fell", "precision": "building", "c": [1428.8, 1019.6], "block": "0828", "hook": "The 'most Irish parish west of Chicago' sealed rock from Ireland's Hill of Tara into its church. The building now hosts roller skating.", "story": "Founded in 1885, Sacred Heart was the first Catholic parish in western San Francisco, and it was later remembered as 'the most Irish parish west of Chicago' [1]. Its first pastor, Father James Flood, who was no relation to the Comstock millionaire, started out in a derelict Methodist chapel at Linden and Buchanan Streets. In 1886 he bought land at Fillmore and Fell [1]. Architect Thomas J. Welsh designed a wooden church there in 1887, and then, with his partner John Carey, the present brick Romanesque Revival church, his only surviving church in that style [1]. On September 7, 1897 the parish laid the cornerstone and filled it with ancient coins, rock from Tara Hill in Ireland, moss from the roof of St. Columbkille's Abbey, minerals from El Dorado County mines and copies of the day's newspapers [1]. Money ran short. Archbishop Riordan dedicated the church on September 25, 1898, with a temporary wooden wall where the transepts now stand [1]. The complex came through 1906 unharmed, and the finished church was rededicated in 1909 [1]. Damage from the 1989 earthquake and the cost of a retrofit led the Archdiocese to close the church at the end of 2004 [1][3]. The Church of 8 Wheels now runs roller skating inside, and the complex became Landmark No. 316 in 2024 [1][2].", "people": [{"name": "Father James Flood", "role": "first pastor"}, {"name": "Thomas J. Welsh", "role": "architect"}, {"name": "Archbishop Patrick W. Riordan", "role": "dedicated the church in 1898"}], "sources": [{"title": "Landmark Designation Report: Sacred Heart Parish Complex (Landmark No. 316)", "publisher": "San Francisco Planning Department", "year": 2016, "url": "https://files.sfplanning.org/documents/preservation/LM316.pdf", "supports": "founding, 'most Irish parish' phrase, Flood, Welsh, cornerstone contents, 1898 dedication, 1909 completion, 2004 closure, roller skating lease, 2024 approval"}, {"title": "Supervisors Landmark Historic Sacred Heart Parish Complex", "publisher": "Office of Supervisor Dean Preston", "year": 2024, "url": "https://www.deanprestonsf.com/press-releases/supervisors-landmark-historic-sacred-heart-parish-complexnbsp", "supports": "landmarking and Church of 8 Wheels"}, {"title": "Sacred Heart Church Could Be Designated A Landmark", "publisher": "Hoodline", "year": 2015, "url": "https://hoodline.com/2015/05/sacred-heart-church-could-be-designated-a-landmark/", "supports": "Loma Prieta damage and 2004 closure"}], "photo": null}, {"id": "institutions-fillmore-substation", "theme": "institutions", "title": "The Substation That Restarted the Streetcars", "year": 1902, "yearEnd": 1978, "place": "1190 Fillmore Street, at Turk", "precision": "block", "c": [1441.0, 359.2], "block": "0749", "hook": "This brick powerhouse helped electrify San Francisco's streetcars and got the Fillmore line running soon after 1906. It has now stood empty for nearly fifty years.", "story": "The brick and sandstone substation at Fillmore and Turk went up in 1902, when San Francisco's street railways were switching from horse cars to electricity [1]. It came through the 1906 earthquake and fire, and the Fillmore Street line was one of the first back in service afterwards [1]. For three-quarters of a century it fed power to United Railroads, the Market Street Railway and finally Muni [2]. In 1978 it was declared surplus and shut, and on April 23, 1979 it became city Landmark No. 105 [2][4]. Since then it has mostly waited. The Redevelopment Agency took it over, and in 2009 redevelopment funds were diverted to bail out the nearby Yoshi's jazz club. When the agency was dissolved, the building went back to the City [2]. In August 2021 Public Works ordered emergency repairs after cracks in its unreinforced masonry were found to pose 'a significant collapse hazard to pedestrians, bicyclists, and motorists below' [2]. A seismic retrofit estimated at $2-3 million in 2003 was put at $20-30 million by 2024. A 2008 call for proposals drew only two bids, and both were rejected [3]. Neighbours have proposed a history museum, a shelter behind the preserved facade, and a 'Maya Angelou Still I Rise Center' [3].", "people": [], "sources": [{"title": "San Francisco Landmark #105: Market Street Railway Substation", "publisher": "NoeHill in San Francisco", "year": null, "url": "https://noehill.com/sf/landmarks/sf105.asp", "supports": "1902, brick and sandstone, electrification, survival in 1906 and early return of the Fillmore line"}, {"title": "Historic Neighborhood Substation at Risk of a Collapse", "publisher": "SocketSite", "year": 2021, "url": "https://socketsite.com/archives/2021/08/historic-neighborhood-substation-at-risk-of-a-collapse.html", "supports": "railways served, 1978 closure, Redevelopment and Yoshi's, 2021 emergency order and quote"}, {"title": "'Don't tear it down': Locals call for revival of historic Fillmore substation", "publisher": "The San Francisco Standard", "year": 2024, "url": "https://sfstandard.com/2024/08/07/fillmore-substation-vacant-building/", "supports": "retrofit cost estimates, 2008 RFP, community proposals"}, {"title": "San Francisco Preservation Bulletin No. 9: San Francisco Landmarks", "publisher": "San Francisco Planning Department", "year": 2014, "url": "https://default.sfplanning.org/Preservation/bulletins/HistPres_Bulletin_09.PDF", "supports": "Landmark No. 105, effective April 23, 1979"}], "photo": null}, {"id": "victorian-archbishops-mansion", "theme": "victorian", "title": "A Palace for the Archbishop", "year": 1904, "yearEnd": 2023, "place": "1000 Fulton Street (Archbishop's Mansion), at Steiner", "precision": "building", "c": [1232.9, 658.5], "block": "0778", "hook": "Built for San Francisco's archbishop in 1904, the mansion on Alamo Square later housed nuns, a boys' home, a psychiatric clinic, an opera-themed inn and a startup incubator.", "story": "In 1904 a Second Empire mansion went up facing the northeast corner of Alamo Square as the home of Patrick Riordan, second archbishop of San Francisco [1][2]. Architect Frank Shea gave it a mahogany staircase under a stained-glass dome, ornate fireplaces and French doors [3]. The Alamo Square Neighborhood Association calls it a symbol of the Catholic Church's prominence in the city's life at the time [2]. The house came through the 1906 earthquake and went on to host a Pope and later archbishops [3]. Over the decades it has also housed a convent, an orphanage, a psychiatric hospital, a rehab centre and a bed-and-breakfast [3]. It sold for $7 million in 2012, and in 2018 the co-living company Roam turned it into rooms for \"modern nomads\" [3]. By early 2023 it housed HF0, a live-in startup incubator, and the archbishop's house had become a tech \"hacker house\" [4].", "people": [{"name": "Patrick William Riordan", "role": "Archbishop of San Francisco, first occupant"}, {"name": "Frank Shea", "role": "architect"}], "sources": [{"title": "San Francisco Landmark #151: Archbishop's Mansion", "publisher": "NoeHill", "year": 2009, "url": "https://noehill.com/sf/landmarks/sf151.asp", "supports": "Built 1904 for Riordan, second archbishop; Second Empire; faces Alamo Square"}, {"title": "Explore", "publisher": "Alamo Square Neighborhood Association", "year": 2025, "url": "https://alamosquare.org/explore/", "supports": "Built 1904 for Riordan; symbol of the Catholic church's prominence"}, {"title": "The Archbishop's Mansion is SF's poshest new co-living space", "publisher": "7x7 Bay Area", "year": 2018, "url": "https://www.7x7.com/san-francisco-archbishops-mansion-open-for-coliving-2565077122.html", "supports": "Frank Shea; survived 1906; archbishops, Pope Pius XII; convent, B&B, orphanage, psychiatric hospital, rehab; sold $7M 2012; Roam"}, {"title": "Inside SF's most competitive 'hacker house'", "publisher": "San Francisco Standard (Liz Lindqwister)", "year": 2023, "url": "https://sfstandard.com/2023/01/23/inside-sfs-most-competitive-hacker-house-where-workers-eat-sleep-and-breathe-tech/", "supports": "HF0 incubator in the Archbishop's Mansion, 2023"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/4/46/Archbishop%27s_Mansion_%281905%29_at_1000_Fulton_Street%2C_San_Francisco.png", "page": "https://commons.wikimedia.org/wiki/File:Archbishop%27s_Mansion_(1905)_at_1000_Fulton_Street,_San_Francisco.png", "credit": "Max Kirkeberg Collection, DIVA San Francisco State University, via Wikimedia Commons", "license": "Public domain", "year": 1905}}, {"id": "institutions-normal-school-orphanage", "theme": "institutions", "title": "A Teachers' College Among the Orphanage Ruins", "year": 1906, "yearEnd": 1954, "place": "Former Teachers College campus, Haight Street between Laguna and Buchanan", "precision": "block", "c": [1813.1, 1317.4], "block": "0851", "hook": "After the 1906 earthquake, San Francisco State's forerunner set up in the damaged grounds of the West Coast's first orphanage and stayed for almost fifty years.", "story": "The block bounded by Haight, Laguna, Buchanan and Hermann Streets once belonged to the Protestant Orphan Asylum, founded in 1851 as the first orphanage on the West Coast [1]. Hayes Valley did not burn in 1906, but the earthquake badly damaged the asylum's masonry building [1]. The San Francisco State Normal School, founded on Nob Hill in 1899, spent a short time in Oakland and then moved into the orphanage's surviving outbuildings [1][2]. It was led by Frederic Burk, president until his death in 1924. Undeterred by what the nomination calls 'old, barren-looking' facilities, he set admission standards equal to the University of California's and introduced seminar classes and practice teaching [1]. State Architect George B. McDougall worked with Burk on a master plan, and between 1924 and 1935 the Spanish Colonial Revival campus of Richardson Hall, Woods Hall and the WPA-built Woods Hall Annex went up [1]. The Depression stopped the rest of the plan. In 1938 students protested the crumbling 'temporary' buildings, one of San Francisco State's earliest protests [1]. The college, renamed San Francisco State Teachers College in 1921, moved to Lake Merced in 1953-54, and UC Extension used the campus until 2003 [2]. The three surviving halls became city landmarks in 2007 [3].", "people": [{"name": "Frederic Burk", "role": "first president of the San Francisco State Normal School"}, {"name": "George B. McDougall", "role": "California State Architect"}], "sources": [{"title": "National Register of Historic Places Registration Form: San Francisco State Teacher's College", "publisher": "National Park Service", "year": 2007, "url": "https://npgallery.nps.gov/NRHP/GetAsset/NRHP/07001391_text", "supports": "orphan asylum, 1906 move, Burk's reforms, McDougall plan, 1924-35 construction, 1938 protest"}, {"title": "Streetwise: Modern School Days", "publisher": "OpenSFHistory / Western Neighborhoods Project", "year": 2021, "url": "https://www.opensfhistory.org/osfhcrucible/2021/08/22/streetwise-modern-school-days/", "supports": "1899 founding, renamings, 1953-54 move, UC Extension 1957-2003"}, {"title": "San Francisco Preservation Bulletin No. 9: San Francisco Landmarks", "publisher": "San Francisco Planning Department", "year": 2014, "url": "https://default.sfplanning.org/Preservation/bulletins/HistPres_Bulletin_09.PDF", "supports": "Richardson Hall, Woods Hall and Woods Hall Annex designated Landmarks 256-258 in 2007"}], "photo": null}, {"id": "quake1906-jefferson-square-camp-16", "theme": "quake1906", "title": "Camp No. 16: Cottages You Could Keep", "year": 1906, "yearEnd": 1907, "place": "Jefferson Square (Camp No. 16)", "precision": "area", "c": [1943.9, 386.3], "block": "0759", "hook": "The tents in Jefferson Square gave way to rows of little redwood cottages. Families who paid their rent could haul them away and keep them.", "story": "Jefferson Square became official Camp No. 16 on June 2, 1906. That month it held as many as 2,000 people [1]. With the rainy season coming, the relief corporation decided to replace the tents with separate wooden cottages. Construction began in the camps on September 10, 1906 [1]. Union carpenters built them in standard sizes, the smallest 10 by 14 feet, and 5,610 went up across the city [2]. Planners later described Camp No. 16 as a large camp holding 1,710 people in these mass-produced cottages [3]. The tents had been free, but the cottages were not. Relief officials charged a small rent, arguing that giving everything away \"killed the self-respect of the efficient class\" [1]. The lease worked as a purchase. A tenant who paid rent up to August 1, 1907 owned the cottage, but had to move it out of the square at their own expense [1]. The camp closed on August 23, 1907 [1]. Many cottages were dragged off on wagons to private lots, and a few are still standing somewhere in the city [2].", "people": [], "sources": [{"title": "San Francisco Relief Survey: The Organization and Methods of Relief Used After the Earthquake and Fire of April 18, 1906 (Russell Sage Foundation)", "publisher": "Survey Associates / Project Gutenberg", "year": 1913, "url": "https://www.gutenberg.org/ebooks/56217", "supports": "Camp No. 16 opening June 2, 1906, max 2,000, closing Aug. 23, 1907; cottage plan and Sept. 10, 1906 start; nominal rent rationale quote; lease-to-own terms"}, {"title": "1906 Earthquake Refugee Shacks", "publisher": "Western Neighborhoods Project (outsidelands.org)", "year": 2007, "url": "https://www.outsidelands.org/shacks.php", "supports": "Union carpenters, cottage sizes, 5,610 cottages, cottages hauled to private lots as camps closed from August 1907"}, {"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area (Page & Turnbull)", "publisher": "San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Jefferson Square as Camp No. 16 accommodating 1,710 people in refugee cottages"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/3/33/Camping_in_Jefferson_Square_LCCN2003668286.jpg", "page": "https://commons.wikimedia.org/wiki/File:Camping_in_Jefferson_Square_LCCN2003668286.jpg", "credit": "Pillsbury Picture Co. / Library of Congress", "license": "Public domain", "year": 1906}}, {"id": "quake1906-alamo-square-camp-22", "theme": "quake1906", "title": "Camp No. 22: Tents on the Hill", "year": 1906, "yearEnd": 1907, "place": "Alamo Square (Hayes Street side)", "precision": "area", "c": [1128.0, 783.0], "block": "0799", "hook": "Alamo Square became an official refugee camp, with its tents propped up on wooden legs so they stood level on the slope.", "story": "In the first days after the fire, refugees camped wherever they found open ground, and Alamo Square was one of those places [2]. In July 1906 the Army took it over as an official camp, No. 22 [1]. The Relief Survey's records say it opened on July 9, 1906, and was fullest on October 1, with 857 people. It closed on March 13, 1907 [1]. The hill was a problem, because a tent pitched on a slope isn't much of a bed. A photograph shows the camp's answer: the tents were set on wooden undercarriages that held them level [3]. That summer tents in the official camps were given floors, and buildings with latrines, wash-houses and hot and cold running water went up [1]. Alamo Square was one of several camps nearby. Duboce Park, a few blocks south, was Camp No. 19, with up to 650 people until February 1907 [1][2]. Relief District IV, which covered the neighbourhood north of Market, housed 10,737 refugees in all [2].", "people": [], "sources": [{"title": "San Francisco Relief Survey: The Organization and Methods of Relief Used After the Earthquake and Fire of April 18, 1906 (Russell Sage Foundation)", "publisher": "Survey Associates / Project Gutenberg", "year": 1913, "url": "https://www.gutenberg.org/ebooks/56217", "supports": "Camp No. 22 opening July 9, 1906, maximum 857 on Oct. 1, 1906, closing Mar. 13, 1907; Army takeover in July; floored tents and wash-houses; Duboce Park Camp No. 19 figures"}, {"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area (Page & Turnbull)", "publisher": "San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Refugee camps at Alamo Square and Duboce Park; Relief District IV housed 10,737 refugees"}, {"title": "OpenSFHistory Top Ten: 1906 Earthquake Refugee Camps (Arnold Woods)", "publisher": "Western Neighborhoods Project (OpenSFHistory)", "year": 2021, "url": "https://www.opensfhistory.org/osfhcrucible/2021/04/18/opensfhistory-top-ten-1906-earthquake-refugee-camps/", "supports": "Undercarriages built to keep Alamo Square tents level; photo of camp looking north from Hayes (wnp27.1917)"}], "photo": null}, {"id": "quake1906-jefferson-square-first-week", "theme": "quake1906", "title": "Carpets for Roofs in Jefferson Square", "year": 1906, "yearEnd": null, "place": "Jefferson Square (Eddy, Gough, Golden Gate & Laguna)", "precision": "area", "c": [2014.2, 342.7], "block": "0745", "hook": "Five thousand people crowded into Jefferson Square after the fire. Most of them sheltered under carpets and bedsheets when a storm broke over the city.", "story": "Jefferson Square sat just outside the burned district, and it filled fast. The brewer Adolphus Busch was caught in the earthquake at the St. Francis Hotel. He later said he \"urged them to escape to Jefferson square, which we did\" [1]. By April 20 there was a food station in the square, one of the first places where refugees lined up for rations [2]. Then, on the first Sunday night after the fire, came the rain. From midnight to 3 a.m. it poured, driven by a high wind [1]. One 1906 account described \"the 5,000 people or more camped in Jefferson Square Park\" as \"something terrible.\" Not more than 5 per cent had an Army tent. The rest had made shelters of \"carpets, bedsheets and every imaginable substance\" [1][3]. People kept their spirit anyway. The same account quoted an aged, disabled woman lying on a dirt floor under patchwork, carpets and tin roofing: \"I am the widow of a union soldier. The sufferings related by my husband at Vicksburg were as nothing compared to mine. I am very comfortable, thank you\" [1][3]. Nearby, St. Paul's Lutheran church served as an emergency hospital [1].", "people": [{"name": "Adolphus Busch", "role": "St. Louis brewer who fled to Jefferson Square"}], "sources": [{"title": "Complete Story of the San Francisco Horror (Richard Linthicum and Trumbull White; Hubert D. Russell)", "publisher": "Internet Archive (digitized book)", "year": 1906, "url": "https://archive.org/details/completestorysa01whitgoog", "supports": "Busch account; Sunday-night storm; 5,000 campers, 5 per cent with tents, makeshift shelters; widow's quote; St. Paul Lutheran emergency hospital"}, {"title": "San Francisco Relief Survey: The Organization and Methods of Relief Used After the Earthquake and Fire of April 18, 1906 (Russell Sage Foundation)", "publisher": "Survey Associates / Project Gutenberg", "year": 1913, "url": "https://www.gutenberg.org/ebooks/56217", "supports": "Food station at Jefferson Square operating by April 20, 1906"}, {"title": "Refugee Camps 1906: The First Month (reprint of Ch. 13, 'In the Refugee Camps', Complete Story of the San Francisco Horror)", "publisher": "FoundSF", "year": 1906, "url": "https://www.foundsf.org/index.php?title=Refugee_Camps_1906:_The_First_Month", "supports": "Same primary text: Jefferson Square conditions and the widow's quote"}], "photo": {"url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/San_Francisco_Earthquake_of_1906%2C_Jefferson_Square_refugee_camp_-_NARA_-_522960.tif/lossy-page1-1920px-San_Francisco_Earthquake_of_1906%2C_Jefferson_Square_refugee_camp_-_NARA_-_522960.tif.jpg", "page": "https://commons.wikimedia.org/wiki/File:San_Francisco_Earthquake_of_1906,_Jefferson_Square_refugee_camp_-_NARA_-_522960.tif", "credit": "George W. Haley / U.S. National Archives", "license": "Public domain", "year": 1906}}, {"id": "quake1906-fillmore-new-downtown", "theme": "quake1906", "title": "Fillmore Street, the New Market Street", "year": 1906, "yearEnd": 1909, "place": "Fillmore Street at Ellis", "precision": "street", "c": [1426.3, 181.4], "block": "0732", "hook": "With downtown in ashes, San Francisco went shopping on Fillmore. For a few years a neighbourhood street became the city's main street.", "story": "The fire had burned downtown and stopped at Van Ness, so the stores and offices that had lost their buildings looked for somewhere to go. Many of them came to Fillmore Street, a neighbourhood shopping street in the middle of the Western Addition. It briefly became a commercial centre for the whole city, until downtown was rebuilt [1]. Merchants took to calling it \"the new Market Street\" [2]. Streetcars made it possible. United Railroads had its Fillmore line running again within days, and Muni's transit chronology counts that as an important reason Fillmore became, for a short time, San Francisco's main business street [3]. A 1908 photograph at O'Farrell shows the result: crowded sidewalks, a streetcar taking on passengers, a Roos Bros. clothing store on the corner and the Van Vroom Painless Dental Parlors [4]. It didn't last. After a couple of years the big firms went back downtown, and Fillmore became a neighbourhood street again [2].", "people": [], "sources": [{"title": "Western Addition Early 20th Century Life and Work (William Issel and Robert Cherny, from San Francisco 1865-1932)", "publisher": "FoundSF", "year": 1986, "url": "https://www.foundsf.org/index.php?title=Western_Addition_Early_20th_Century_Life_and_Work", "supports": "Fire stopped at Van Ness; Fillmore briefly the city's commercial centre before downtown rebuilt; houses around Fillmore subdivided"}, {"title": "Fillmore: Forever New (Robert F. Oaks)", "publisher": "The New Fillmore", "year": null, "url": "https://newfillmore.com/fillmore-classics/fillmore-forever-new/", "supports": "'The new Market Street'; businesses relocated and returned downtown after a couple of years"}, {"title": "Transit in San Francisco: A Selected Chronology, 1850-1995 (Robert Callwell)", "publisher": "San Francisco Municipal Railway", "year": 1999, "url": "https://archives.sfmta.com/cms/rhome/documents/TransitinSanFrancisco-CallwellChronologyweb.pdf", "supports": "Fillmore line back within days; line an important factor in Fillmore becoming the major business street"}, {"title": "Fillmore near O'Farrell, 1908 (wnp14.10601)", "publisher": "Western Neighborhoods Project (OpenSFHistory)", "year": null, "url": "https://opensfhistory.org/Display/wnp14.10601", "supports": "1908 view: crowded sidewalks, streetcar boarding, Roos Bros. clothing store, Van Vroom Painless Dental Parlors"}], "photo": null}, {"id": "quake1906-fillmore-turk-breadline", "theme": "quake1906", "title": "Four Blocks for a Loaf", "year": 1906, "yearEnd": null, "place": "Fillmore Street between Turk and Eddy", "precision": "block", "c": [1430.9, 305.8], "block": "0749", "hook": "With cooking indoors banned until chimneys were checked, the breadline at Fillmore and Turk stretched four blocks.", "story": "At the end of the third day, Mayor Eugene Schmitz told everyone to put out their stoves. His proclamation warned \"all citizens not to build fires in their homes until the chimneys have been inspected and repaired properly\" [1]. Even families whose houses had survived now had no way to cook. Their pantries soon ran out, most goods in the shops had been seized, and depending on the district the ban on indoor fires lasted from a week to two or three months [2]. So the Western Addition queued. Officials took over the grocery stores still standing and handed out food. One breadline was set up at Fillmore and Turk, where \"every person who stood in line was given a whole loaf.\" That line \"was four blocks long all one afternoon\" [1]. Milk shipped over from Oakland went to women and children [1]. A postcard from the time shows a breadline running east along Eddy Street from Fillmore, with a soldier patrolling beside it. The cataloguer notes some doubt about the exact spot [3]. Photographs from the Western Addition show families cooking in the street on wood-burning stoves [3].", "people": [{"name": "Eugene Schmitz", "role": "Mayor of San Francisco"}], "sources": [{"title": "Complete Story of the San Francisco Horror (Richard Linthicum and Trumbull White; Hubert D. Russell)", "publisher": "Internet Archive (digitized book)", "year": 1906, "url": "https://archive.org/details/completestorysa01whitgoog", "supports": "Schmitz proclamation text; breadline at Fillmore and Turk, whole loaf, four blocks long; milk from Oakland"}, {"title": "San Francisco Relief Survey: The Organization and Methods of Relief Used After the Earthquake and Fire of April 18, 1906 (Russell Sage Foundation)", "publisher": "Survey Associates / Project Gutenberg", "year": 1913, "url": "https://www.gutenberg.org/ebooks/56217", "supports": "No cooking in private houses until chimneys inspected; prohibition lasted from a week to two or three months"}, {"title": "Fillmore Street 1906 (OpenSFHistory wnp27.7212 bread line on Eddy from Fillmore; wnp13.426 street cooking)", "publisher": "FoundSF / OpenSFHistory", "year": null, "url": "https://www.foundsf.org/Fillmore_Street_1906", "supports": "Bread line photo on Eddy from Fillmore with soldier; families cooking in the streets on wood-burning stoves"}], "photo": null}, {"id": "quake1906-hayes-valley-fills-up", "theme": "quake1906", "title": "Hayes Valley Fills Up", "year": 1906, "yearEnd": 1915, "place": "Hayes Street between Octavia and Laguna", "precision": "street", "c": [1897.6, 894.6], "block": "0807", "hook": "The houses west of Octavia survived the fire, and then filled with refugees. Big family homes turned into flats and backyards grew cottages.", "story": "West of Octavia, Hayes Valley came through the fire. It did not come through undamaged. The geologist H.O. Wood found cracked brick walls and fallen gables across the valley, and wrote that \"most chimney stacks were broken\" [1]. Brick-faced storefronts on Hayes Street collapsed onto the sidewalk [1]. The neighbourhood's biggest change came afterwards, as the burned-out moved in. Many refugees rented apartments or built new housing in Hayes Valley. Some owners moved away and turned their large single-family houses into apartments [1]. All over the Victorian districts just outside the fire line, Richard Walker notes, big old homes were quickly divided into flats [2]. Little was torn down. Instead, the 1913–15 Sanborn maps show large lots split up, flats built beside older houses, and cottages squeezed into back yards [1]. Hayes Valley had been middle-class, and it became increasingly working-class [1]. The same maps show the Jefferson Square Building, at the southwest corner of Golden Gate and Octavia, as headquarters of the San Francisco Socialist Party, and a Machinists' Hall on Oak Street [1].", "people": [{"name": "Harry O. Wood", "role": "geologist who surveyed the earthquake damage"}], "sources": [{"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area (Page & Turnbull)", "publisher": "San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Wood quote on Hayes Valley damage, collapsed Hayes Street storefronts, refugees renting and building, conversions to apartments, working-class shift, Sanborn infill, Socialist Party HQ, Machinists' Hall"}, {"title": "Multiple-Unit Buildings: Invisible Homes, Visible Publics, Derisible Lives (Richard Walker, Ecumene, 1995)", "publisher": "FoundSF", "year": 1995, "url": "https://www.foundsf.org/index.php?title=Multiple-Unit_Buildings:_Invisible_Homes,_Visible_Publics,_Derisible_Lives", "supports": "Large old homes just outside the fire line (Western Addition, Hayes Valley) rapidly subdivided into flats"}], "photo": null}, {"id": "victorian-dietle-house", "theme": "victorian", "title": "Sold for a Bag of Gold", "year": 1906, "yearEnd": null, "place": "294 Page Street (Charles Dietle House), at Laguna", "precision": "building", "c": [1855.7, 1185.5], "block": "0839", "hook": "After the 1906 fire, a merchant who had lost his business bought this Stick-style house on Page Street. He paid with a bag of gold saved from the ruins.", "story": "Henry Geilfuss, who later designed the Westerfeld House, designed and built the Stick-style house at the corner of Page and Laguna for Charles Dietle [1][2]. The city's landmark records give the date as 1885, though the same NoeHill page also heads it \"Built 1878\" [1]. The house came through the 1906 earthquake and fire. Afterwards Dietle sold it to John DeMartini, who paid with a bag of gold he had rescued from his destroyed business [1][2]. It became San Francisco Landmark No. 48 in 1972 [2][3]. In 2006 it housed a law office, and its interior was later restored [2]. When it came up for sale in 2013 at $2,995,000, SocketSite worked the price out at about 2,034 troy ounces of gold [2]. Its Stick-Eastlake details and its ballroom are still there [4].", "people": [{"name": "Charles Dietle", "role": "original owner"}, {"name": "Henry Geilfuss", "role": "architect-builder"}, {"name": "John DeMartini", "role": "buyer in 1906"}], "sources": [{"title": "San Francisco Landmark #48: Charles Dietle House", "publisher": "NoeHill", "year": 2003, "url": "https://noehill.com/sf/landmarks/sf048.asp", "supports": "Geilfuss; built for Dietle; bag of gold sale to DeMartini 1906"}, {"title": "From A Bag Of Gold In 1906 To 2,034 Troy Ounces Today", "publisher": "SocketSite", "year": 2013, "url": "https://socketsite.com/archives/2013/04/294_page_street_from_a_bag_of_gold_in_1906_to_2034_ounc.html", "supports": "Built 1885 by Geilfuss; bag of gold; Landmark #48 in 1972; law office; 2013 price and gold equivalent"}, {"title": "Preservation Bulletin No. 9: San Francisco Designated Landmarks", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://sfplanning.org/sites/default/files/documents/preserv/bulletins/HistPres_Bulletin_09.PDF", "supports": "Landmark No. 48, 294 Page Street, effective 1972"}, {"title": "Opulent Victorian a snapshot of historic San Francisco", "publisher": "SFGATE", "year": 2016, "url": "https://www.sfgate.com/realestate/article/Opulent-Victorian-asnapshot-of-historicSan-10598668.php", "supports": "Stick-Eastlake style, grand ballroom"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/4/4c/294_Page_St_-_Charles_Dietle_House.jpg", "page": "https://commons.wikimedia.org/wiki/File:294_Page_St_-_Charles_Dietle_House.jpg", "credit": "Dreamyshade / Wikimedia Commons", "license": "CC BY-SA 4.0", "year": 2017}}, {"id": "quake1906-ham-and-eggs-fire", "theme": "quake1906", "title": "The Ham and Eggs Fire", "year": 1906, "yearEnd": null, "place": "395 Hayes Street, at Gough", "precision": "building", "c": [2164.2, 918.6], "block": "0817", "hook": "A woman lit her stove to make breakfast after the earthquake. Her cracked chimney started the fire that burned City Hall and most of Hayes Valley.", "story": "The earthquake hit at 5:12 a.m. on April 18, 1906 [3]. Around nine o'clock, a woman in a house on the south side of Hayes Street, about 75 feet east of Gough, lit her stove to cook breakfast. The quake had cracked her chimney, and the house caught fire [1]. Tradition puts the kitchen at 395 Hayes, the corner building that housed a café in 2013 [2]. Every fire company was already busy. At Golden Gate Avenue and Buchanan another blaze burned five houses and kept much of the department tied up until ten [1]. Nobody could mount a proper fight, and Kennedy's 1908 study concluded that this one fire \"may truthfully be said to have burned over more territory than any other single fire\" [1]. It jumped Gough to the west and Franklin to the east. By about 1 p.m. it had reached the St. Nicholas Hotel on Market, and St. Ignatius Church and College at Van Ness and Hayes was burning. Embers set the roof of Mechanics' Pavilion alight [1]. Firemen found that the quake had broken the neighbourhood's water supply [2]. People called it the \"ham and eggs fire\" [1][2]. Before it was stopped it had destroyed City Hall and nearly everything east of Octavia [2][3].", "people": [{"name": "Lawrence J. Kennedy", "role": "historian whose 1908 thesis traced the fire's origin and spread"}], "sources": [{"title": "The Progress of the Fire in San Francisco, April 18th-21st, 1906, As Shown by an Analysis of Original Documents (Lawrence J. Kennedy, UC Berkeley master's thesis, 1908)", "publisher": "Museum of the City of San Francisco (sfmuseum.org)", "year": 1908, "url": "https://sfmuseum.org/1906/kennedy.html", "supports": "Location on the south side of Hayes ~75 ft east of Gough, ~9 a.m., defective chimney, the Golden Gate & Buchanan fire, 'ham and egg fire' name and quote, spread and 1 p.m. landmarks"}, {"title": "The Dangers of Cooking After a Quake: The Ham and Eggs Fire", "publisher": "Hoodline", "year": 2013, "url": "https://hoodline.com/2013/04/the-dangers-of-cooking-after-a-quake-the-ham-and-eggs-fire/", "supports": "395 Hayes Street address and present café, damaged chimney, water supply cut off, destruction of City Hall"}, {"title": "Transit in San Francisco: A Selected Chronology, 1850-1995 (Robert Callwell)", "publisher": "San Francisco Municipal Railway", "year": 1999, "url": "https://archives.sfmta.com/cms/rhome/documents/TransitinSanFrancisco-CallwellChronologyweb.pdf", "supports": "5:12 a.m. time of the earthquake"}, {"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area (Page & Turnbull)", "publisher": "San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Everything north of Market and east of Octavia leveled by the 'Ham and Eggs Fire'"}], "photo": null}, {"id": "communities-st-paulus-hydrant", "theme": "communities", "title": "The Hydrant That Saved St. Paulus", "year": 1906, "yearEnd": null, "place": "St. Paulus Lutheran Church, 999 Eddy St at Gough", "precision": "building", "c": [2141.4, 281.3], "block": "0745", "hook": "Crews were about to dynamite the German Lutheran church to stop the 1906 fire. Then the pastor asked them to try one more hydrant.", "story": "St. Paulus was the pioneer German Lutheran parish of its synod on the West Coast. Pastor Jacob M. Buehler organized the German Evangelical St. Paulus Congregation on May 15, 1867, and in 1872 the parish opened a German-American weekday school, the first Lutheran day school on the Pacific Coast [1]. Its carpenter-Gothic church at Eddy and Gough was dedicated on February 11, 1894. The architect, the Stuttgart-born Julius E. Krafft, seems to have had Chartres Cathedral in mind, and the tallest of its three redwood spires rose 55 meters [1]. In April 1906 the fire crept as close as Van Ness Avenue on one side and Golden Gate Avenue on the other. With the water mains broken, crews were dynamiting buildings to make firebreaks, and St. Paulus was on the list. Before the charges went off, Pastor G. A. Bernthal asked the workers to try the hydrant on the Eddy–Gough corner. It worked, and the church was saved [1]. In thanks the parish lent its lower rooms to the city as the First Reserve Hospital. Over two months, more than 3,000 injured people were hospitalized there and more than 10,000 were given first aid [1][2]. Services stayed German until 1920 [1][3]. The church survived a spire fire in 1940, but a fire on November 5, 1995 destroyed it [1][4].", "people": [{"name": "Jacob M. Buehler", "role": "founding pastor, 1867"}, {"name": "G. A. Bernthal", "role": "pastor in 1906"}, {"name": "Julius E. Krafft", "role": "architect"}, {"name": "J. H. Romig", "role": "physician in charge of the First Reserve Hospital"}], "sources": [{"title": "National Register of Historic Places Inventory–Nomination Form: Saint Paulus Lutheran Church", "publisher": "National Park Service", "year": 1980, "url": "https://npgallery.nps.gov/NRHP/GetAsset/NRHP/82002251_text", "supports": "Founding, school, dedication, architect, the 1906 hydrant, the First Reserve Hospital, English services from 1920, 1940 fire"}, {"title": "St. Paulus Lutheran Church", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/St._Paulus_Lutheran_Church", "supports": "Served as a shelter and hospital in 1906, German services until 1920, 1940 and 1995 fires"}, {"title": "'Amazing grace': St. Paulus Lutheran celebrates 150 years", "publisher": "Living Lutheran", "year": 2017, "url": "https://www.livinglutheran.org/2017/06/amazing-grace-st-paulus-lutheran-celebrates-150-years/", "supports": "German immigrant founders, 1906 hospital and shelter, change to English in 1920, 1995 fire"}, {"title": "San Francisco Landmark #116: Saint Paulus Lutheran Church", "publisher": "NoeHill", "year": null, "url": "https://noehill.com/sf/landmarks/sf116.asp", "supports": "Address 999 Eddy at Gough; destroyed by fire 5 November 1995"}], "photo": null}, {"id": "communities-sacred-heart-irish", "theme": "communities", "title": "The Most Irish Parish West of Chicago", "year": 1906, "yearEnd": 1936, "place": "Sacred Heart Church, Fillmore & Fell Streets (554 Fillmore St)", "precision": "building", "c": [1441.4, 1013.8], "block": "0828", "hook": "Its first pastor was a Father James Flood, but not the silver millionaire. His parish at Fillmore and Fell came through 1906 without a scratch.", "story": "Sacred Heart was founded in 1885 to serve Catholics on the city's western edge. Its first pastor, Father James Flood, was no relation to the Comstock silver king of the same name. He began in makeshift quarters and lived in a rented flat at 710 Hayes Street [1]. Thomas J. Welsh's Romanesque church at Fillmore and Fell was finished in 1898 [1][2]. For more than three decades most of its parishioners were Irish Catholics, among them the Mahony and Fay families and the opera singer Maude Fay Symington. It was remembered as \"the most Irish parish west of Chicago\" [1]. The church came through the 1906 earthquake and fire unscathed. The parish school, then in the old Sutro mansion at Hayes and Fillmore, served as a temporary hospital and shelter [1][2]. In 1910 the parish unveiled three Carrara marble altars for its silver jubilee. The main one weighed 95 tons [3]. By the 1910s many Irish families were leaving the district, and Italian, Mexican, Guatemalan and Puerto Rican families joined the parish in the 1920s and '30s [1]. The Dominican Sisters, who taught about 500 pupils there in the early 1920s, had once lived in a \"rat ridden shed.\" They finally got a proper convent in 1936 [1].", "people": [{"name": "Father James Flood", "role": "first pastor, 1885–1889"}, {"name": "Thomas J. Welsh", "role": "architect of the church"}, {"name": "Maude Fay Symington", "role": "opera singer and parishioner"}, {"name": "Father John Cullen", "role": "pastor from 1922; built the school and convent"}], "sources": [{"title": "Landmark No. 316: Sacred Heart Parish Complex, Landmark Designation Report", "publisher": "San Francisco Planning Department", "year": 2016, "url": "https://files.sfplanning.org/documents/preservation/LM316.pdf", "supports": "Founding, Father Flood, the 'most Irish parish' phrase, Irish parishioners, 1906, Sacred Heart College, demographic change, the 'rat ridden shed' and the 1936 convent"}, {"title": "Sacred Heart Chronology", "publisher": "Friends of 1800", "year": null, "url": "https://www.friendsof1800.org/SACREDHEART/sacredheartchronology.html", "supports": "Established 1885, completed 1898 to Welsh's design, food and shelter after 1906, little damage"}, {"title": "Sacred Heart Parish of San Francisco", "publisher": "Friends of 1800", "year": null, "url": "http://www.friendsof1800.org/SACREDHEART/sacredheart.html", "supports": "Carrara marble altars unveiled in 1910 for the silver jubilee; the main altar weighs 95 tons"}], "photo": null}, {"id": "communities-hebrew-orphan-asylum", "theme": "communities", "title": "The Orphanage That Fed the Neighborhood", "year": 1906, "yearEnd": 1921, "place": "Pacific Hebrew Orphan Asylum, 600 Divisadero St at Hayes", "precision": "building", "c": [832.9, 865.8], "block": "1202", "hook": "The earthquake wrecked its kitchen, so the superintendent grilled meat over a fire pit. The Jewish orphanage on Divisadero became a place where neighbors came to eat.", "story": "The Pacific Hebrew Orphan Asylum and Home Society was started in the early 1870s by B'nai B'rith and Temple Emanu-El [1][2]. In 1876 it settled permanently at 600 Divisadero, at the corner of Hayes. It cared for Jewish orphans and also for dependent elderly people [2][3]. When the 1906 earthquake destroyed the asylum's kitchen, Superintendent Henry Mauser grilled meat over a fire pit, and the orphanage became a place where neighbors came to be fed [3]. By the early twentieth century more than 200 people lived in the building, and it was aging badly [1]. Ideas about raising children without families were also changing. Reformers now favored a \"cottage\" plan of small family-style houses instead of big dormitories. One writer argued that \"a boy or girl must be indeed incorrigible who cannot find rest and sweetness in the call of a robin or savor of the new cut grass\" [1]. After years of debate, the trustees bought thirteen acres of Adolph Sutro's forest off Ocean Avenue. On June 13, 1921, under Dr. Samuel Langer, the children moved to the new Homewood Terrace [1][2]. Their old corner on Divisadero later became a Bank of Italy branch [3].", "people": [{"name": "Henry Mauser", "role": "superintendent in 1906"}, {"name": "Dr. Samuel Langer", "role": "director who led the move to Homewood Terrace"}], "sources": [{"title": "Homewood Terrace: A Closer Look", "publisher": "OpenSFHistory / Western Neighborhoods Project", "year": 2017, "url": "https://www.opensfhistory.org/osfhcrucible/2017/07/10/homewood-terrace-a-closer-look/", "supports": "Over 200 residents, the aging building, the cottage plan and quote, the Sutro forest purchase, the 1921 move"}, {"title": "Homewood Terrace Orphanage", "publisher": "Western Neighborhoods Project (outsidelands.org)", "year": null, "url": "https://www.outsidelands.org/homewood-terrace.php", "supports": "Founding, 600 Divisadero from 1876 for children and dependent aged, Dr. Samuel Langer, move on June 13, 1921"}, {"title": "A Short History of 600 Divisadero", "publisher": "Hoodline", "year": 2014, "url": "https://hoodline.com/2014/09/a-short-history-of-600-divisadero/", "supports": "1906 kitchen destroyed, Superintendent Henry Mauser grilling meat to feed neighbors, the later Bank of Italy branch"}], "photo": null}, {"id": "quake1906-page-fillmore-auditorium", "theme": "quake1906", "title": "The Rink at Page and Fillmore", "year": 1906, "yearEnd": 1915, "place": "The Auditorium, Page Street between Fillmore and Steiner (SW corner of Page & Fillmore)", "precision": "block", "c": [1310.7, 1227.6], "block": "0848", "hook": "Six months after the earthquake, an enormous skating rink with 6,000 electric lights opened on Page Street. It could hold 8,000 people.", "story": "While downtown was still rubble, the Western Addition was getting new places to go out. On November 2, 1906, the Auditorium opened at the southwest corner of Page and Fillmore. It ran the whole block along Page to Steiner [1][2]. It was built as a roller-skating rink, and a big one: the skating floor measured about 335 by 100 feet, and the building held 8,000 people [2]. The Call reported \"6000 electric lights, arranged in festoons from the ceiling,\" with walls \"paneled in Flemish oak,\" bevelled mirrors and painted landscapes [1]. People did more than skate there. The hall hosted boxing matches, basketball games, political rallies, dog shows, military balls, indoor carnivals, track meets and a poultry show [1]. There were also hospital benefits, St. Patrick's Day celebrations and roller polo [2]. Trouble came in 1913, when alcohol was apparently served to minors and the building lost its liquor licence [2]. On November 7, 1915, a huge fire destroyed the Auditorium, burned four neighbouring stores and killed a firefighter [1][2].", "people": [], "sources": [{"title": "The Auditorium", "publisher": "San Francisco Theatres (Bill Counts)", "year": 2018, "url": "http://sanfranciscotheatres.blogspot.com/2018/08/auditorium.html", "supports": "Location, November 2, 1906 opening, 8,000 capacity, SF Call description quotes, event list, November 7, 1915 fire"}, {"title": "Victorian attractions of San Francisco (Rae Alexandra)", "publisher": "KQED", "year": 2022, "url": "https://www.kqed.org/arts/13909983/victorian-attractions-san-francisco-chutes-gravity-railroad-woodwards-gardens-bonet-tower-auditorium-skating", "supports": "Opened 1906, full block Fillmore to Steiner on Page, rink dimensions, events, 1913 licence loss, fire killing a firefighter and destroying four stores"}], "photo": null}, {"id": "communities-webster-street-shul", "theme": "communities", "title": "The Webster Street Shul", "year": 1906, "yearEnd": 1973, "place": "Congregation Keneseth Israel, 935 Webster St", "precision": "block", "c": [1506.4, 493.3], "block": "0773", "hook": "Its founders thought the Geary Street temple was not strict enough, so they built their own. On the High Holidays, crowds spilled onto the sidewalk.", "story": "Keneseth Israel was one of the Fillmore's two Orthodox synagogues. It was founded by religious immigrants who wanted to keep strictly to the practice of the Old Country. They had split away from the group that founded Beth Israel, the less Orthodox congregation on Geary Street [1]. The cornerstone of the Webster Street building was laid in 1903 [1]. After the 1906 earthquake and fire drove Jews out of South of Market, the synagogue found itself at the center of a growing Jewish district [1][2]. Neighbors called it the Webster Street Shul. Its sister congregation, Anshey Sfard, was known as the Golden Gate Avenue Shul, at 1140 Golden Gate [2][3]. On Rosh Hashanah and Yom Kippur, crowds gathered all day outside the district's three synagogues. Some came out for air between prayers, and plenty never went in at all. Some could not afford congregation membership. Others were nonbelievers who still wanted to \"be counted\" as Jews on the holiest days [1]. As families moved to the Richmond, the Sunset and the suburbs, the neighborhood's institutions followed. Anshey Sfard left in 1958, and Keneseth Israel left Webster Street in 1973 [3].", "people": [], "sources": [{"title": "The Fillmore: A Jewish Neighborhood in the 1920s (from Jerry Flamm, Good Life in Hard Times)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/The_Fillmore:_A_Jewish_Neighborhood_in_the_1920s", "supports": "Orthodox founding and the split from Beth Israel, 1903 cornerstone, the High Holiday crowds"}, {"title": "Jewish Fillmore", "publisher": "The New Fillmore", "year": 2009, "url": "https://newfillmore.com/fillmore-classics/jewish-fillmore/", "supports": "Address 935 Webster, the nicknames, Anshey Sfard at 1140 Golden Gate, the 1906 migration"}, {"title": "The Library's Neighborhood", "publisher": "Jewish Community Library (San Francisco)", "year": null, "url": "https://jewishcommunitylibrary.org/neighborhood/", "supports": "Anshey Sfard moved in 1958; Keneseth Israel departed in 1973"}], "photo": null}, {"id": "quake1906-watching-from-alamo-square", "theme": "quake1906", "title": "Watching the City Burn from Alamo Square", "year": 1906, "yearEnd": null, "place": "Alamo Square, near Steiner and Grove Streets", "precision": "block", "c": [1285.2, 745.7], "block": "0798", "hook": "On April 18, 1906, crowds climbed Alamo Square's hill, sat on the grass, and watched downtown San Francisco go up in smoke.", "story": "Alamo Square's hill looks east straight over the city, and on April 18, 1906 that made it a grandstand. Photographs taken that day show the lawn full of people sitting and watching smoke rise from downtown. Wagons loaded with refugees' belongings stand on Fulton Street below [1]. Another view, taken near Steiner and Grove, shows a crowd standing in the park looking east at the fire [1]. A century later, the Examiner still remembered the square as the place \"where people gathered to watch downtown burn in 1906\" [2]. They had a lot to watch. By about 1 p.m. the Hayes Valley fire had reached Market Street, and St. Ignatius Church and College at Van Ness and Hayes was burning [3]. A 1906 account called it \"the greatest Jesuitical institution in the west\" and put its cost at $2,000,000 [4]. The people on the hill were safe. The fire was stopped at Octavia Street, about half a mile east, at dawn the next day [3].", "people": [], "sources": [{"title": "OpenSFHistory photographs wnp37.00150 / wnp27.4955 (view east from Alamo Square) and WNP135.00066 (Steiner & Grove)", "publisher": "Western Neighborhoods Project (OpenSFHistory)", "year": null, "url": "https://opensfhistory.org/Display/wnp37.00150", "supports": "April 18, 1906 crowds sitting on the lawn watching the fire, refugee wagons on Fulton Street, crowd near Steiner & Grove"}, {"title": "Alamo Square: From 'Primeval Forest Of Rocks' To Iconic Park (Griffin Estes)", "publisher": "Hoodline", "year": 2015, "url": "https://hoodline.com/2015/06/alamo-square-park/", "supports": "Examiner (May 3-4, 2008) quote about people gathering to watch downtown burn"}, {"title": "The Progress of the Fire in San Francisco, April 18th-21st, 1906, As Shown by an Analysis of Original Documents (Lawrence J. Kennedy, UC Berkeley master's thesis, 1908)", "publisher": "Museum of the City of San Francisco (sfmuseum.org)", "year": 1908, "url": "https://sfmuseum.org/1906/kennedy.html", "supports": "St. Ignatius burning about 1 p.m.; fire stopped at Octavia at dawn April 19"}, {"title": "Complete Story of the San Francisco Horror (Richard Linthicum and Trumbull White; Hubert D. Russell)", "publisher": "Internet Archive (digitized book)", "year": 1906, "url": "https://archive.org/details/completestorysa01whitgoog", "supports": "St. Ignatius cost $2,000,000"}], "photo": null}, {"id": "quake1906-octavia-fire-line", "theme": "quake1906", "title": "Where the Fire Stopped: Octavia Street", "year": 1906, "yearEnd": null, "place": "Octavia Street at Hayes Street", "precision": "street", "c": [1970.0, 890.9], "block": "0807", "hook": "For a full night the Hayes Valley fire crept west. At dawn on April 19, 1906, firemen held it at Octavia Street, and it never went further.", "story": "The Hayes Valley fire spent the afternoon and evening of April 18 working west from Gough. It reached Fell Street on the south and Golden Gate Avenue on the north [1]. One 1906 account described it spreading \"like a sickle set to a field of grain\" around the south end of the Western Addition, up to Oak and Fell along Octavia. There, the account went on, \"one puny engine puffed a single stream of water upon the burning mass\" [2]. At 12:30 a.m. on the 19th it reached Octavia between Golden Gate and McAllister [1]. Then it stopped. According to Kennedy's 1908 analysis, at five in the morning the fire \"was finally stopped at the west along Octavia Street,\" and south of Fell half a block east of it. Firemen, \"possibly assisted by some dynamiting,\" did it with no help from wind, hills or empty lots [1]. The line held for good [1][3]. City planners still use it: almost everything east of Octavia is post-1906, while Hayes Valley to the west keeps some of the oldest buildings in that part of the city [3]. Many of the Victorians west of Octavia today came through that night.", "people": [], "sources": [{"title": "The Progress of the Fire in San Francisco, April 18th-21st, 1906, As Shown by an Analysis of Original Documents (Lawrence J. Kennedy, UC Berkeley master's thesis, 1908)", "publisher": "Museum of the City of San Francisco (sfmuseum.org)", "year": 1908, "url": "https://sfmuseum.org/1906/kennedy.html", "supports": "Westward spread to Fell and Golden Gate, 12:30 a.m. arrival at Octavia, 5 a.m. stop at Octavia and half a block east of it south of Fell, quotes on stopping and dynamiting"}, {"title": "Complete Story of the San Francisco Horror (Richard Linthicum and Trumbull White; Hubert D. Russell)", "publisher": "Internet Archive (digitized book)", "year": 1906, "url": "https://archive.org/details/completestorysa01whitgoog", "supports": "Contemporary description: 'like a sickle set to a field of grain' and 'one puny engine' quotes"}, {"title": "Historic Context Statement: Market and Octavia Neighborhood Plan Area (Page & Turnbull)", "publisher": "San Francisco Planning Department", "year": 2007, "url": "https://archives.sfplanning.org/documents/682-MO_Context_Final_202007.pdf", "supports": "Octavia as the permanent western boundary of the fire; old buildings surviving west of Octavia"}], "photo": null}, {"id": "quake1906-bloody-tuesday-turk-fillmore", "theme": "quake1906", "title": "Bloody Tuesday at the Turk Street Car Barn", "year": 1907, "yearEnd": null, "place": "Turk & Fillmore car barn (yard on Turk behind the powerhouse)", "precision": "block", "c": [1410.6, 369.5], "block": "0750", "hook": "A year after the fire, strikebreakers with pistols drove streetcars out of the Turk and Fillmore barn. The shooting that followed became known as 'Bloody Tuesday.'", "story": "The earthquake gave United Railroads president Patrick Calhoun his chance. He had long wanted to turn his Market Street cable lines into overhead-wire trolleys, and after the disaster he got a permit. He was accused of bribing the entire Board of Supervisors to do it. A 22-month trial ended in a hung jury [1]. In May 1907 more than 1,500 carmen voted to strike for $3 for an eight-hour day [2]. The company brought in professional strikebreakers who could run streetcars and handle guns [2]. At 3:25 p.m. on Tuesday, May 7, six cars pulled out of the Turk and Fillmore barn. Each carried two company inspectors and four of James Farley's strikebreakers wearing pistols [1]. When the crowd threw rocks and bricks, Farley's men opened fire [1]. Strikers captured one car and brought it back, and it crashed into the barn gate. The men inside, thinking they were under attack, started shooting [2]. Accounts of the toll differ. The city's transit chronology says two men were killed and more than twenty wounded [2]. Market Street Railway counts a dead chauffeur and two fatally wounded strikers [1]. The brick powerhouse is still standing [1].", "people": [{"name": "Patrick Calhoun", "role": "president of United Railroads"}, {"name": "James Farley", "role": "strikebreaker contractor"}], "sources": [{"title": "STRIKE! (Rick Laubscher)", "publisher": "Market Street Railway", "year": 2022, "url": "https://www.streetcar.org/strike/", "supports": "Calhoun's post-quake trolley conversion and bribery allegation, hung jury, May 7 events at the Turk & Fillmore barn, casualty account, surviving powerhouse"}, {"title": "Transit in San Francisco: A Selected Chronology, 1850-1995 (Robert Callwell)", "publisher": "San Francisco Municipal Railway", "year": 1999, "url": "https://archives.sfmta.com/cms/rhome/documents/TransitinSanFrancisco-CallwellChronologyweb.pdf", "supports": "Strike vote and demands, strikebreakers, 3:25 p.m. departure, car crashing into gate, two killed and 20+ wounded, 'Bloody Tuesday'"}], "photo": null}, {"id": "quake1906-fillmore-arches", "theme": "quake1906", "title": "Fourteen Arches of Light", "year": 1907, "yearEnd": 1943, "place": "Fillmore Street at Fulton (southern end of the arches)", "precision": "street", "c": [1430.1, 709.9], "block": "0797", "hook": "To show that Fillmore was now a great city street, its merchants hung fourteen glowing iron arches over it. The arches stayed up until 1943.", "story": "Fillmore's merchants wanted their temporary boom to last. In one writer's words, the street had gone \"from a row of suburban delicatessen and cigar shops to the main artery of a great city\" [1]. In April 1907 the Fillmore Street Improvement Association asked the Board of Supervisors to let it build arches. That year Butte Engineering and Electric put up fourteen double iron arches from Sacramento Street down to Fulton. Each one crossed 32 feet above the pavement and carried 120 electric lights [1]. The first was lit at Pine on September 9, 1907, and the whole run on November 27, in time for holiday shopping. The contract was for $7,500 and costs reached $11,000, though boosters claimed $50,000 [1]. At Christmas the bulbs were changed to red and green [1]. In July 1908 a Call reporter, Gibson Adams, spent an evening on Fillmore and paid a quarter at a second-floor dance hall \"where ladies of divers nationalities graciously waltzed with me without the formality of names\" [1]. People often remember the arches as decorations for the 1915 Exposition, but they are older than that [1][2]. In June 1943 they were taken down for wartime scrap [1][2].", "people": [{"name": "Gibson Adams", "role": "San Francisco Call feature reporter"}], "sources": [{"title": "The Fillmore Arches (Woody LaBounty)", "publisher": "San Francisco Story", "year": 2022, "url": "https://www.sanfranciscostory.com/fillmore-arches/", "supports": "Improvement Association request, builder, number, span, height, lights, lighting dates, costs, Christmas colours, Gibson Adams quote, PPIE misattribution, 1943 removal"}, {"title": "Fillmore Arches Torn Down", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=Fillmore_Arches_Torn_Down", "supports": "Arches torn down as WWII scrap in 1943 (and the common PPIE attribution)"}, {"title": "Fillmore: Forever New (Robert F. Oaks)", "publisher": "The New Fillmore", "year": null, "url": "https://newfillmore.com/fillmore-classics/fillmore-forever-new/", "supports": "Electrically lit iron arches built across intersections after 1906"}], "photo": null}, {"id": "quake1906-houdini-ellis-street", "theme": "quake1906", "title": "Houdini and His Rival on Ellis Street", "year": 1907, "yearEnd": null, "place": "Orpheum Theatre (1631 Ellis St) and Princess Theatre (1671 Ellis St), near Fillmore", "precision": "block", "c": [1363.8, 181.5], "block": "0731", "hook": "In 1907 the Orpheum, burned out of downtown, reopened on Ellis near Fillmore. Houdini topped the bill while a rival escape artist played next door.", "story": "The Orpheum vaudeville circuit lost its O'Farrell Street theatre in April 1906 [1]. While downtown was rebuilt, it opened a new Orpheum at 1631 Ellis, near Fillmore, in March 1907. The architects were O'Brien and Werner, and the house had about 1,750 seats [1][2]. On August 31, 1907, Sam Loverich opened the Princess right next door at 1671 Ellis [2]. That September Harry Houdini played the Orpheum. By then he had moved past handcuffs, and he was billed as \"Houdini in New Sensations.\" The feature that week was a challenge to escape from a box built by employees of the Emporium department store [3]. For his last week, the Princess booked George W. Brindamour, advertised as \"King of All Handcuff Kings\" [3]. Variety expected a fight. Instead it reported, under the headline \"Jail Breakers at Peace,\" that each man went about his business \"as though oblivious of the other's existence\" [3]. In April 1909 the Orpheum moved back downtown, and the Ellis Street house became the Garrick [1][2]. Both theatres later became churches and were demolished in the 1970s during Fillmore redevelopment [2].", "people": [{"name": "Harry Houdini", "role": "escape artist, Orpheum headliner"}, {"name": "George W. Brindamour", "role": "rival escape artist at the Princess"}, {"name": "Sam Loverich", "role": "opened the Princess Theatre"}], "sources": [{"title": "The Orpheum / Garrick Theatre", "publisher": "San Francisco Theatres (Bill Counts)", "year": 2018, "url": "http://sanfranciscotheatres.blogspot.com/2018/10/garrick-theatre.html", "supports": "Loss of O'Farrell St Orpheum in 1906, 1631 Ellis, March 11, 1907 opening, architects, seats, 1909 move and Garrick name"}, {"title": "Ellis near Fillmore, circa 1908 (Orpheum and Princess Theatres postcard)", "publisher": "SFMemory (Greg Gaar Postcard Collection)", "year": null, "url": "https://sfmemory.org/Display/sfm001-00759", "supports": "Addresses, Orpheum opening March 11, 1907, Princess opening August 31, 1907, later churches, 1970s demolition"}, {"title": "Houdini and Brindamour: Showdown in San Francisco (John Cox)", "publisher": "Wild About Harry", "year": 2016, "url": "https://www.wildabouthoudini.com/2016/02/houdini-and-brindamour-showdown-in-san.html", "supports": "September 1907 engagement, billings, Emporium box challenge, Variety 'Jail Breakers at Peace' report"}], "photo": null}, {"id": "institutions-sp-hospital", "theme": "institutions", "title": "A Railroad's Hospital Beside the Panhandle", "year": 1908, "yearEnd": 1974, "place": "1400 Fell Street (Fell, Baker, Hayes and Lyon)", "precision": "building", "c": [444.2, 898.6], "block": "1206", "hook": "When the 1906 fire destroyed its hospital, the Southern Pacific built a grand new one on the Panhandle, for railroad workers only.", "story": "The Southern Pacific's 1898 hospital at 14th and Mission Streets burned in the 1906 fire, and that same year the railroad bought an entire block facing the Panhandle, said to be one of the largest property deals after the disaster [1]. Daniel J. Patterson, an architect in SP's Maintenance of Way Department, designed the Neo-Classical hospital, annex and powerhouse, built from 1907-08 [1]. The location was deliberate: planners of the day wanted hospitals in pleasant residential districts, where fresh air and sunlight along the Panhandle would help convalescents [1]. The railroad had begun opening hospitals for its employees in 1868, which the National Register nomination calls the first in the world reserved for railroad workers; this was the flagship, paid for by employee dues and company money [1]. It formally opened on July 15, 1909 with 450 beds [2]. In 1911 Collis P. Huntington's widow and nephew gave Huntington Social Hall as his memorial [1]. Renamed Harkness Community Hospital in 1968, it closed in 1974, apparently bankrupt [1]. The failure halted an expansion plan and left the city's only intact early-1900s hospital complex. Mercy Housing converted it in 1982-83 into 158 senior apartments [2], and it became city Landmark No. 192 in 1989 [3].", "people": [{"name": "Daniel J. Patterson", "role": "Southern Pacific architect who designed the hospital"}, {"name": "Collis P. Huntington", "role": "Southern Pacific president memorialised by Huntington Social Hall"}, {"name": "Edward S. Harkness", "role": "SP board member for whom the hospital was renamed in 1968"}], "sources": [{"title": "National Register of Historic Places Registration Form: Southern Pacific Company Hospital Historic District", "publisher": "National Park Service (prepared by Page & Turnbull)", "year": 1989, "url": "https://npgallery.nps.gov/NRHP/GetAsset/NRHP/89000319_text", "supports": "1906 purchase, Patterson, siting, 1868 employee hospitals, Huntington Hall, Harkness renaming and 1974 closure, intactness"}, {"title": "Southern Pacific Hospital: City Landmark #192", "publisher": "San Francisco Heritage", "year": null, "url": "https://www.sfheritage.org/news/southern-pacific-hospital-city-landmark-192/", "supports": "July 15, 1909 opening, 450 beds, Mercy Housing conversion and 158 units"}, {"title": "San Francisco Preservation Bulletin No. 9: San Francisco Landmarks", "publisher": "San Francisco Planning Department", "year": 2014, "url": "https://default.sfplanning.org/Preservation/bulletins/HistPres_Bulletin_09.PDF", "supports": "Landmark No. 192, effective 1989"}], "photo": null}, {"id": "quake1906-fillmore-chutes", "theme": "quake1906", "title": "The Chutes Come to Fillmore Street", "year": 1909, "yearEnd": 1911, "place": "Chutes Park, block of Fillmore, Turk, Webster & Eddy (entrance near 1226 Fillmore)", "precision": "block", "c": [1524.2, 333.7], "block": "0749", "hook": "In 1909 San Francisco's famous water-chute amusement park moved to Fillmore Street. Two years later a fire that began in a barber shop destroyed it.", "story": "After 1906 Fillmore had the crowds, and a showman moved in. On March 8, 1909, Irving Ackerman, son of the original Chutes owner, took a 13-year lease on the old Coney Island amusement park. It filled the block bounded by Fillmore, Webster, Eddy and Turk [1]. He spent $250,000 moving and enlarging the Chutes, and the new park opened on July 14, 1909 [1]. It had the famous water chute, a merry-go-round, a Circle Swing, a \"Dante's Inferno\" labyrinth, a human roulette wheel, a dance pavilion and an outdoor movie screen. There were daredevils, an elephant named Mike, a flea circus, and boxing exhibitions that included heavyweight champion Jack Johnson [1]. A fireproof Chutes Theatre opened on December 31, 1909 [2]. Some time after midnight on May 29, 1911, fire broke out in the Bondy brothers' barber shop. It killed three people, injured seven and wrecked most of the park [1]. The concrete theatre survived [1][2]. Ackerman did not rebuild the park. The theatre, turned to face Fillmore Street, reopened in 1915 as the Lyric under Ackerman and Harris [2].", "people": [{"name": "Irving Ackerman", "role": "Chutes owner, later of Ackerman & Harris"}, {"name": "Jack Johnson", "role": "heavyweight boxing champion who appeared at the Chutes"}], "sources": [{"title": "Fillmore Chutes: A Closer Look (Arnold Woods)", "publisher": "Western Neighborhoods Project (OpenSFHistory)", "year": 2020, "url": "https://www.opensfhistory.org/osfhcrucible/2020/08/09/fillmore-chutes-a-closer-look/", "supports": "Lease date, block, $250,000, July 14, 1909 opening, attractions and performers, May 29, 1911 fire details, theatre survival, no rebuilding"}, {"title": "Chutes / Lyric / American Theatre", "publisher": "San Francisco Theatres (Bill Counts)", "year": 2018, "url": "http://sanfranciscotheatres.blogspot.com/2018/10/american-theatre.html", "supports": "Chutes Theatre opening Dec. 31, 1909 at 1226 Fillmore, survival of the fireproof theatre, 1915 reopening as the Lyric facing Fillmore under Ackerman and Harris"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/4/48/Fillmore_Chutes_under_construction.jpg", "page": "https://commons.wikimedia.org/wiki/File:Fillmore_Chutes_under_construction.jpg", "credit": "Abraham Lipman / Marilyn Blaisdell Collection (OpenSFHistory wnp37.03379)", "license": "Public domain", "year": 1909}}, {"id": "communities-langendorf-bakery", "theme": "communities", "title": "Challah the Size of a Shop Window", "year": 1915, "yearEnd": null, "place": "Langendorf Bakery, 1160 McAllister St", "precision": "block", "c": [1483.3, 567.8], "block": "0773", "hook": "The 1906 fire burned out a Viennese baker south of Market. He started again on McAllister Street and built what neighbors considered the Fillmore's number one Jewish bakery.", "story": "Bernard Langendorf came to America from Vienna at sixteen. In 1895 he moved his small bakery from Chicago to San Francisco and opened Langendorf's Vienna Bakery on Folsom Street, baking rye bread said to follow an old Viennese formula [1]. The 1906 earthquake and fire destroyed it. Like many Jewish families burned out of South of Market, he moved west to the Fillmore and reopened at 878 McAllister near Laguna [1][2]. In 1915, with $400,000 raised from ten prominent San Franciscans, he built a larger plant at 1160 McAllister [1]. Neighbors remembered Langendorf's as the number one Jewish bakery in the district. During the High Holidays its windows held giant challahs, some filled with raisins and candied fruit and sprinkled with colored candy or poppy seeds [1]. By the early 1920s horse-drawn wagons and battery-powered white trucks carried its bread across the city. A 1917 film shows a parade of its horse-drawn wagons and delivery trucks, painted with the slogan \"The Best of all Breads\" [1][3]. Merchants and former employees remembered Bernard himself riding the No. 5 McAllister streetcar to the bank with a paper bag full of the day's cash [1].", "people": [{"name": "Bernard Langendorf", "role": "Viennese-born baker and founder"}], "sources": [{"title": "The Fillmore: A Jewish Neighborhood in the 1920s (from Jerry Flamm, Good Life in Hard Times)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/The_Fillmore:_A_Jewish_Neighborhood_in_the_1920s", "supports": "Langendorf's biography, the Folsom Street and 878 McAllister bakeries, the 1915 plant at 1160 McAllister, the challahs, delivery fleet and streetcar anecdote"}, {"title": "Jewish Fillmore", "publisher": "The New Fillmore", "year": 2009, "url": "https://newfillmore.com/fillmore-classics/jewish-fillmore/", "supports": "Jews displaced in 1906 moved into the Fillmore; Langendorf's among the neighborhood's Jewish businesses"}, {"title": "Gould can 1041: Langendorf Bakery Trucks (1917 film)", "publisher": "Prelinger Archives / Internet Archive", "year": 1917, "url": "https://archive.org/details/0773_Gould_can_1041_Langendorf_Bakery_Trucks_13_11_30_00", "supports": "The 1917 parade of horse-drawn and motor delivery vehicles; the slogan 'The Best of all Breads'"}], "photo": null}, {"id": "communities-chateau-tivoli-yiddish", "theme": "communities", "title": "Yiddish Lectures in a Painted Lady", "year": 1917, "yearEnd": 1929, "place": "1057 Steiner St (now the Chateau Tivoli), at Golden Gate Ave", "precision": "building", "c": [1258.7, 491.9], "block": "0775", "hook": "A shipping magnate's colorful Victorian became a home for young Jewish immigrant women. Later it became a hall for Yiddish writers and radicals.", "story": "The colorful Victorian at the corner of Steiner and Golden Gate was built in 1892 for the shipping magnate Daniel B. Jackson [1]. After 1906, as the Jewish Fillmore filled in around it, the house took on two new lives. In 1917 it became the Emanu-El Sisterhood's Residence for Single Jewish Women [1][2][3]. The Sisterhood had been founded in 1894 by women of Temple Emanu-El. It offered job help and clubs for working girls, and the Steiner Street house was meant to ease newly arrived Eastern European immigrants into American life [1][4]. The residence stayed until 1923, when the Sisterhood moved into a new building designed by Julia Morgan on Page Street [2][3]. In 1929 the house became the Yiddish Cultural Center [2][3]. It was the district's hub for secular Jewish life: classes in Yiddish language and literature, and lectures by prominent Yiddish writers from around the world. It was, the New Fillmore notes, \"also a center of radical politics\" [1]. The center lasted into the 1960s [3]. The house, now the Chateau Tivoli, is one of the few buildings of the Jewish Fillmore still standing [1].", "people": [{"name": "Daniel B. Jackson", "role": "shipping magnate who built the house"}], "sources": [{"title": "Jewish Fillmore", "publisher": "The New Fillmore", "year": 2009, "url": "https://newfillmore.com/fillmore-classics/jewish-fillmore/", "supports": "Built 1892 by Daniel B. Jackson; 1917 Sisterhood residence and its purpose; Yiddish Cultural Center activities; the radical-politics quote; a rare survivor"}, {"title": "Jews of the Fillmore: Exhibit honors a once-thriving S.F. Jewish neighborhood", "publisher": "J. The Jewish News of Northern California", "year": 2009, "url": "https://jweekly.com/2009/07/10/jews-of-the-fillmore-exhibit-honors-a-once-thriving-s-f-jewish-neighborhoo/", "supports": "1057 Steiner as the Sisterhood residence (1917–1923) and Yiddish Cultural Center (1929)"}, {"title": "The Library's Neighborhood", "publisher": "Jewish Community Library (San Francisco)", "year": null, "url": "https://jewishcommunitylibrary.org/neighborhood/", "supports": "Sisterhood residence at Steiner and Golden Gate 1917–1923; Yiddish Cultural Center 1929 to the 1960s"}, {"title": "Emanu-El Residence Club of San Francisco records, 1894–1969", "publisher": "The Magnes Collection of Jewish Art and Life, UC Berkeley", "year": null, "url": "https://magnes.berkeley.edu/collections/archives/emanu-el-residence-club-of-san-francisco-records-1894-1969/", "supports": "Sisterhood founded 1894; its work with working women"}], "photo": null}, {"id": "institutions-300-page", "theme": "institutions", "title": "Julia Morgan's Women's Residence, Then a Zen Temple", "year": 1922, "yearEnd": 1969, "place": "300 Page Street, at Laguna", "precision": "building", "c": [1814.1, 1184.7], "block": "0840", "hook": "Julia Morgan designed this brick residence for single Jewish working women. In 1969 it became the home of San Francisco Zen Center.", "story": "Women of Temple Emanu-El founded the Emanu-El Sisterhood for Personal Service in 1894. Rather than handing out money, they gave Eastern European Jewish immigrants food, education, training and help finding work [1]. From 1912 the Sisterhood rented houses for single women [2]. It then commissioned Julia Morgan, working with Dorothy Wormser, to design a permanent residence at Page and Laguna, which was finished in 1922 [1]. The brick building housed up to 60 women [1]. Its residents over the years included German women fleeing Europe in the 1930s and '40s, and in 1942-43 nearly all of them were war workers [1][2]. The Sisterhood also offered counselling, childcare and classes in its Institute for Practical Arts [2]. Renamed the Emanu-el Residence Club in 1955, it gradually lost residents, and in 1969 the board voted to close it [2]. That same year San Francisco Zen Center bought the building, and Shunryu Suzuki Roshi founded City Center there as a Soto Zen training centre open to the public [1][3]. It was the Zen community's second Jewish home. Suzuki's congregation, Sokoji, met in the former Bush Street synagogue that Congregation Ohabai Shalome built in 1895 [1][2].", "people": [{"name": "Julia Morgan", "role": "architect"}, {"name": "Dorothy Wormser", "role": "co-designer"}, {"name": "Shunryu Suzuki Roshi", "role": "founder of San Francisco Zen Center's City Center"}], "sources": [{"title": "History of 300 Page Street", "publisher": "San Francisco Zen Center, Sangha News Journal", "year": 2012, "url": "https://blogs.sfzc.org/blog/2012/09/25/history-of-300-page-street/", "supports": "Sisterhood's founding and work, Morgan and Wormser, 1922, 60 residents, refugees, 1969 purchase, Sokoji synagogue"}, {"title": "History of 300 Page St (by Mary C. Morgan)", "publisher": "Cuke Archives (Shunryu Suzuki archive)", "year": null, "url": "https://www.cuke.com/Cucumber-Project/other/300page-history.htm", "supports": "1912 rented houses, war workers, programs, 1955 renaming, 1969 closure"}, {"title": "About City Center", "publisher": "San Francisco Zen Center", "year": null, "url": "https://www.sfzc.org/practice-centers/city-center/about", "supports": "City Center founded 1969 by Suzuki Roshi, open to the public, Julia Morgan building"}], "photo": null}, {"id": "communities-menuhin-steiner", "theme": "communities", "title": "A Prodigy's House on Steiner Street", "year": 1923, "yearEnd": null, "place": "Menuhin family home, 1043 Steiner St", "precision": "building", "c": [1235.5, 519.0], "block": "0775", "hook": "A Hebrew teacher bought a hillside house with a double parlor that could seat sixty. His seven-year-old son, Yehudi, was about to astonish the concert world.", "story": "Moshe and Marutha Menuhin were Russian Jewish immigrants. They brought their son Yehudi to San Francisco when he was nine months old [1]. Moshe taught Hebrew and went on to run the Jewish Education Society [1][2]. He was also for a time principal of the Central Hebrew School at Grove and Buchanan, which hundreds of neighborhood children attended [3]. Yehudi began violin at five with Sigmund Anker, a teacher of young children. He then studied with Louis Persinger, concertmaster of the San Francisco Symphony, and gave his first professional concert around 1923 at the Oakland Auditorium [1]. That autumn the family left 732 Hayes Street for a two-story wooden house at 1043 Steiner. Its double living room, divided by sliding doors, could seat about sixty guests for informal concerts, and there was a small practice room off the kitchen [4]. Moshe covered the $50-a-month mortgage partly by renting out garage spaces and upstairs rooms [4]. The children, Yehudi and his sisters Hephzibah and Yaltah, were taught at home [1]. Hephzibah, a gifted pianist, had been born in San Francisco in 1920 [2]. In 1927, at age ten, Yehudi played his Carnegie Hall debut and became a star overnight [1].", "people": [{"name": "Yehudi Menuhin", "role": "violinist, grew up in the house"}, {"name": "Moshe Menuhin", "role": "Hebrew teacher, Jewish Education Society, father"}, {"name": "Marutha Menuhin", "role": "mother"}, {"name": "Hephzibah Menuhin", "role": "pianist, sister"}, {"name": "Louis Persinger", "role": "violin teacher, San Francisco Symphony concertmaster"}], "sources": [{"title": "Yehudi Menuhin", "publisher": "Encyclopedia.com (Contemporary Musicians)", "year": null, "url": "https://www.encyclopedia.com/people/literature-and-arts/music-history-composers-and-performers-biographies/yehudi-menuhin", "supports": "Move to SF at nine months, teachers Anker and Persinger, Oakland debut, home schooling, Carnegie Hall at ten"}, {"title": "Menuhin, Hephzibah (1920–1981)", "publisher": "Australian Dictionary of Biography", "year": null, "url": "https://adb.anu.edu.au/biography/menuhin-hephzibah-14967", "supports": "Hephzibah born 20 May 1920 in San Francisco; Moshe was manager of the Jewish Education Society"}, {"title": "Jewish Fillmore", "publisher": "The New Fillmore", "year": 2009, "url": "https://newfillmore.com/fillmore-classics/jewish-fillmore/", "supports": "Moshe Menuhin was principal of the Central Hebrew School at Grove and Buchanan; the family lived next to 1057 Steiner"}, {"title": "The Menuhin Tour of San Francisco, Part 2 (citing Humphrey Burton, Yehudi Menuhin: A Life)", "publisher": "Active Violinist", "year": null, "url": "https://www.activeviolinist.com/blog/the-menuhin-tour-part-2", "supports": "Move from 732 Hayes to 1043 Steiner in autumn 1923; double living room for about sixty; mortgage and lodgers"}], "photo": null}, {"id": "communities-jefferson-market", "theme": "communities", "title": "Feathers on Buchanan Street", "year": 1925, "yearEnd": null, "place": "Jefferson Market, 1002 Buchanan St", "precision": "building", "c": [1718.2, 533.5], "block": "0771", "hook": "Cages of squawking chickens were stacked on the sidewalk, and feathers hung in the air. This was where Jewish San Francisco came to buy its Sabbath bird.", "story": "In the 1920s and '30s, the Jefferson Market at 1002 Buchanan, owned by I. Goldstein, was the main place in San Francisco's Jewish community to buy a fresh chicken [1]. Jerry Flamm's account remembers a place that \"bulged with screeching chickens\". Cages were piled on the sidewalk, leaving only narrow aisles for passers-by, and a cloud of feathers hung in the air [1]. You picked your bird and a clerk carried it, flapping, to the back. There the shochet, the kosher slaughterer, killed it with a straight-edge razor and hung it to bleed. Then it was plucked, wrapped in newspaper and handed to you [1][2]. The Jefferson was one of four places in the district that sold kosher chickens, along with Sosnick's, Diller's and Shenson's [2]. They belonged to a dense little world. In the two blocks bounded by Fillmore, Buchanan, McAllister and Golden Gate there were two synagogues, three kosher restaurants, four Jewish bakeries, five kosher meat markets, at least three delicatessens and a Jewish liquor merchant [2][3]. On Saturday nights, after the Sabbath ended at sundown, shops reopened and stayed busy until eleven [1].", "people": [{"name": "I. Goldstein", "role": "owner of the Jefferson Market"}, {"name": "Jerry Flamm", "role": "memoirist of the Jewish Fillmore"}], "sources": [{"title": "The Fillmore: A Jewish Neighborhood in the 1920s (from Jerry Flamm, Good Life in Hard Times)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/The_Fillmore:_A_Jewish_Neighborhood_in_the_1920s", "supports": "Address, owner, the description of the chickens and the shochet, Saturday-night hours"}, {"title": "Jewish Fillmore", "publisher": "The New Fillmore", "year": 2009, "url": "https://newfillmore.com/fillmore-classics/jewish-fillmore/", "supports": "The four kosher chicken sellers, the shochet, the count of businesses in the two blocks"}, {"title": "Jews of the Fillmore: Exhibit honors a once-thriving S.F. Jewish neighborhood", "publisher": "J. The Jewish News of Northern California", "year": 2009, "url": "https://jweekly.com/2009/07/10/jews-of-the-fillmore-exhibit-honors-a-once-thriving-s-f-jewish-neighborhoo/", "supports": "The count of synagogues, restaurants, bakeries and meat markets in the two-block area"}], "photo": null}, {"id": "communities-dillers-kosher", "theme": "communities", "title": "Seventy-Five Cents at Diller's", "year": 1925, "yearEnd": null, "place": "Diller's Strictly Kosher Restaurant, 1233 Golden Gate Ave", "precision": "block", "c": [1491.5, 516.5], "block": "0773", "hook": "Dinner at Diller's cost a bissel more than at Schindler's, but on weekend nights the kosher restaurant on Golden Gate Avenue was packed.", "story": "Among the kosher eateries along Golden Gate Avenue and McAllister Street, Diller's Strictly Kosher Restaurant was, in Jerry Flamm's words, \"the biggest, the best, and the most popular\" [1]. It stood on Golden Gate between Webster and Fillmore [1][2]. A dinner cost seventy-five cents, a \"bissel\" (a little) more than the fifty cents charged at Schindler's, and people agreed it was worth it [1]. On weekend nights the place was full. Families coming back from the popular Sunday picnics at San Mateo Park or at Alum Rock Park in San Jose often went straight to Diller's for dinner before going home [1]. Diller's also sold kosher chickens, one of four places in the district that did [2]. It stood in a two-block pocket bounded by Fillmore, Buchanan, McAllister and Golden Gate that held three kosher restaurants, four Jewish bakeries and five kosher meat markets [2][3]. The Jewish Fillmore grew up after the 1906 earthquake, when Jews burned out of South of Market moved west. It faded after World War II as families left for the Richmond, the Sunset and the suburbs [2]. Later redevelopment cleared many of these blocks [3].", "people": [{"name": "Jerry Flamm", "role": "memoirist who described Diller's"}], "sources": [{"title": "The Fillmore: A Jewish Neighborhood in the 1920s (from Jerry Flamm, Good Life in Hard Times)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/The_Fillmore:_A_Jewish_Neighborhood_in_the_1920s", "supports": "Address 1233 Golden Gate, prices, the quote, the Sunday picnic crowds"}, {"title": "Jewish Fillmore", "publisher": "The New Fillmore", "year": 2009, "url": "https://newfillmore.com/fillmore-classics/jewish-fillmore/", "supports": "Location between Webster and Fillmore, most popular eatery, kosher chickens, the two-block count, rise and decline of the Jewish Fillmore"}, {"title": "Jews of the Fillmore: Exhibit honors a once-thriving S.F. Jewish neighborhood", "publisher": "J. The Jewish News of Northern California", "year": 2009, "url": "https://jweekly.com/2009/07/10/jews-of-the-fillmore-exhibit-honors-a-once-thriving-s-f-jewish-neighborhoo/", "supports": "Diller's among the remembered businesses; the two-block count; redevelopment demolitions"}], "photo": null}, {"id": "institutions-harding-theater", "theme": "institutions", "title": "The Harding: Movies, Operetta, the Dead, a Church", "year": 1926, "yearEnd": 2017, "place": "Harding Theater, 616 Divisadero Street at Hayes", "precision": "building", "c": [833.7, 849.6], "block": "1202", "hook": "One Divisadero movie palace has been a vaudeville house, a Gilbert and Sullivan stage, a Grateful Dead venue, a church and an arcade bar.", "story": "The Harding was built in 1926 for theatre owner Samuel H. Levin, whose chain also included the Balboa, Alexandria, Coliseum, Metro and Empire. It was designed by the Reid Brothers, James and Merritt Reid [1][2]. It seated 1,250 people and opened with Colleen Moore in 'Irene'. Cinema Treasures dates the opening to April 8, 1926, while another account says May [1][2]. In the 1920s it was a neighbourhood movie and vaudeville house, and it later ran as a single-screen cinema [2]. Then it began a long run of second lives. The Lamplighters, San Francisco's Gilbert and Sullivan company, performed there in the 1960s [1][2]. In the late 1960s and early '70s it was a music venue, and the Grateful Dead played on November 6 and 7, 1971 [1][2]. For about thirty years after that it was a church and community centre, until 2003 or 2004 according to different sources [1][2]. In 2008 a Planning Department historic resource evaluation concluded that the Harding was a landmark building [2]. In November 2017 it reopened as Emporium SF, an arcade and bar with pinball, games and billiards [1].", "people": [{"name": "Samuel H. Levin", "role": "theatre owner who built the Harding"}, {"name": "James and Merritt Reid", "role": "architects (Reid Brothers)"}], "sources": [{"title": "Harding Theatre", "publisher": "Cinema Treasures", "year": null, "url": "https://www.cinematreasures.org/theaters/3141", "supports": "opening film and date, Reid Brothers, 1,250 seats, Lamplighters, Grateful Dead dates, church to 2004, Emporium 2017"}, {"title": "The Harding Theater", "publisher": "Friends of 1800", "year": null, "url": "http://www.friendsof1800.org/HARDING/hardingtheater.html", "supports": "Levin chain, May 1926 opening, sequence of uses, church until 2003, 2008 evaluation"}], "photo": null}, {"id": "communities-old-holy-virgin", "theme": "communities", "title": "A Russian Cathedral in an Episcopal Church", "year": 1931, "yearEnd": 1965, "place": "Old Holy Virgin Cathedral, 858–864 Fulton St", "precision": "building", "c": [1471.4, 658.9], "block": "0780", "hook": "Russians who had fled the Revolution bought a redwood Episcopal church on Fulton Street. For 34 years it was the cathedral of the Russian Orthodox Church Outside Russia's western diocese.", "story": "In 1927, as refugees from the Russian Revolution settled in San Francisco, a group of faithful led by Archbishop Apollinary (Koshevoi) formed a parish of the Russian Orthodox Church Outside Russia. They dedicated it to the icon of the Mother of God, \"Joy of All Who Sorrow\" [1]. At first they worshipped in a storefront on Sacramento Street. In 1931 they bought the former St. Stephen's Episcopal Church on Fulton Street between Webster and Fillmore [1][2]. It is a German Renaissance–style building of California redwood, dated to about 1880 [2]. They installed an iconostasis in front of the altar and carved icon shrines along the walls, and the building became the cathedral of the diocese [1]. Archbishop Tikhon (Troitsky) led the diocese from 1930 to 1962 [1]. After the communist victory in China, thousands of Orthodox refugees came to San Francisco in the early 1950s, many of them by way of the Philippines under the guidance of St. John of Shanghai and San Francisco. The cathedral was packed so tight that candles had to be passed hand to hand to reach the stands [1]. St. John became archbishop of San Francisco in 1963 and kept serving at Fulton Street until the new cathedral on Geary opened in 1965 [1][3]. The old building became City Landmark No. 28 in 1970 [1][2].", "people": [{"name": "Archbishop Apollinary (Koshevoi)", "role": "led the founding of the parish, 1927"}, {"name": "Archbishop Tikhon (Troitsky)", "role": "ruling hierarch in San Francisco, 1930–1962"}, {"name": "St. John of Shanghai and San Francisco (John Maximovitch)", "role": "archbishop of San Francisco from 1963"}], "sources": [{"title": "History: The Old Cathedral of the Holy Virgin 'Joy of All Who Sorrow'", "publisher": "Old Holy Virgin Cathedral", "year": null, "url": "http://stariisobor.org/about-ohvc/history/", "supports": "1927 founding, the Sacramento Street storefront, 1931 purchase of St. Stephen's Episcopal, iconostasis, Archbishop Tikhon, refugees from China, St. John, 1965 move, Landmark No. 28"}, {"title": "San Francisco Landmark #28: Old Holy Virgin Russian Orthodox Church", "publisher": "NoeHill", "year": null, "url": "https://noehill.com/sf/landmarks/sf028.asp", "supports": "Address 858–864 Fulton between Webster and Fillmore, built 1880 as an Episcopal church, German Renaissance style, bought 1931"}, {"title": "Holy Virgin Cathedral", "publisher": "Wikipedia (pointer)", "year": null, "url": "https://en.wikipedia.org/wiki/Holy_Virgin_Cathedral", "supports": "The Fulton Street 'Old Cathedral' used until 1965; designated a landmark on May 3, 1970; St. John's appointment"}], "photo": null}, {"id": "institutions-kadish-alchemy-mural", "theme": "institutions", "title": "The Atom Mural the WPA Found Too Radical", "year": 1935, "yearEnd": null, "place": "Woods Hall Annex, 218 Buchanan Street", "precision": "building", "c": [1764.8, 1348.1], "block": "0851", "hook": "Reuben Kadish wanted to paint the splitting of the atom on a college stairway. What he painted instead was a shattered egg.", "story": "Woods Hall Annex, completed in 1935, was the last building on the Teachers College campus and the only one built by the WPA [1]. On the second-floor landing of its main stair, muralist Reuben Kadish painted 'A Dissertation on Alchemy', six panels of figures and symbols about alchemy and science [1]. The nomination dates it to 1935, while a later account gives 1937 [1][3]. At the centre, a huge shattered egg releases a stylised spiral. Kadish had originally planned to show the splitting of the atom, an idea WPA officials considered too radical, and the egg may be an abstract reworking of it [1]. He had studied with the Mexican muralist David Siqueiros, and the influence shows [1]. The campus was one of the city's busiest centres of WPA art. At least five murals were made here by Kadish, Jack Moxom, Hebe Stackpole, Maxine Albro and John Gerrity [1]. Most are gone. Albro's marble mosaic over the Haight and Buchanan entrance to Woods Hall has been removed or covered, and Gerrity's canvas panels have probably been taken down [1][2]. Kadish's mural and Moxom's winged fresco angel in Richardson Hall survive [1]. The mural was restored after graffiti damage in 2013, and the old campus now houses an apartment complex called Alchemy [3].", "people": [{"name": "Reuben Kadish", "role": "WPA muralist"}, {"name": "Maxine Albro", "role": "WPA mosaic artist"}, {"name": "Jack Moxom", "role": "WPA fresco painter"}], "sources": [{"title": "National Register of Historic Places Registration Form: San Francisco State Teacher's College", "publisher": "National Park Service", "year": 2007, "url": "https://npgallery.nps.gov/NRHP/GetAsset/NRHP/07001391_text", "supports": "Annex date and WPA construction, mural description, atom idea, Siqueiros, list of muralists, fate of Albro and Gerrity works"}, {"title": "UC Extension/San Francisco State Teacher's University - Woods Hall Annex", "publisher": "The Living New Deal", "year": null, "url": "https://livingnewdeal.org/sites/uc-extensionsan-francisco-state-teachers-university-woods-hall-annex-san-francisco-ca/", "supports": "Albro mosaic over the Haight and Buchanan entrance; Kadish mural title"}, {"title": "A look at where SFSU's former campus was", "publisher": "Golden Gate Xpress (SF State)", "year": null, "url": "https://goldengatexpress.org/105672/beyond-sfsu/a-look-at-where-sfsus-former-campus-was/", "supports": "2013 restoration after graffiti, Alchemy apartments, 1937 date"}], "photo": null}, {"id": "communities-weill-pledge", "theme": "communities", "title": "Hands on Hearts at Raphael Weill School", "year": 1942, "yearEnd": null, "place": "Raphael Weill School (now Rosa Parks Elementary), 1501 O'Farrell St", "precision": "building", "c": [1680.8, 136.3], "block": "0723", "hook": "On April 20, 1942, Dorothea Lange photographed Japanese American children reciting the Pledge of Allegiance. Within weeks, the government had taken them away.", "story": "Raphael Weill School on O'Farrell Street served most of the children of the Japanese American community. Its student body reflected one of the most diverse neighborhoods in the West, and Dorothea Lange called the area \"the so-called international district\" [1]. In the spring of 1942 Lange was photographing the removal ordered under Executive Order 9066 for the War Relocation Authority. Between April 16 and 20 she photographed the school [2][3]. Her caption for one frame read: \"Pals at Raphael Weill Public School... Yuichi Sumi (left), of Japanese ancestry, and Tommy Wong of Chinese descent, on one of the last days before evacuation\" [3]. On April 20 she photographed a flag-pledge ceremony [3]. Two seven-year-olds in plaid coats stood in the front row, hands over their hearts. Hideno Nakamoto and Yoko Itashiki were soon sent to the Tanforan Assembly Center in San Bruno and then to the camp at Topaz, Utah [4]. The pictures were taken nine days after the first wave of more than 600 Japanese Americans had been removed from the city [2]. By the end of May every Japanese American family in San Francisco was gone [2].", "people": [{"name": "Dorothea Lange", "role": "photographer for the War Relocation Authority"}, {"name": "Hideno Nakamoto (later Helene Mihara)", "role": "pupil in the pledge photograph"}, {"name": "Yoko Itashiki (later Mary Ann Yahiro)", "role": "pupil in the pledge photograph"}, {"name": "Yuichi Sumi", "role": "pupil photographed with his friend Tommy Wong"}], "sources": [{"title": "Historic Context Statement: Japantown, San Francisco", "publisher": "San Francisco Planning Department (Donna Graves and Page & Turnbull)", "year": 2011, "url": "https://sfplanning.s3.amazonaws.com/archives/documents/1696-Japantown_Context_Statement_REVISED_5-11.pdf", "supports": "Raphael Weill School at 1501 O'Farrell served most Japantown children; diverse student body; Lange's 'international district'"}, {"title": "Pledge of Allegiance", "publisher": "Oakland Museum of California, Picture This", "year": null, "url": "http://picturethis.museumca.org/pictures/pledge-allegiance", "supports": "Photographs taken April 16–20, 1942, nine days after the first 600+ were removed; all SF Japanese Americans gone by end of May"}, {"title": "Pals at Raphael Weill Public School, Geary and Buchanan Streets (NARA 536050) and Flag of allegiance pledge (NARA 536053)", "publisher": "U.S. National Archives, via Wikimedia Commons", "year": 1942, "url": "https://commons.wikimedia.org/wiki/File:Pals_at_Raphael_Weill_Public_School,_Geary_and_Buchanan_Streets._Yuichi_Sumi_(left),_of_Japanese_an_._._._-_NARA_-_536050.jpg", "supports": "Lange's original captions and the date of April 20, 1942"}, {"title": "JANM Photo Exhibition Depicts Triumph Over Adversity", "publisher": "Rafu Shimpo", "year": 2018, "url": "https://rafu.com/2018/12/janm-photo-exhibition-depicts-triumph-over-adversity/", "supports": "Hideno Nakamoto and Yoko Itashiki, both 7, sent to Tanforan and then Topaz"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/9/9c/San_Francisco%2C_California._Flag_of_allegiance_pledge_at_Raphael_Weill_Public_School%2C_Geary_and_Buch_._._._-_NARA_-_536053.jpg", "page": "https://commons.wikimedia.org/wiki/File:San_Francisco,_California._Flag_of_allegiance_pledge_at_Raphael_Weill_Public_School,_Geary_and_Buch_._._._-_NARA_-_536053.jpg", "credit": "Dorothea Lange, War Relocation Authority / U.S. National Archives", "license": "Public domain", "year": 1942}}, {"id": "communities-last-buses-1942", "theme": "communities", "title": "Six Greyhound Buses on O'Farrell Street", "year": 1942, "yearEnd": null, "place": "Raphael Weill School (now Rosa Parks Elementary), 1501 O'Farrell St", "precision": "building", "c": [1693.3, 130.2], "block": "0723", "hook": "On the morning of May 20, 1942, the last 274 Japanese Americans in San Francisco boarded buses outside a neighborhood school. \"There were tears,\" the Chronicle reported.", "story": "On December 7, 1941, about 5,280 people of Japanese ancestry lived in San Francisco [1]. Executive Order 9066, signed in February 1942, let the Army clear them out, citizens and non-citizens alike [2]. Each exclusion order gave families only days to register at a Civil Control Station, which offered to arrange the \"leasing, sale, storage or other disposition\" of homes, businesses, cars and household goods [3]. The first groups left in April from control stations at 1701 and 2020 Van Ness Avenue [4]. The city's Japanese Americans reported to sites including Kinmon Gakuen on Bush Street, the YMCA on Buchanan and Raphael Weill School [2]. The last were cleared on May 20. That morning, reported the Chronicle, \"at the Raphael Weill School on O'Farrell Street, they started their ride to Tanforan\" in six Greyhound buses, watched by military police. \"There were tears – but not from the Japanese. They came from those who stayed behind – old friends, old employers, old neighbors\" [1]. By noon all 274 were at the San Bruno racetrack [1]. That night, the paper said, Japanese town was empty, its windows \"plastered with 'To Lease' signs\" [1]. Most San Franciscans were later sent on to Topaz, Utah, and many stayed there until 1945 [2].", "people": [], "sources": [{"title": "S.F. Clear of all But 6 Sick Japanese (San Francisco Chronicle, May 21, 1942)", "publisher": "Museum of the City of San Francisco", "year": 1942, "url": "http://sfmuseum.org/hist8/evac19.html", "supports": "5,280 Japanese in SF in 1941; the last 274 left by six Greyhound buses from Raphael Weill School on O'Farrell Street; quotes about the tears and the 'To Lease' signs"}, {"title": "Historic Context Statement: Japantown, San Francisco", "publisher": "San Francisco Planning Department (Donna Graves and Page & Turnbull)", "year": 2011, "url": "https://sfplanning.s3.amazonaws.com/archives/documents/1696-Japantown_Context_Statement_REVISED_5-11.pdf", "supports": "EO 9066; registration at Kinmon Gakuen, the YMCA and Raphael Weill School, where the last buses left; Topaz; many held until 1945"}, {"title": "Instructions to All Persons of Japanese Ancestry (April 1, 1942)", "publisher": "Museum of the City of San Francisco", "year": 1942, "url": "http://sfmuseum.org/hist9/evacorder.html", "supports": "Civil Control Station at 1701 Van Ness and its property-disposition services"}, {"title": "Goodby! Write Soon! (San Francisco News, April 7, 1942)", "publisher": "Museum of the City of San Francisco", "year": 1942, "url": "http://sfmuseum.org/hist8/evac12.html", "supports": "First departures from the control stations at 2020 and 1701 Van Ness"}], "photo": null}, {"id": "harlem-wartime-migration", "theme": "harlem", "title": "Fifteen to a Room: The Wartime Fillmore", "year": 1943, "yearEnd": 1950, "place": "Fillmore Street between McAllister and O'Farrell", "precision": "area", "c": [1423.8, 495.4], "block": "0773", "hook": "In one decade San Francisco's Black population grew about tenfold, as shipyard workers from Texas and Louisiana crowded into the flats along Fillmore Street.", "story": "In 1940 San Francisco had 4,806 African American residents. By 1950 it had 43,460, an increase of about 900 percent [1]. They came from Texas, Louisiana, Oklahoma and across the South for work at Hunters Point Naval Shipyard and Marinship in Sausalito. Racial covenants and prejudice closed off many neighborhoods to them, so many settled in the Fillmore [1][2]. By 1950 about 15,000 lived in the Western Addition [2]. Conditions were grim. A 1944 survey by the San Francisco Reporter found war workers \"crowded 9, 10, and 15 to a single room with only one window\" [1]. Sociologist Charles S. Johnson reported that neighborhood groups and merchants were working to \"restrict the area of living for Negro families to the present boundaries of the Fillmore district\" [1]. Newcomers spread south along Fillmore and Webster toward Hayes Valley [3]. An eight-block stretch of Fillmore, from Sutter down to McAllister, had already become the main street of Black San Francisco [1]. The newcomers' churches, clubs and shops would soon earn the district a new nickname: the Harlem of the West [1].", "people": [{"name": "Charles S. Johnson", "role": "Sociologist, author of The Negro War Worker in San Francisco"}], "sources": [{"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "1940 and 1950 population figures; shipyard jobs; covenants; 1944 Reporter quote; Charles S. Johnson quote; Fillmore main street between Sutter and McAllister; 'Harlem of the West'"}, {"title": "The Fillmore: Black SF", "publisher": "FoundSF (Chris Carlsson)", "year": 2016, "url": "https://www.foundsf.org/index.php?title=The_Fillmore:_Black_SF", "supports": "Migrants from Texas, Oklahoma, Louisiana and the Deep South; 15,000 in the Western Addition by 1950"}, {"title": "Sacred Heart Parish Complex Landmark Designation Report (LM316)", "publisher": "San Francisco Planning Department", "year": 2016, "url": "https://files.sfplanning.org/documents/preservation/LM316.pdf", "supports": "African American residents moved south along Fillmore and Webster streets into Hayes Valley"}], "photo": null}, {"id": "harlem-haynes-for-supervisor", "theme": "harlem", "title": "The Preacher Who Ran for City Hall", "year": 1945, "yearEnd": 1951, "place": "Third Baptist Church, 1399 McAllister Street", "precision": "building", "c": [1130.3, 593.0], "block": "0778", "hook": "Two decades before San Francisco seated a Black supervisor, a Baptist pastor ran three times, and in 1951 he won 36,000 votes.", "story": "Frederick Douglas Haynes was born in Talcott, West Virginia, in 1899 and orphaned as a child. He took the pulpit of Third Baptist in 1932, when, a 1953 profile said, most members were unemployed and \"often the Sunday offering did not exceed thirty dollars\" [1]. By his death in 1971 the church had more than 3,000 members [1]. In 1945 Haynes became the first African American to run for the San Francisco Board of Supervisors, and he ran again in 1947 and 1951 [1]. One campaign flyer read: \"I have pledged myself to fight to my dying day to wipe out discrimination against minority races in the economical, political, and social life of our city, state, and nation\" [1]. He never won, but his 36,000 votes in 1951, backed by the Union Labor Party, the CIO Council and the Fillmore Democratic Club, showed white politicians that Black voters counted [1][3]. The city context statement names him among the ministers who served as the community's main liaisons with the white power structure [2]. Terry Francois became the first Black supervisor in 1964, and in 1972 Haynes's widow, Charlie Mae, won a seat on the school board [1].", "people": [{"name": "Frederick Douglas Haynes Sr.", "role": "Pastor and candidate for supervisor"}, {"name": "Charlie Mae (Crawford) Haynes", "role": "Singer, church worker, elected to the school board in 1972"}, {"name": "Terry A. Francois", "role": "First African American supervisor, 1964"}], "sources": [{"title": "Third Baptist Church Complex, 1399 McAllister Street: Article 10 Landmark Designation Report", "publisher": "San Francisco Planning Department", "year": 2017, "url": "https://default.sfplanning.org/Preservation/landmarks_designation/hp_third_baptist_church_final_draft.pdf", "supports": "Haynes biography; 1932 offerings quote; runs in 1945, 1947, 1951; flyer quote; 36,000 votes; endorsements; Charlie Mae Haynes's 1972 election"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "Haynes among ministers who were the community's principal liaisons with the white power structure"}, {"title": "Third Baptist Church: A Landmark of Faith, Community, and U.S. History", "publisher": "Alamo Square Neighborhood Association", "year": 2026, "url": "https://alamosquare.org/2026/03/third-baptist-church-a-landmark-of-faith-community-and-u-s-history/", "supports": "Haynes pastor 1932-1971; first African American to run for the Board of Supervisors in 1945"}], "photo": null}, {"id": "redevelopment-stamped-blighted", "theme": "redevelopment", "title": "Stamped \"Blighted\" Before the Bulldozers", "year": 1948, "yearEnd": null, "place": "The 1947 redevelopment study zone (Van Ness to Webster, Geary to McAllister), centred near Laguna and Eddy", "precision": "area", "c": [1805.3, 361.5], "block": "0747", "hook": "Years before a single Victorian fell, the city's own planners had written the Western Addition off, in language that singled out the colour of the people living there.", "story": "The paperwork came well before the bulldozers. In 1945 a study called Blight and Taxes, published by the San Francisco Planning and Housing Association, marked the Western Addition for urban renewal. It said the district \"is not white. It is gray, brown, and an indeterminate shade of dirty black\" [1]. The city's 1945 Master Plan praised the area's closeness to the financial district and its slopes for view apartments, then admitted that \"only a relatively small proportion\" of its \"colored and foreign-born families\" could be expected to live in whatever replaced their homes [2]. At the end of 1947 the City Planning Commission proposed a $52 million rebuilding of a 36-block zone enclosed by Van Ness, Webster, McAllister and Geary [3]. In 1948 the Fillmore, where 60 percent of residents were African American, was formally declared blighted [4]. Residents saw what was coming. In July 1948 a multiracial coalition met at the Buchanan Street YMCA, where Dr. Carlton B. Goodlett Jr., head of the local NAACP, warned that \"scores of small businessmen would be wiped out by the plan\" [2]. Demolition started eight years later.", "people": [{"name": "Carlton B. Goodlett Jr.", "role": "Physician, publisher and head of the San Francisco NAACP chapter in 1948"}], "sources": [{"title": "Fillmore Redevelopment", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=Fillmore_Redevelopment", "supports": "1945 'Blight and Taxes' report and its quoted language"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "1945 Master Plan quotation; July 1948 YMCA meeting and Goodlett quotation"}, {"title": "The Queen of the 'Harlem of the West' Brought Glamour and Stars to the Fillmore (Rae Alexandra)", "publisher": "KQED", "year": 2020, "url": "https://www.kqed.org/arts/13874853/the-queen-of-the-harlem-of-the-west-brought-glamour-and-stars-to-the-fillmore", "supports": "End-1947 $52 million proposal for a 36-block zone bounded by Van Ness, Webster, McAllister and Geary"}, {"title": "Sad chapter in Western Addition history ending (Leslie Fulbright)", "publisher": "San Francisco Chronicle", "year": 2008, "url": "https://www.sfgate.com/bayarea/article/Sad-chapter-in-Western-Addition-history-ending-3203302.php", "supports": "Fillmore declared blighted in 1948; 60 percent African American"}], "photo": null}, {"id": "harlem-primalon", "theme": "harlem", "title": "Mirror Balls at the Primalon Ballroom", "year": 1949, "yearEnd": 1961, "place": "Primalon Ballroom, 1223 Fillmore Street (site, between Turk and Eddy)", "precision": "block", "c": [1390.4, 332.2], "block": "0750", "hook": "A 1930s miniature golf course and roller rink on Fillmore became the ballroom where Count Basie, Lionel Hampton and Dizzy Gillespie played to dancing crowds.", "story": "The big indoor-outdoor lot at 1223 Fillmore Street opened in 1934 as the Woodland Dancing Hall, complete with miniature golf links [1]. After the Second World War it became the Brown Bomber Café, a beer garden with roller skating on weekdays and, on weekends, skating and dancing together under suspended mirror balls [1]. In 1949 it became the Primalon Ballroom, run by the McCoy family [1][2]. Top acts included Count Basie, Lionel Hampton and Dizzy Gillespie, alongside local blues bands such as Pee Wee Crayton's [1]. Like the Majestic up the street, which became the Fillmore Auditorium in 1952, the Primalon was one of the dance halls that shifted its bookings toward jazz, blues and R&B [2]. The Primalon closed in 1961, and the structure was torn down in 1974 [1]. Nothing of it survives today [2].", "people": [{"name": "James McCoy", "role": "Proprietor"}, {"name": "Pee Wee Crayton", "role": "Blues guitarist and bandleader"}], "sources": [{"title": "Jazz in San Francisco, Pt. 3: Bagdad-by-the-Bay, 1940s, '50s & '60s", "publisher": "The Syncopated Times", "year": 2021, "url": "https://syncopatedtimes.com/jazz-in-san-francisco-pt-3-bagdad-by-the-bay-1940s-50s-60s/", "supports": "1934 Woodland Dancing Hall; Brown Bomber Café; mirror balls; 1949 Primalon; performers; closed 1961, demolished 1974"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "James and Mary McCoy's Primalon Ballroom at 1223 Fillmore; building no longer extant; Majestic renamed The Fillmore in 1952"}], "photo": null}, {"id": "harlem-melrose-records", "theme": "harlem", "title": "Behind the Counter at Melrose Records", "year": 1950, "yearEnd": null, "place": "Melrose Record Shop, 1226 Fillmore Street (site, between Turk and Eddy)", "precision": "block", "c": [1428.2, 331.1], "block": "0749", "hook": "Before she was famous as Maya Angelou, a young woman sold jazz and blues records on Fillmore Street, beside a Louisiana Navy veteran who would open nightclubs.", "story": "Not every landmark of the Harlem of the West was a nightclub. At the Melrose Record Shop, 1226 Fillmore Street, neighbors bought the latest jazz and blues, and classical records too [1]. A photograph by David Johnson shows the shopfront around 1950 [2]. In the 1950s one of the clerks was a young woman who would become Maya Angelou; in the same years she was dancing professionally at the Purple Onion in North Beach [1]. Later, in I Know Why the Caged Bird Sings, she wrote about the Fillmore's clubs and bars [1]. Working alongside her was Joseph \"Bunny\" Simon, born in 1928 into a family of 16 in Lake Charles, Louisiana. He had joined the Navy at 15, was badly injured at Port Chicago, and settled in San Francisco after his discharge in 1946 [3]. It was his part-time job at Melrose that made clear his passion was music. He went on to open nightclubs of his own, starting on Divisadero Street in 1961 [3]. Like most of the business district around it, the shop's building was later demolished [1].", "people": [{"name": "Maya Angelou", "role": "Writer; worked at the shop in the 1950s"}, {"name": "Joseph \"Bunny\" Simon", "role": "Record clerk, later nightclub owner"}, {"name": "David Johnson", "role": "Photographer"}], "sources": [{"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "Melrose Record Shop at 1226 Fillmore; music sold; Angelou worked there in the 1950s while dancing at the Purple Onion; building no longer extant"}, {"title": "The Fillmore: Black SF", "publisher": "FoundSF", "year": 2016, "url": "https://www.foundsf.org/index.php?title=The_Fillmore:_Black_SF", "supports": "David Johnson photograph of the Melrose record shop at 1226 Fillmore, c. 1950"}, {"title": "Changemakers: Joseph 'Bunny' Simon", "publisher": "University of San Francisco (Sudeepto Chakraborty)", "year": 2020, "url": "https://usfblogs.usfca.edu/sfchangemakers/2020/07/01/joseph-bunny-simon/", "supports": "Simon's biography; part-time job at Melrose alongside Maya Angelou; first club in 1961"}], "photo": null}, {"id": "harlem-booker-t-hotel", "theme": "harlem", "title": "The Booker T., Where the Stars Slept", "year": 1951, "yearEnd": 1970, "place": "Booker T. Washington Hotel, 1540 Ellis Street (site, near Fillmore)", "precision": "block", "c": [1530.9, 146.3], "block": "0725", "hook": "Often unwelcome in downtown hotels, Nat King Cole, Dinah Washington and W.E.B. Du Bois checked into a six-story hotel off Fillmore, where Slim Gaillard sometimes ran the kitchen.", "story": "The six-story, 115-room building at 1540 Ellis opened in 1910 as a rooming house. In the 1940s, as the Hotel Edison, it had a notorious reputation [1]. In August 1951 it was remodeled at a cost of $100,000 and renamed the Booker T. Washington Hotel [1]. Accounts differ over who owned what: one credits a buyer named William Bush, another says the colorful Shirley \"Fats\" Corlett renamed it and the promoter Charles Sullivan bought it [1][2]. What is agreed is that its lobby lounge, booked by Sullivan, became a jazz room; saxophonist Ben Webster opened it on January 31, 1952 [1]. At a time when downtown hotels often turned Black guests away, the Booker T. was where they stayed [3]. A 1953 Sun-Reporter list of guests included Louis Jordan, the Nat King Cole Trio, Dinah Washington, Joe Louis, the Harlem Globetrotters and W.E.B. Du Bois, and Slim Gaillard would take over the kitchen to cook for musicians [1]. Sullivan, the self-made \"Mayor of Fillmore,\" was found shot dead south of Market in 1966; police called it suicide, but the coroner disagreed [2]. The hotel was torn down in 1970, and its address no longer exists [1][3].", "people": [{"name": "Charles Sullivan", "role": "Promoter, the \"Mayor of Fillmore\""}, {"name": "Shirley \"Fats\" Corlett", "role": "Earlier owner"}, {"name": "Ben Webster", "role": "Saxophonist, opened the lounge in 1952"}, {"name": "Slim Gaillard", "role": "Musician who cooked for fellow musicians"}], "sources": [{"title": "The Booker T. Washington Hotel (Harlem of the West project, archived)", "publisher": "Elizabeth Pepin Silva and Lewis Watts, Harlem of the West", "year": 2018, "url": "https://web.archive.org/web/20180729035410/https://www.harlemofthewestsf.com/venues/the-booker-t-washington-hotel/", "supports": "1910 origin; Hotel Edison; 1951 purchase, remodel and renaming; Ben Webster opening; 1953 guest list; Gaillard; demolition 1970"}, {"title": "Who shot the Mayor of Fillmore?", "publisher": "The New Fillmore (Gary Carr)", "year": 2014, "url": "https://newfillmore.com/2014/09/04/who-shot-the-mayor-of-fillmore/", "supports": "Corlett and Sullivan ownership account; Sullivan's 1966 death and disputed ruling"}, {"title": "Looking for the Booker T.", "publisher": "Ben Zotto (Medium, archived)", "year": 2020, "url": "https://web.archive.org/web/2024/https://bzotto.medium.com/looking-for-the-booker-t-cb565824a691", "supports": "Hotel as refuge from segregated downtown hotels; 1540 Ellis no longer exists"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "Charles Sullivan's Booker T. Washington Hotel and Cocktail Lounge at 1540 Ellis; performers lodged there"}], "photo": null}, {"id": "harlem-third-baptist-march", "theme": "harlem", "title": "Marching to McAllister Street", "year": 1952, "yearEnd": null, "place": "Third Baptist Church, 1399 McAllister Street (at Pierce)", "precision": "building", "c": [1144.3, 593.0], "block": "0778", "hook": "In 1952 the oldest Black Baptist congregation in the West tore down a pioneer's mansion with its own hands, and marched in to a modern church.", "story": "Third Baptist began in 1852 as the First Colored Baptist Church of San Francisco, the first African American Baptist congregation west of the Rockies [1]. For almost half a century after 1906 it worshipped at 1299 Hyde Street, far from the wartime Black neighborhood growing up in the Western Addition [2]. In 1950 Rev. Frederick D. Haynes Sr. led the purchase of the northwest corner of Pierce and McAllister, where Captain Charles Goodall's 1859 mansion stood [1]. A newspaper photo caption described congregation members demolishing the house themselves and planning to reuse much of its old timber in the new church [1]. William F. Gunnison designed the sanctuary, with a bell tower and bare cross visible from blocks away; the permit was approved in May 1952 and the building finished that year [1]. A 1953 account recalled how members, fresh from their centenary, \"sang their last praises in the old church, and marched in a phalanx to the new.\" Deborah Johnson, the youngest member, cut the ribbon [1]. Only a few years later the city's other pioneer Black churches followed it west [1][2]. The city made the complex Landmark No. 275 in 2017 [3].", "people": [{"name": "Frederick Douglas Haynes Sr.", "role": "Pastor, 1932-1971"}, {"name": "William F. Gunnison", "role": "Architect"}, {"name": "Deborah Johnson", "role": "Youngest member, cut the opening ribbon"}], "sources": [{"title": "Third Baptist Church Complex, 1399 McAllister Street: Article 10 Landmark Designation Report", "publisher": "San Francisco Planning Department", "year": 2017, "url": "https://default.sfplanning.org/Preservation/landmarks_designation/hp_third_baptist_church_final_draft.pdf", "supports": "Founding in 1852; Goodall mansion site; demolition by members; Gunnison design; 1952 permit; 'marched in a phalanx' quote; ribbon cutting"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "1299 Hyde Street location 1906-1952; move to 1399 McAllister in 1952"}, {"title": "The Old Landmark: Third Baptist Church Moves Closer To Historic Status", "publisher": "Hoodline (Shane Downing)", "year": 2017, "url": "https://hoodline.com/2017/11/the-old-landmark-third-baptist-church-moves-closer-to-historic-status/", "supports": "1952 settlement at Pierce and McAllister; landmark vote in November 2017"}], "photo": {"url": "https://upload.wikimedia.org/wikipedia/commons/9/97/Third_Baptist_Church.jpg", "page": "https://commons.wikimedia.org/wiki/File:Third_Baptist_Church.jpg", "credit": "Kurt Kaiser / Wikimedia Commons", "license": "CC0", "year": 2020}}, {"id": "harlem-blue-mirror", "theme": "harlem", "title": "Leola King's Blue Mirror", "year": 1953, "yearEnd": null, "place": "935 Fillmore Street, between Fulton and McAllister (site)", "precision": "block", "c": [1398.5, 636.9], "block": "0779", "hook": "An Oklahoma-born barbecue cook they called Goldie opened a lounge where Louis Armstrong and Dinah Washington played, then spent decades fighting the bulldozers.", "story": "Leola King was born in Seminole County, Oklahoma, in 1919 and came to San Francisco in 1946 [1][2]. Friends called her Goldie. Her first hit was Oklahoma King's, a barbecue at 1601 Geary that smoked buffalo, deer and quail [1]. In 1953 she opened the Blue Mirror at 935 Fillmore, between Fulton and McAllister, among the first nightclubs in the Bay Area owned by a woman of color [1][3]. It had a circular bar, velvet festoons and molded Greek figurines [1]. Louis Armstrong, Dinah Washington, Lena Horne, Count Basie and Duke Ellington passed through, and pianist Earl Grant played Monday nights [1][3]. Touring performers slept nearby at the Manor Plaza Hotel, 930 Fillmore [4]. Redevelopment took almost everything: Oklahoma King's was taken for about $25,000, the Blue Mirror closed in the early 1960s, and a sheriff evicted her from a later bar in 1974 [1]. \"The way they took everything is criminal,\" she said [1]. For more than half a century she lived in a 29-room house at 711 Scott Street, on Alamo Square [1]. She died in 2015, aged 96 [3].", "people": [{"name": "Leola \"Goldie\" King", "role": "Nightclub owner and entrepreneur"}, {"name": "Earl Grant", "role": "Pianist, Monday nights at the Blue Mirror"}], "sources": [{"title": "Legendary 'Queen of Fillmore' Leola King leaves proud legacy of struggle against Redevelopment", "publisher": "San Francisco Bay View (Lance Burton)", "year": 2015, "url": "https://sfbayview.com/2015/02/legendary-queen-of-fillmore-leola-king-leaves-proud-legacy-of-struggle-against-redevelopment/", "supports": "Birth, arrival 1946, Oklahoma King's, Blue Mirror address, decor, performers, redevelopment losses, quote, 711 Scott Street"}, {"title": "The Queen of the 'Harlem of the West' Brought Glamour and Stars to the Fillmore", "publisher": "KQED (Rae Alexandra)", "year": 2020, "url": "https://www.kqed.org/arts/13874853/the-queen-of-the-harlem-of-the-west-brought-glamour-and-stars-to-the-fillmore", "supports": "Arrival in 1946; Blue Mirror opened 1953 at 935 Fillmore; performers"}, {"title": "Farewell to a Fillmore icon", "publisher": "The New Fillmore (Rochelle Metcalfe)", "year": 2015, "url": "https://newfillmore.com/2015/03/05/farewell-to-a-fillmore-icon/", "supports": "One of the first women of color to own a nightclub; Earl Grant on Mondays; death at 96"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "Leola King's Blue Mirror at 935 Fillmore; performers lodging at the Manor Plaza Hotel, 930 Fillmore"}], "photo": null}, {"id": "redevelopment-leola-king-blue-mirror", "theme": "redevelopment", "title": "The Queen of Fillmore Loses Her Crown", "year": 1953, "yearEnd": 1974, "place": "Site of the Blue Mirror, 935 Fillmore Street", "precision": "block", "c": [1381.2, 633.8], "block": "0779", "hook": "Redevelopment bulldozed her barbecue pit, closed her jazz club and had the sheriff carry her out of her tavern. Leola King fought the Agency for fifty years.", "story": "Leola King came to San Francisco in 1946 and opened Oklahoma King's, a barbecue pit at 1601 Geary that served buffalo, deer and quail. It stood inside A-1. King said she arrived one morning to find the building gone [1]. She was paid about $25,000 for the property and got nothing for the business she lost [2]. In 1953 she opened the Blue Mirror here at 935 Fillmore, a club with a circular bar and velvet festoons where Louis Armstrong and Dinah Washington performed [1][2]. The club was gone by the early 1960s. King said her liquor licence was taken after a set-up, and the Bay Guardian, which reviewed her records, reported that redevelopment reached the business and she was put out without compensation [1][2]. In 1964 she opened the Bird Cage Tavern at 1505 Fillmore. In 1974 the Agency bought that building for A-2, and the sheriff had to remove her [2]. She held two certificates of preference, and trying to redeem them turned into more than twenty years of legal fights [2]. By the late 1990s she had lost nearly everything, including her home at 711 Scott Street near Alamo Square [1]. She died in 2015, aged 96 [3].", "people": [{"name": "Leola King", "role": "Nightclub owner and businesswoman, known as the Queen of Fillmore"}, {"name": "Bobbie Webb", "role": "Saxophonist who played the Blue Mirror"}], "sources": [{"title": "The Queen of the 'Harlem of the West' Brought Glamour and Stars to the Fillmore (Rae Alexandra)", "publisher": "KQED", "year": 2020, "url": "https://www.kqed.org/arts/13874853/the-queen-of-the-harlem-of-the-west-brought-glamour-and-stars-to-the-fillmore", "supports": "Oklahoma King's at 1601 Geary; bulldozing; Blue Mirror at 935 Fillmore opened 1953; licence account; loss of 711 Scott St."}, {"title": "A Half Century of Lies (G.W. Schultz, SF Bay Guardian, 2007)", "publisher": "FoundSF", "year": 2007, "url": "https://www.foundsf.org/index.php?title=A_Half_Century_of_Lies", "supports": "$25,000 payment; Blue Mirror decor; early-1960s loss; Bird Cage at 1505 Fillmore; 1974 eviction by sheriff; two certificates of preference"}, {"title": "Farewell to a Fillmore icon", "publisher": "The New Fillmore", "year": 2015, "url": "https://newfillmore.com/2015/03/05/farewell-to-a-fillmore-icon/", "supports": "Died February 2015 aged 96; Blue Mirror on Fillmore near McAllister"}], "photo": null}, {"id": "redevelopment-a1-school-spared", "theme": "redevelopment", "title": "Everything Came Down but the Schools", "year": 1956, "yearEnd": 1973, "place": "Raphael Weill (now Rosa Parks) Elementary School, 1501 O'Farrell Street", "precision": "building", "c": [1705.4, 136.4], "block": "0723", "hook": "When Western Addition A-1 cleared 108 acres, the plan said to demolish every building except a YMCA and two public schools. This school was one of them.", "story": "The Board of Supervisors approved the Western Addition A-1 redevelopment plan on May 28, 1956 [1]. Its 108 acres ran from Post Street south to Eddy and O'Farrell, and from Franklin west to Broderick. The plan called for demolishing every building except the Buchanan Street YMCA and two public schools: Raphael Weill Elementary, here at 1501 O'Farrell, and Benjamin Franklin (now Gateway High) on Scott Street [2]. Geary, a block north, was widened into an expressway [1]. Clearing the land displaced 1,350 households and 358 businesses, and a relocation office opened in the YMCA in February 1958 [1]. The area's population went from 6,112 before the project to 3,724 after it [2]. The Agency's final relocation report in 1963 claimed that \"two out of three of the residents moved into standard housing\" [1]. The longshoremen's union saw it differently, calling it \"disgraceful that the Redevelopment Agency cannot even find two-thirds of the former residents of A-1\" [3]. Most of the work was finished by March 1973 [1]. The school survived and became Rosa Parks Elementary, where the activist Mary Rogers later volunteered as a parent [4].", "people": [{"name": "Mary Helen Rogers", "role": "Western Addition activist and parent volunteer at the school"}], "sources": [{"title": "Western Addition A-1", "publisher": "Office of Community Investment and Infrastructure (successor to the SF Redevelopment Agency)", "year": null, "url": "https://sfocii.org/completed-project-areas/western-addition-1", "supports": "Plan approval May 28, 1956; Geary widening; 1,350 households and 358 businesses; February 1958 relocation office; 1963 report quotation; completion by March 1973"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "A-1 boundaries and acreage; buildings to be spared incl. Raphael Weill at 1501 O'Farrell; population 6,112 to 3,724"}, {"title": "The ILWU and Western Addition Redevelopment A-2 (Carol Cuenod)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=The_ILWU_and_Western_Addition_Redevelopment_A-2", "supports": "ILWU Local 6 statement about the missing two-thirds of A-1 residents"}, {"title": "Honoring Mary Rogers (Rep. Nancy Pelosi), Congressional Record Vol. 152, Part 3", "publisher": "U.S. Government Publishing Office", "year": 2006, "url": "https://www.govinfo.gov/content/pkg/CRECB-2006-pt3/html/CRECB-2006-pt3-Pg3561-2.htm", "supports": "Mary Rogers volunteered at Raphael Weill, later Rosa Parks, Elementary"}], "photo": null}, {"id": "harlem-third-baptist-pulpit", "theme": "harlem", "title": "A Pulpit for Du Bois and Robeson", "year": 1958, "yearEnd": null, "place": "Third Baptist Church, 1399 McAllister Street", "precision": "building", "c": [1152.9, 603.9], "block": "0778", "hook": "When other San Francisco venues would not have Paul Robeson, a church at McAllister and Pierce did. W.E.B. Du Bois came too.", "story": "Under Rev. F.D. Haynes, Third Baptist became a stage for nationally known Black figures, intellectuals and artists [1]. Du Bois and his wife, the author Shirley Graham Du Bois, chose the church for their West Coast lectures and for Du Bois's 90th birthday celebration; a 1958 photograph shows him addressing the congregation [1]. Dr. Carlton Goodlett, publisher of the Sun-Reporter and a trustee of the church, stayed in close touch with Paul and Eslanda Robeson, and was largely responsible for bringing Robeson to Third Baptist for a concert when all other venues were closed to him [2]. Josephine Baker also appeared there, and a 1958 program advertised Mahalia Jackson [1]. That year Haynes and his church hosted the National Baptist Convention, more than 25,000 Baptists [1]. In the spring of 1960 Haynes invited Martin Luther King Jr. and Ralph Abernathy to a citywide mass meeting on the treatment of minority youth in San Francisco's schools [1]. Others who used its pulpit included Adam Clayton Powell and King himself [3].", "people": [{"name": "W.E.B. Du Bois", "role": "Scholar and activist"}, {"name": "Shirley Graham Du Bois", "role": "Author and activist"}, {"name": "Paul Robeson", "role": "Singer, actor and activist"}, {"name": "Carlton B. Goodlett", "role": "Physician, publisher, church trustee"}, {"name": "Frederick Douglas Haynes Sr.", "role": "Pastor"}], "sources": [{"title": "Third Baptist Church Complex, 1399 McAllister Street: Article 10 Landmark Designation Report", "publisher": "San Francisco Planning Department", "year": 2017, "url": "https://default.sfplanning.org/Preservation/landmarks_designation/hp_third_baptist_church_final_draft.pdf", "supports": "Du Bois lectures and 90th birthday celebration; 1958 photo; Josephine Baker; Mahalia Jackson program; 1958 convention of 25,000; 1960 invitation to King and Abernathy"}, {"title": "The Black Press (Sun-Reporter history and Thomas Fleming interview)", "publisher": "FoundSF", "year": 1999, "url": "https://www.foundsf.org/index.php?title=The_Black_Press", "supports": "Goodlett brought Robeson for a concert at Third Baptist when other venues were closed to him"}, {"title": "The Old Landmark: Third Baptist Church Moves Closer To Historic Status", "publisher": "Hoodline (Shane Downing)", "year": 2017, "url": "https://hoodline.com/2017/11/the-old-landmark-third-baptist-church-moves-closer-to-historic-status/", "supports": "Church as platform for Du Bois, King, Baker, Adam Clayton Powell and Robeson"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "Goodlett as trustee of Third Baptist"}], "photo": null}, {"id": "redevelopment-ame-zion-golden-gate", "theme": "redevelopment", "title": "A Congregation Rebuilds on Golden Gate", "year": 1960, "yearEnd": null, "place": "First A.M.E. Zion Church, 2159 Golden Gate Avenue", "precision": "building", "c": [157.2, 469.2], "block": "1160", "hook": "Its old church on Geary stood inside A-1. The congregation rebuilt out west for $130,000, and its pastor later sat on the Redevelopment Commission.", "story": "From 1912 the A.M.E. Zion congregation worshipped at 1669 Geary Street, at Webster [1]. That corner lay inside what became the A-1 project area, bounded by Post, Franklin, Eddy and O'Farrell, and Broderick [1]. The old church was torn down in the late 1950s. In 1960 the congregation rebuilt here at 2159 Golden Gate Avenue, in a building designed by the architect Robert Batchelor that cost about $130,000 [1]. The Assessor's roll still gives 1960 as its year of construction [2]. Other Black churches were making similar moves. After the war, older congregations were either full or too far from where their members now lived, and their pastors moved them to the Western Addition. Third Baptist built at 1399 McAllister in 1952, and Bethel A.M.E. settled on Laguna Street [1]. By 1960 more than a third of San Francisco's African Americans lived in the Western Addition [1]. The church also kept a voice in how the district was rebuilt. Its pastor, Parree Porter, joined the Redevelopment Commission, taking the seat of Hannibal Williams, who resigned in 1978 after calling his fellow commissioners \"white liberal zookeepers\" [3].", "people": [{"name": "Robert Batchelor", "role": "Architect of the 1960 church"}, {"name": "Parree Porter", "role": "Pastor of First A.M.E. Zion and Redevelopment commissioner"}, {"name": "Hannibal Williams", "role": "WACO leader and Redevelopment commissioner"}], "sources": [{"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "1669 Geary location since 1912; late-1950s demolition; 1960 rebuilding at 2159 Golden Gate by Robert Batchelor for $130,000; other church moves; A-1 boundaries"}, {"title": "Assessor Historical Secured Property Tax Rolls (year built)", "publisher": "City and County of San Francisco, DataSF", "year": 2025, "url": "https://data.sf.gov/Housing-and-Buildings/Assessor-Historical-Secured-Property-Tax-Rolls/wv5m-vpq2", "supports": "Parcel 1160029 (2155–2159 Golden Gate) year built 1960"}, {"title": "Redevelopment and Patronage Politics", "publisher": "FoundSF (based on Chester Hartman and John Mollenkopf)", "year": null, "url": "https://www.foundsf.org/index.php?title=Redevelopment_and_Patronage_Politics", "supports": "Parree Porter of First AME Zion succeeded Hannibal Williams on the Redevelopment Commission; Williams resigned in 1978; 'white liberal zookeepers'"}], "photo": null}, {"id": "redevelopment-st-francis-square", "theme": "redevelopment", "title": "The Longshoremen's Answer: St. Francis Square", "year": 1960, "yearEnd": 1963, "place": "St. Francis Square Cooperative, Quickstep Lane (south of O'Farrell between Laguna and Buchanan)", "precision": "building", "c": [1792.8, 111.5], "block": "0723", "hook": "On land the bulldozers had emptied, a dockworkers' pension fund built a co-op where a three-bedroom share cost $610 and a family of any colour could buy in.", "story": "In 1960 the Redevelopment Agency set aside three blocks of cleared A-1 land for moderate-income garden apartments [1]. Lou Goldblatt, secretary-treasurer of the International Longshore and Warehouse Union (ILWU), wanted the union's growing pension fund put to work: \"I thought there was no reason why that money shouldn't be used to build some low-cost housing\" [1]. The ILWU-PMA trustees set up a Longshore Redevelopment Corporation. Architects Marquis & Stoller and landscape architect Lawrence Halprin designed 299 apartments in twelve three-story buildings arranged around shared courtyards, built in 1962–63 with a 3-1/8 percent federally subsidized mortgage [2]. A share cost $410 for a one-bedroom and $610 for a three-bedroom, and monthly payments ran from $84 to $140 [1]. The sales office advertised the Square as \"open to all.\" In 1964 a new resident, Josephine Solomon, wrote to the Chronicle about \"our marvelous, mixed-up collection of white, brown, and yellow children playing together\" [3]. The co-op paid off its HUD mortgage in 2004 [2]. The city has not yet designated it a landmark, but SF Planning lists it as a proposed one [4].", "people": [{"name": "Lou Goldblatt", "role": "ILWU International Secretary-Treasurer who conceived the project"}, {"name": "Lawrence Halprin", "role": "Landscape architect"}, {"name": "Claude Stoller", "role": "Architect, Marquis & Stoller"}, {"name": "Josephine Solomon", "role": "Early resident"}], "sources": [{"title": "Redevelopment A-1 and Origin of St. Francis Square (Carol Cuenod)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/Redevelopment_A-1_and_Origin_of_St._Francis_Square", "supports": "1960 set-aside; Goldblatt quotation; share prices and monthly payments"}, {"title": "Finding Aid to the St. Francis Square Cooperative, Inc. Collection (SFH 62)", "publisher": "San Francisco History Center, SF Public Library (Online Archive of California)", "year": 2012, "url": "https://oac.cdlib.org/findaid/ark:/13030/c8154ff8", "supports": "299 apartments in twelve buildings; Marquis & Stoller and Halprin; 221(d)(3) 3-1/8% mortgage; 1962–63 construction; 2004 mortgage repayment"}, {"title": "St. Francis Square: How a Union Built Integrated, Affordable Housing in San Francisco (Peter Cole)", "publisher": "JSTOR Daily", "year": 2016, "url": "https://daily.jstor.org/st-francis-square-affordable-housing-san-francisco/", "supports": "'Open to all' marketing; Josephine Solomon's 1964 letter"}, {"title": "Proposed Landmarks", "publisher": "San Francisco Planning", "year": null, "url": "https://sfplanning.org/project/proposed-landmarks", "supports": "St. Francis Square Cooperative Apartments listed as a proposed individual landmark"}], "photo": null}, {"id": "harlem-divisadero-jazz", "theme": "harlem", "title": "Jazz Moves West to Divisadero", "year": 1961, "yearEnd": 1967, "place": "Divisadero and McAllister streets (site of The Playpen)", "precision": "street", "c": [843.1, 593.7], "block": "1180", "hook": "In the 1960s a string of small jazz rooms opened on Divisadero, where Miles Davis, Wes Montgomery and Ike and Tina Turner played.", "story": "In 1961 Joseph \"Bunny\" Simon, a former clerk at the Melrose Record Shop, opened his first club at Divisadero and McAllister. It became known as The Playpen [1]. In a neighborhood torn apart by redevelopment, it was a place where everyone in the Fillmore could gather. Neighbors lined up around the block to drink and dance to the jukebox, and teenagers were let in with chaperones on Sunday afternoons [1]. Upstairs, Redd Foxx, Miles Davis, Wes Montgomery, Sly and the Family Stone and Ike and Tina Turner performed [1]. Simon liked to tell how young Willie Brown opened a campaign office across the street in the early 1960s, and blamed losing the election partly on volunteers who spent their days in the club [1]. Others followed. The Both/And opened at 350 Divisadero in 1965, where Dexter Gordon and Archie Shepp made live records, and in 1967 Herman Warren opened the Half Note in a former coffee shop, with Thelonious Monk among its players [2]. The clubs were friendly rivals: each fielded a softball team, and the losers drank at the winners' bar [2].", "people": [{"name": "Joseph \"Bunny\" Simon", "role": "Owner of The Playpen"}, {"name": "Herman Warren", "role": "Owner of the Half Note"}, {"name": "Willie L. Brown Jr.", "role": "Young politician"}], "sources": [{"title": "Changemakers: Joseph 'Bunny' Simon", "publisher": "University of San Francisco (Sudeepto Chakraborty)", "year": 2020, "url": "https://usfblogs.usfca.edu/sfchangemakers/2020/07/01/joseph-bunny-simon/", "supports": "The Playpen at Divisadero and McAllister, 1961; its crowds and performers; Willie Brown anecdote"}, {"title": "The Lost Jazz Clubs Of Divisadero", "publisher": "Hoodline (Nuala Sawyer)", "year": 2016, "url": "https://hoodline.com/2016/08/the-lost-jazz-clubs-of-divisadero-1471994845/", "supports": "Both/And at 350 Divisadero from 1965 and its recordings; Half Note from 1967 under Herman Warren; softball rivalry"}], "photo": null}, {"id": "harlem-sun-reporter-turk", "theme": "harlem", "title": "The Sun-Reporter's Upstairs Room on Turk", "year": 1963, "yearEnd": null, "place": "1366 Turk Street (site of Dr. Goodlett's office and the Sun-Reporter)", "precision": "block", "c": [1475.6, 348.5], "block": "0749", "hook": "A doctor who won a newspaper in a poker game moved it to Turk Street, where Malcolm X, Muhammad Ali and future mayors came upstairs.", "story": "Dr. Carlton B. Goodlett came to San Francisco in 1945 and opened a medical practice. He soon invested with the dentist Daniel Collins in the Reporter, a Black paper founded in the Fillmore during the war [1]. The paper's longtime editor, Thomas Fleming, later told the story of how they got a second paper, the Sun: its white owner lost about $2,500 to Goodlett at poker one night and offered him the Sun for $1,500 [2]. The two papers became the Sun-Reporter, with the motto \"That no good cause shall lack a champion, and that evil shall not thrive unopposed\" [2]. The sources disagree on some early dates. In 1963 Goodlett moved both his medical office and the paper to his new building at 1366 Turk Street [1][2]. Its upstairs Community Room became a hub: Malcolm X, Muhammad Ali, Dick Gregory and the Black Panthers came through, and politicians from Willie Brown to George Moscone stopped by for advice [2]. Goodlett also led the local NAACP and in 1966 ran for governor, finishing third in the Democratic primary [1][2]. He died in 1997. The Turk Street building is gone [1].", "people": [{"name": "Carlton B. Goodlett", "role": "Physician and publisher"}, {"name": "Thomas C. Fleming", "role": "Editor of the Sun-Reporter"}, {"name": "Daniel Collins", "role": "Dentist and co-publisher"}], "sources": [{"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "Goodlett's arrival in 1945, investment with Collins, 1963 move of office and paper to 1366 Turk; NAACP presidency; building no longer extant"}, {"title": "The Black Press (Thomas Fleming interview and Sun-Reporter history)", "publisher": "FoundSF", "year": 1999, "url": "https://www.foundsf.org/index.php?title=The_Black_Press", "supports": "Poker-game acquisition of the Sun; motto; 1963 move to Turk Street; Community Room visitors; 1966 run for governor"}], "photo": null}, {"id": "institutions-panhandle-freeway", "theme": "institutions", "title": "The Freeway That Never Crossed the Panhandle", "year": 1964, "yearEnd": 1966, "place": "The Panhandle, between Fell and Oak Streets", "precision": "area", "c": [323.3, 1050.9], "block": "1700", "hook": "The state wanted to run an interstate through the Panhandle, the park's oldest planting ground. A folk singer, a rally and three 6-5 votes stopped it.", "story": "The block-wide Panhandle between Fell and Oak was Golden Gate Park's first testing ground. Activist Calvin Welch described it as John McLaren's arboretum, where every tree and bush was planted first to see whether it would survive, which is why it has the park's oldest trees and 21 kinds of eucalyptus [1]. By the 1950s, state highway planners wanted a freeway here, carrying traffic from the Central Freeway through Hayes Valley, partly sunk into the Panhandle, and under Golden Gate Park to link up with Highway 1 at 14th Avenue and Fulton [2]. Supervisors turned down versions 8-3 in 1956 and 6-5 in 1962 [2][3]. On May 17, 1964 the Citizens Committee to Save Golden Gate Park held a rally at the park's Polo Grounds, where folk singer Malvina Reynolds sang 'Cement Octopus' [2]. That October the board rejected the route 6-5 again [3]. The state came back with the plan, and some $250 million in federal interstate money was at stake [2]. On March 21, 1966, the supervisors voted 6-5 against both the Panhandle and Golden Gate freeways [2][3]. In 1966 Reynolds was photographed singing to protesters in the Panhandle itself [1]. The route was taken out of the state highway system in 1972 [3].", "people": [{"name": "Malvina Reynolds", "role": "folk singer who performed at anti-freeway protests"}, {"name": "Calvin Welch", "role": "Haight-Ashbury activist and historian"}], "sources": [{"title": "The Panhandle", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=The_Panhandle", "supports": "Welch quote on the arboretum; 1966 photos of Reynolds in the Panhandle"}, {"title": "The Panhandle Freeway And The Revolt That Saved The Park", "publisher": "Hoodline", "year": 2015, "url": "https://hoodline.com/2015/03/panhandle-freeway-revolt/", "supports": "route, federal funds, May 17, 1964 rally and 'Cement Octopus', votes including March 21, 1966"}, {"title": "The planned Panhandle Freeway of San Francisco (Interstate 80)", "publisher": "Gribblenation", "year": 2024, "url": "http://www.gribblenation.org/2024/07/the-planned-panhandle-freeway-of-san.html", "supports": "1956, 1962, October 1964 and 1966 votes; 1972 deletion"}], "photo": null}, {"id": "modern-1090-page-ballroom", "theme": "modern", "title": "The Ballroom in the Basement", "year": 1965, "yearEnd": 1966, "place": "1090 Page Street (the Albin rooming house)", "precision": "block", "c": [687.2, 1165.4], "block": "1218", "hook": "Under a shabby Page Street rooming house lay an old ballroom with a proscenium arch. The jam sessions held there helped give birth to San Francisco rock.", "story": "In the mid-1960s, 1090 Page Street was a Victorian rooming house. Rod Albin managed it from 1964 and let his brother Peter and other San Francisco State students take over rooms and the basement [4]. Down there, the band later wrote, was \"the ghost of a beautiful old ballroom complete with proscenium arch that was a perfect rehearsal and dance space\" [1]. Chet Helms organised dances and jam sessions in that rosewood-panelled room. The Chronicle's Joel Selvin wrote that musicians who played there went on to form Quicksilver Messenger Service, the Grateful Dead and Big Brother and the Holding Company [2]. Peter Albin, who had started out wanting to write songs for children, formed Big Brother with Sam Andrew. They were joined by guitarist James Gurley and drummer Dave Getz, a cook and art instructor who \"simply asked for the job\" [1]. For about six months the band worked on its sound underground. It made its public debut on January 22, 1966, at Ken Kesey's Trips Festival [1]. Janis Joplin later rehearsed with the band at what Hoodline called the \"Albin House\" [3]. Selvin reported in 2009 that the old house had been torn down long ago [2].", "people": [{"name": "Chet Helms", "role": "Promoter; staged jam sessions in the basement"}, {"name": "Peter Albin", "role": "Bassist, co-founder of Big Brother"}, {"name": "Rod Albin", "role": "Managed the rooming house"}, {"name": "Sam Andrew", "role": "Guitarist, co-founder of Big Brother"}, {"name": "Janis Joplin", "role": "Singer who rehearsed there with Big Brother"}], "sources": [{"title": "The History of Big Brother & the Holding Co.", "publisher": "Big Brother & the Holding Company (Sam Andrew)", "year": null, "url": "https://www.bbhc.com/how-big-brother-got-started/", "supports": "Ballroom quote, members, Helms's dances, six months underground, Trips Festival debut 22 Jan 1966"}, {"title": "The Chronicle's Bay Area Musical History Tour", "publisher": "San Francisco Chronicle (Joel Selvin)", "year": 2009, "url": "https://www.sfgate.com/entertainment/article/The-Chronicle-s-Bay-Area-Musical-History-Tour-3250341.php", "supports": "Rosewood-panelled ballroom, Helms's jam sessions, bands that formed, house torn down"}, {"title": "Summer Of Love Look Back: Janis Joplin's San Francisco", "publisher": "Hoodline (Alisa Scerrato)", "year": 2017, "url": "https://hoodline.com/2017/05/summer-of-love-look-back-janis-joplin-s-san-francisco/", "supports": "Joplin and Big Brother rehearsed at 1090 Page, the 'Albin House'"}, {"title": "Albin Rooming House: Big Brother & The Holding Company Began Here", "publisher": "Rock and Roll Roadmap", "year": null, "url": "https://rockandrollroadmap.com/places/hotels-motels/san-francisco-area-hotels-motels/albin-rooming-house-big-brother-and-the-holding-company-began-here/", "supports": "Rod Albin managed the house from 1964; SF State students took rooms and the basement"}], "photo": null}, {"id": "modern-hayes-street-gay-enclave", "theme": "modern", "title": "Hayes Street's Gay Main Street", "year": 1966, "yearEnd": 2000, "place": "488 Hayes Street (David's House / Marlena's)", "precision": "building", "c": [2020.8, 880.7], "block": "0808", "hook": "Long before the boutiques came, a few blocks of Hayes Street held a gay thrift shop, a drag bar, a gay weekly newspaper and a street fair.", "story": "In the 1960s the Society for Individual Rights, San Francisco's leading gay-rights group, ran the Sirporium on Hayes Street [1][2]. It was a thrift shop that sold items donated by members and used the money to pay for community events [1]. Sources disagree on the address: the city's LGBTQ context statement gives 515 Hayes, while the neighbourhood association gives 525 [1][2]. In the 1970s Dottie's Stardust Lounge, a gay bar, stood at the corner of Hayes and Laguna [2]. In 1984 David's House opened at 488 Hayes, next to David's Garden Cafe. It became the Overpass in 1986 and Marlena's in 1990, a bar remembered for its welcome to older gay men [2]. Next door, from 1983 to 1992, 500 Hayes housed the offices of the San Francisco Sentinel [2]. Founded in the early 1970s, the Sentinel was one of the city's first commercially successful gay weeklies and stopped weekly publication in 1995 [1]. From 1981 to 1990, during the worst years of AIDS, the Lily Street Fair filled a four-block alley nearby [2]. Around the corner at 320 Fell Street, the photographer Daniel Nicoletta ran a studio from 1990 to 2000, where he hosted salons, fundraisers and memorial services [2].", "people": [{"name": "Daniel Nicoletta", "role": "Photographer; ran a studio on Fell Street"}], "sources": [{"title": "Citywide Historic Context Statement for LGBTQ History in San Francisco", "publisher": "San Francisco Planning Department (Donna Graves and Shayne Watson)", "year": 2016, "url": "https://default.sfplanning.org/Preservation/lgbt_HCS/FinalLGBTQ_HCS_March2016.pdf", "supports": "Sirporium at 515 Hayes and its purpose; Sentinel at 500 Hayes, founding and end of weekly run"}, {"title": "LGBTQ History in Hayes Valley", "publisher": "Hayes Valley Neighborhood Association", "year": 2022, "url": "https://hayesvalleysf.org/lgbtq-history-in-hayes-valley/2022/03/", "supports": "Sirporium at 525 Hayes; Dottie's; David's House/Overpass/Marlena's; Sentinel 1983-92; Lily Street Fair; Nicoletta studio"}], "photo": null}, {"id": "redevelopment-waco-mary-rogers", "theme": "redevelopment", "title": "Mary Rogers, WACO and the Bulldozers", "year": 1966, "yearEnd": 1969, "place": "Western Addition A-2 project area (centred near Fillmore and Turk)", "precision": "area", "c": [1434.6, 385.0], "block": "0756", "hook": "She had a ninth-grade education and twelve children. She lay down in front of bulldozers, and she helped take the federal government to court.", "story": "Mary Helen Rogers moved to San Francisco from Texas in 1965, just as the Redevelopment Agency was razing whole blocks of the Western Addition [1]. In March 1966 she and Hannibal Williams took the lead in organizing the Western Addition Community Organization, known as WACO. It brought together churches and tenants, including many residents of St. Francis Square [2]. Rogers had a ninth-grade education, but she became an expert in housing law, and on at least one occasion she lay down in front of the bulldozers [1]. On December 15, 1967, WACO sued the federal housing secretary to stop funding for A-2 [3]. HUD's own staff had found a shortfall of 689 units of relocation housing [3]. In December 1968 Judge Sweigert held that HUD's approval of the relocation plan was \"completely arbitrary and without basis in fact\" and blocked the Agency from forcibly displacing residents until it produced a plan for decent, safe and sanitary housing [3]. The injunction was lifted in March 1969, after HUD approved a revised plan [4]. Rogers kept fighting for forty years, until her death in 2006 [1].", "people": [{"name": "Mary Helen Rogers", "role": "WACO co-founder and housing activist"}, {"name": "Hannibal Williams", "role": "Minister and WACO leader"}, {"name": "Judge Sweigert", "role": "U.S. District Judge, Northern District of California"}], "sources": [{"title": "Mary Rogers -- S.F. community activist (Demian Bulwa)", "publisher": "San Francisco Chronicle", "year": 2006, "url": "https://www.sfgate.com/bayarea/article/Mary-Rogers-S-F-community-activist-2502885.php", "supports": "Arrival 1965; ninth-grade education; lay down before bulldozers; housing-law expertise; death in 2006"}, {"title": "The ILWU and Western Addition Redevelopment A-2 (Carol Cuenod)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=The_ILWU_and_Western_Addition_Redevelopment_A-2", "supports": "March 1966 founding of WACO under Hannibal Williams and Mary Rogers; St. Francis Square residents involved"}, {"title": "Western Addition Community Organization v. Weaver, 294 F. Supp. 433 (N.D. Cal. 1968)", "publisher": "Caselaw Access Project, Harvard Law School", "year": 1968, "url": "https://static.case.law/f-supp/294/cases/0433-01.json", "supports": "Suit filed December 15, 1967; 689-unit deficiency; 'completely arbitrary' finding; injunction against forced displacement"}, {"title": "Western Addition Community Organization v. Romney, 320 F. Supp. 308 (N.D. Cal. 1969)", "publisher": "Caselaw Access Project, Harvard Law School", "year": 1969, "url": "https://static.case.law/f-supp/320/cases/0308-01.json", "supports": "Injunction of December 26, 1968 dissolved March 5, 1969 after HUD's January 29, 1969 approval"}], "photo": null}, {"id": "modern-love-pageant-rally", "theme": "modern", "title": "The Day LSD Became Illegal", "year": 1966, "yearEnd": 1967, "place": "The Panhandle at Masonic Avenue and Fell Street", "precision": "block", "c": [110.2, 943.2], "block": "1208", "hook": "The day California outlawed LSD, the Haight threw a party on the Panhandle, with the Grateful Dead and Big Brother playing, dogs in psychedelic gear and Kesey's bus.", "story": "On October 6, 1966, the day a new California law against LSD took effect, the editors of the San Francisco Oracle staged a \"Love Pageant Rally\" on the Panhandle [1]. Contemporary newspaper accounts put the gathering at the corner of Masonic and Fell, with a traffic jam building along Masonic [2]. Estimates of the crowd ranged from about 500 in one contemporary report to between 1,000 and 3,000 in later retellings [1][2]. The Grateful Dead and Big Brother and the Holding Company played. Ken Kesey's multicoloured bus turned up, carrying \"long-haired children\" and dogs outfitted in \"psychedelic gear\" [2]. Afterwards, organiser Michael Bowen told Richard Alpert, \"People are sure hungry for some communicating,\" and that remark helped inspire the Human Be-In a few months later [1]. The rally was the first of five Grateful Dead appearances in the Panhandle over eight months [4]. Other bands also played free in the grassy strip between Fell and Oak. The most famous was Jimi Hendrix, who played on Jefferson Airplane's flatbed truck one Sunday in June 1967, farther west near Cole Street [3]. On March 8, 2026, musicians revived the flatbed tradition for an estimated 5,000 people. The generator powering the amplifiers ran out of fuel in the middle of \"Wharf Rat\" [4].", "people": [{"name": "Michael Bowen", "role": "Artist and organiser, San Francisco Oracle"}, {"name": "Ken Kesey", "role": "Author; arrived with the Merry Pranksters' bus"}, {"name": "Jimi Hendrix", "role": "Played a free Panhandle show, June 1967"}], "sources": [{"title": "Hungry for Communication: The Love Pageant Rally & Michael Bowen", "publisher": "California Historical Society (Nicole Meldahl)", "year": 2016, "url": "https://californiahistoricalsociety.blogspot.com/2016/10/hungry-for-communication-love-pageant.html", "supports": "Oracle organisers, date and LSD law, crowd estimate, bands, Bowen quote and the Be-In"}, {"title": "October 6, 1966: The Panhandle, San Francisco", "publisher": "Grateful Dead Sources (transcribed 1966 newspaper accounts)", "year": 2017, "url": "http://deadsources.blogspot.com/2017/03/october-6-1966-panhandle-san-francisco.html", "supports": "Masonic and Fell location, ~500 crowd, Kesey's bus, dogs in psychedelic gear, traffic on Masonic"}, {"title": "The Chronicle's Bay Area Musical History Tour", "publisher": "San Francisco Chronicle (Joel Selvin)", "year": 2009, "url": "https://www.sfgate.com/entertainment/article/The-Chronicle-s-Bay-Area-Musical-History-Tour-3250341.php", "supports": "Free concerts between Fell and Oak; Hendrix on the Airplane's flatbed, June 1967, at Oak and Cole"}, {"title": "Grateful Dead Music on a Flatbed Truck in Golden Gate Park's Panhandle", "publisher": "Grateful Web (Gabriel David Barkin)", "year": 2026, "url": "https://www.gratefulweb.com/articles/grateful-dead-music-on-a-flatbed-truck-in-golden-gate-parks-panhandle/", "supports": "Five Dead Panhandle shows from the rally on; the 2026 revival, crowd estimate and generator failure"}], "photo": null}, {"id": "redevelopment-empty-fillmore", "theme": "redevelopment", "title": "When Fillmore Street Went Quiet", "year": 1966, "yearEnd": 1989, "place": "Fillmore Street at Eddy", "precision": "street", "c": [1456.9, 290.7], "block": "0749", "hook": "The \"Harlem of the West\" had clubs, barbershops and banks. After A-2, the stretch of Fillmore down to Turk stayed empty lots for decades.", "story": "A-2 was far bigger than A-1. It covered 60 blocks and 277 acres surrounding the first project, and the Board of Supervisors approved it on October 15, 1964 [1]. Work did not start until May 1966, because HUD would not pay for projects while Proposition 14, the state measure that barred anti-discrimination laws in housing, was in force [1]. Then the clearance came. Of 180 Black-owned businesses operating in A-2, only 48 were successfully relocated, and the other 132 went out of business [2]. Fillmore Street between Pine and Turk, famous in the 1950s as the \"Harlem of the West,\" was left as barren lots for decades [2]. City officials later put the toll of Western Addition redevelopment at 883 businesses shut and 4,729 households forced out [3]. A co-op historian wrote that through the 1980s, the commercial life of lower Fillmore came to one Safeway and a few fast-food chains [4]. Willie Brown, looking back years later, said: \"The black businesses, which had been viable, wonderful, and productive, were totally destroyed. The entertainment world for African Americans virtually ceased to exist in San Francisco\" [2].", "people": [{"name": "Willie Brown", "role": "Former Mayor of San Francisco"}], "sources": [{"title": "Western Addition A-2", "publisher": "Office of Community Investment and Infrastructure (successor to the SF Redevelopment Agency)", "year": null, "url": "https://sfocii.org/completed-project-areas/western-addition-2", "supports": "A-2 approval October 15, 1964; 277 acres; delay until May 1966 over Proposition 14"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "60 blocks; 180 Black-owned businesses, 48 relocated; Fillmore between Pine and Turk left vacant; Willie Brown quotation"}, {"title": "Sad chapter in Western Addition history ending (Leslie Fulbright)", "publisher": "San Francisco Chronicle", "year": 2008, "url": "https://www.sfgate.com/bayarea/article/Sad-chapter-in-Western-Addition-history-ending-3203302.php", "supports": "883 businesses shuttered; 4,729 households forced out"}, {"title": "The ILWU and Western Addition Redevelopment A-2 (Carol Cuenod)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=The_ILWU_and_Western_Addition_Redevelopment_A-2", "supports": "Through the 1980s, one Safeway and several fast-food chains on lower Fillmore"}], "photo": null}, {"id": "modern-janis-lyon-street", "theme": "modern", "title": "Janis Lived Next Door", "year": 1967, "yearEnd": 1968, "place": "122 Lyon Street", "precision": "building", "c": [397.7, 1104.7], "block": "1220", "hook": "Tour guides have pointed at four different Lyon Street houses as Janis Joplin's. Her driver's license points to just one of them.", "story": "During the Summer of Love, Janis Joplin lived in a small flat on Lyon Street, across from the Panhandle. The Chronicle later wrote that she walked her dog around the neighbourhood and browsed the shops on Haight Street [3]. Her exact address has been muddled ever since. In 1999 a nonprofit announced a new 20-bed rehab centre for drug-addicted mothers at 124 Lyon and said it was Joplin's old house. Media as far away as England repeated the claim. Then experts produced a copy of her 1960s driver's license, which gave her address as 122 Lyon, the house next door [1]. According to local lore, she had lived in any of four houses on the block [1]. \"It just shows how mythological the whole thing is,\" said Country Joe McDonald, her boyfriend at the time, who had lived with her there for \"three somewhat fuzzy months\" [1]. Her roommate, the clothing designer Linda Gravenites, said they loved the flat but it had only one bedroom, so in 1968 they moved to Noe Street [1][2]. The confusion never quite ended. A 2009 Chronicle guide listed the apartment as 112 Lyon, No. 3 [3]. In 2014 the six-unit Queen Anne at 122 Lyon went on the market for $1.7 million [2].", "people": [{"name": "Janis Joplin", "role": "Singer, tenant of Apartment 3"}, {"name": "Linda Gravenites", "role": "Roommate and clothing designer"}, {"name": "Country Joe McDonald", "role": "Musician, Joplin's boyfriend in 1967"}], "sources": [{"title": "Oops! Turns Out Janis Joplin Lived Next Door", "publisher": "San Francisco Chronicle (Kevin Fagan)", "year": 1999, "url": "https://www.sfgate.com/news/article/Oops-Turns-Out-Janis-Joplin-Lived-Next-Door-2929576.php", "supports": "Rehab centre mix-up, driver's license at 122 Lyon, four-houses lore, McDonald quotes, Gravenites and the move to Noe Street"}, {"title": "Janis Joplin's Apartment For Sale", "publisher": "Hoodline (Nuala Sawyer)", "year": 2014, "url": "https://hoodline.com/2014/01/janis-joplin-s-apartment-for-sale/", "supports": "Apartment 3, license as only official record, six-unit Queen Anne, $1.7 million listing"}, {"title": "The Chronicle's Bay Area Musical History Tour", "publisher": "San Francisco Chronicle (Joel Selvin)", "year": 2009, "url": "https://www.sfgate.com/entertainment/article/The-Chronicle-s-Bay-Area-Musical-History-Tour-3250341.php", "supports": "Upstairs flat across from the Panhandle, walking her dog, listed as 112 Lyon St. No. 3"}], "photo": null}, {"id": "modern-628-divisadero", "theme": "modern", "title": "The Many Lives of 628 Divisadero", "year": 1967, "yearEnd": 2004, "place": "628 Divisadero Street (The Independent)", "precision": "building", "c": [853.9, 828.1], "block": "1202", "hook": "Jazz, punk, Nirvana, lesbian dance nights, turntablists: behind one plain red front on Divisadero, the city's music changed about every ten years.", "story": "\"Supposedly, Thelonious Monk played here back when this was a hot jazz strip,\" Justice League owner Michael O'Connor told the Chronicle in 1998. He wanted to put up a plaque listing every club the room had been [2]. Accounts disagree on the 1960s name. The Bay Guardian called it the Half Note, a jazz club with a house band that included George Duke and a young Al Jarreau [1]. The Chronicle named the Both/And as a past tenant, where Janis Joplin first heard Big Mama Thornton sing \"Ball and Chain\" [2]. In the early 1980s it was the VIS Club, playing punk, new wave and experimental music. By the late 1980s it had become the Kennel Club, where Nirvana opened for Tad [1][2]. The DJ Page Hodel's roving club The Box drew hundreds of gay men and lesbians to monthly dances there [3]. After the short-lived Crash Palace failed, O'Connor opened the Justice League around 1997. The artist Barry McGee (\"Twist\") painted its murals, and the club hosted drum-and-bass, hip-hop and house nights [2]. In February 2004 it reopened as The Independent, a 500-capacity room. \"The night we opened, the fire department [was] signing everything off while the band was sound-checking,\" recalled owner Allen Scott [1].", "people": [{"name": "Michael O'Connor", "role": "Founder of the Justice League"}, {"name": "Allen Scott", "role": "Managing owner of The Independent"}, {"name": "Page Hodel", "role": "DJ behind The Box and Club Q"}, {"name": "Barry McGee", "role": "Artist ('Twist'), painted the Justice League murals"}], "sources": [{"title": "A very Indy decade", "publisher": "San Francisco Bay Guardian (Emma Silvers)", "year": 2014, "url": "https://sfbgarchive.48hills.org/sfbgarchive/2014/02/11/very-indy-decade/?_sf_s=A+Very+Indy+Decade", "supports": "Half Note, VIS Club, Kennel Club, Justice League, February 2004 opening, 500 capacity, Allen Scott quote"}, {"title": "And Music for All / Divisadero nightclub Justice League carves out an eclectic niche", "publisher": "San Francisco Chronicle (James Sullivan)", "year": 1998, "url": "https://www.sfgate.com/entertainment/article/And-Music-for-All-Divisadero-nightclub-Justice-3009924.php", "supports": "O'Connor's Monk quote, Both/And and Joplin, Nirvana opening for Tad, Crash Palace, McGee murals, weekly nights"}, {"title": "Citywide Historic Context Statement for LGBTQ History in San Francisco", "publisher": "San Francisco Planning Department", "year": 2016, "url": "https://default.sfplanning.org/Preservation/lgbt_HCS/FinalLGBTQ_HCS_March2016.pdf", "supports": "The Box's monthly dance at the Kennel Club drawing hundreds of gays and lesbians"}], "photo": null}, {"id": "redevelopment-certificates-of-preference", "theme": "redevelopment", "title": "The Promise Printed on a Certificate", "year": 1967, "yearEnd": null, "place": "1800 block of Ellis Street", "precision": "block", "c": [999.8, 176.7], "block": "0729", "hook": "Displaced families were given a certificate promising they could come back. On this one block of Ellis Street, the city's list of affected addresses runs to 99 entries.", "story": "When the Agency took a house, it handed the head of household a certificate promising preference for housing built later. In 2008 an Agency spokesman admitted, \"there wasn't a lot of housing built for a long time\" [1]. A state law passed in 1969 made that priority a legal requirement, and the Agency's Certificate of Preference Program carried it out [2]. By 2023, the Public Press reported, city agencies had issued almost 7,000 certificates since the program began in 1967, and only 1,483 had ever been used [3]. Many of them, reporters found, were never honoured [3]. Today the city publishes the addresses of displaced households, with no names attached. The Western Addition A-2 list has 4,792 entries. The 1800 block of Ellis Street alone accounts for 99 of them, spread across 52 street numbers, and many list a flat, a floor or a basement [4]. Under a 2021 state law, descendants became eligible as well, and in January 2022 the city began issuing certificates to the children and grandchildren of people who lost their homes [3]. Investigators working with a city partner have tracked down eligible families as far away as Texas, the Carolinas and Georgia [3].", "people": [], "sources": [{"title": "Sad chapter in Western Addition history ending (Leslie Fulbright)", "publisher": "San Francisco Chronicle", "year": 2008, "url": "https://www.sfgate.com/bayarea/article/Sad-chapter-in-Western-Addition-history-ending-3203302.php", "supports": "Certificates given to heads of household; spokesman Benjamin Ibarra's quotation"}, {"title": "Certificate of Preference Program", "publisher": "Office of Community Investment and Infrastructure", "year": null, "url": "https://sfocii.org/certificate-preference-program", "supports": "1969 state law creating the priority; Certificate of Preference Program"}, {"title": "Housing Program to Redress Urban Renewal Could Get Boost From SF Reparations Plan (Madison Alvarado)", "publisher": "San Francisco Public Press", "year": 2023, "url": "https://www.sfpublicpress.org/housing-program-to-redress-urban-renewal-could-get-boost-from-sf-reparations-plan/", "supports": "Almost 7,000 certificates since 1967, 1,483 exercised; many never honoured; 2021 descendant law; January 2022 first descendant certificates; where displaced families went"}, {"title": "Certificate of Preference displacement addresses (Western Addition A-2, Hunters Point and Yerba Buena list, March 2026)", "publisher": "SF Mayor's Office of Housing and Community Development, SF.gov", "year": 2026, "url": "https://www.sf.gov/certificate-preference-displacement-addresses", "supports": "4,792 Western Addition entries; 99 entries across 52 street numbers on the 1800 block of Ellis Street (count made from the published spreadsheet)"}], "photo": null}, {"id": "redevelopment-bethel-freedom-west", "theme": "redevelopment", "title": "The Church That Built a Co-op", "year": 1968, "yearEnd": 1973, "place": "Bethel A.M.E. Church, 916 Laguna Street (corner of Golden Gate Avenue)", "precision": "building", "c": [1871.9, 526.2], "block": "0770", "hook": "As A-2 flattened the blocks around it, San Francisco's oldest Black congregation stayed put, built a new sanctuary, and sponsored 382 co-op homes next door.", "story": "Bethel A.M.E. traces its roots to a meeting house dedicated in 1852 as the pioneer Black congregation of San Francisco. By its own history, it moved to 916 Laguna Street on January 21, 1945 [1]. The church stood inside the part of A-2 that was cleared most completely. Between Ellis, Gough, Fulton and Webster, an area that had held about 2,500 Victorian-era houses was clear-cut entirely, and most of the replacement housing was two- and three-story townhouses built from the late 1960s into the early 1970s [2]. Bethel stayed and rebuilt. Under the Rev. J. Austell Hall it put up a new sanctuary and education building (1968–72 by the church's count, 1969–73 by the city's) and started a credit union in 1969 [1][2]. Hall also wanted housing, so the church sponsored Freedom West, which became the largest cooperative in the Western Addition [3]. It has 382 co-op units on about 11 acres bounded by Golden Gate, Gough, Fulton and Laguna, and the church stands at its corner [4]. Bethel went on to run Fellowship Manor for seniors, and later Prince Hall Apartments, Laurel Gardens and Thomas Paine Square [1]. A current plan, Freedom West 2.0, proposes to rebuild all 382 units [4].", "people": [{"name": "J. Austell Hall", "role": "Pastor of Bethel A.M.E. and founder of Freedom West"}], "sources": [{"title": "History of Bethel A.M.E. Church, San Francisco, 1852–2019", "publisher": "Bethel AME Church San Francisco", "year": 2019, "url": "https://www.bethelamecsf.org/about-us", "supports": "1852 founding; move to 916 Laguna on January 21, 1945; 1968–72 sanctuary; 1969 credit union; Fellowship Manor and later housing"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "Clear-cutting of ~2,500 Victorians between Ellis, Gough, Fulton and Webster; townhouse replacement housing; 1969–73 new facility"}, {"title": "The ILWU and Western Addition Redevelopment A-2 (Carol Cuenod)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=The_ILWU_and_Western_Addition_Redevelopment_A-2", "supports": "Freedom West the largest Western Addition co-op, sponsored by Bethel AME at its corner"}, {"title": "Freedom West", "publisher": "San Francisco Planning", "year": null, "url": "https://sfplanning.org/project/freedom-west", "supports": "382 co-op units on 11 acres; boundaries; Rev. Hall's vision; Freedom West 2.0 proposal"}], "photo": null}, {"id": "victorian-rainbow-house", "theme": "victorian", "title": "The Rainbow House on Steiner Street", "year": 1968, "yearEnd": null, "place": "908 Steiner Street, between Fulton and McAllister", "precision": "building", "c": [1291.6, 633.4], "block": "0779", "hook": "A redevelopment official told Maija Peeples-Bright to paint her Victorian beige. She painted it every colour she could find instead, with a fibreglass alligator in the window.", "story": "Contractor P. O. Chandler built 908 Steiner in 1888 for Niels Iverson, a Danish immigrant who had sailed round Cape Horn in 1848. SF Heritage gives the builder as R. O. Chandler [1][2]. By the 1960s the house had spent years as a St. Anthony Dining Room shelter for homeless men [1]. Then the artist Maija Peeples-Bright and her husband David Zack bought it for $17,000, with $5,000 from her father [1]. When a city redevelopment agent suggested beige, she said no. \"I liked color. I decided to paint it multiple colors,\" she recalled. She used marine enamel, and passers-by sometimes climbed the scaffold to help [1]. She added a peacock head in a gable and a 10-foot Nile alligator in an upper window [1][2]. A 1968 Chronicle story described an exterior \"painted in five different psychedelic hues\" [3]. The Saturday Evening Post and Progressive Architecture wrote it up too, and the house became a stop for tourists [1][2]. Artists of the Funk movement gathered there. A later owner called it the city's first \"Painted Lady\" [1].", "people": [{"name": "Maija Peeples-Bright", "role": "artist, owner and painter of the house"}, {"name": "David Zack", "role": "art critic, co-owner"}, {"name": "Niels Iverson", "role": "first owner, 1888"}], "sources": [{"title": "'Painted Lady' for sale for $1.6 million", "publisher": "San Francisco Chronicle / SFGATE (Dana Perrigan)", "year": 2009, "url": "https://www.sfgate.com/realestate/article/Painted-Lady-for-sale-for-1-6-million-3252522.php", "supports": "1888, Chandler, Iverson; shelter; purchase price and $5,000; beige suggestion and quote; marine enamel; alligator; tourists; Funk artists; 'first Painted Lady'"}, {"title": "Rainbow Victorians and the Colorist Era in San Francisco", "publisher": "San Francisco Heritage (Kerri Young)", "year": 2020, "url": "https://sfheritage.org/features/colorfully-painted-victorians", "supports": "R. O. Chandler; peacock and alligator; Saturday Evening Post, Chronicle 1968, Progressive Architecture 1969"}, {"title": "The Contagious Joy of Maija Peeples-Bright's Animal-Filled World", "publisher": "KQED (Sarah Hotchkiss)", "year": 2023, "url": "https://www.kqed.org/arts/13934441/8-over-80-maija-peeples-bright/", "supports": "Purchase of 908 Steiner; 1968 Chronicle description 'five different psychedelic hues'"}], "photo": null}, {"id": "harlem-bethel-ame", "theme": "harlem", "title": "Bethel A.M.E. Leaves Chinatown for Laguna", "year": 1969, "yearEnd": null, "place": "Bethel A.M.E. Church, 916 Laguna Street", "precision": "building", "c": [1885.9, 526.2], "block": "0770", "hook": "After most of a century on Powell Street in Chinatown, a pioneer Black congregation followed its people west, then helped house them.", "story": "Bethel A.M.E. was one of San Francisco's three pioneer African American churches. Since the nineteenth century it had worshipped at 1207 Powell Street in Chinatown [1]. After the war the old downtown churches were full, and far from where the city's fast-growing Black population now lived. One by one their pastors moved to the Western Addition [1]. In the late 1950s Bethel bought an old, disused church building on Laguna Street. When that grew too cramped, the congregation replaced it with a new church, which it moved into in 1969 [1][2]. Like Third Baptist and A.M.E. Zion, the new building rejected traditional church architecture in favor of strong, simple geometric shapes and plain walls [2]. Bethel then became a builder. During the Western Addition A-2 redevelopment it partnered with the Redevelopment Agency on affordable housing [2]. It sponsored Freedom West, the area's largest co-op, spread over four blocks at the church's corner, and also operates Laurel Gardens, Prince Hall Apartments, Thomas Paine Square and Fellowship Manor [3].", "people": [], "sources": [{"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department (Tim Kelley, Christopher VerPlanck, Alfred Williams)", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "Bethel at 1207 Powell Street; postwar moves west; late-1950s purchase of old church on Laguna; new facility 1969-73"}, {"title": "Third Baptist Church Complex, 1399 McAllister Street: Article 10 Landmark Designation Report", "publisher": "San Francisco Planning Department", "year": 2017, "url": "https://default.sfplanning.org/Preservation/landmarks_designation/hp_third_baptist_church_final_draft.pdf", "supports": "Bethel moved into its new building at 916 Laguna in 1969; its modern design; partnership with the Redevelopment Agency on affordable housing"}, {"title": "The ILWU and Western Addition Redevelopment A-2", "publisher": "FoundSF (Carol Cuenod)", "url": "https://www.foundsf.org/index.php?title=The_ILWU_and_Western_Addition_Redevelopment_A-2", "year": null, "supports": "Freedom West co-op sponsored by Bethel A.M.E.; the church's other housing developments"}], "photo": null}, {"id": "institutions-sacred-heart-panthers", "theme": "institutions", "title": "Panther Breakfasts and an FBI Plant", "year": 1969, "yearEnd": 1972, "place": "Sacred Heart Church basement hall, 554 Fillmore Street", "precision": "building", "c": [1453.8, 1019.6], "block": "0828", "hook": "A Catholic parish fed up to 100 children a day with the Black Panthers. Then the FBI planted hate-filled coloring books in its basement.", "story": "Father Eugene Boyle became pastor of Sacred Heart in 1968, having already marched with Cesar Chavez from Delano to Sacramento in 1966 [1][2]. In 1969 the Black Panther Party, which had approached most of the churches in the area, came to Sacred Heart. They 'finally came to us on a lark,' Boyle recalled [1]. The parish opened its basement hall and kitchen, and the Breakfast Program for Children began there on March 10, 1969, feeding 75 to 100 local children a day, many of them pupils at the parish school [1]. Police and the FBI took notice. That year San Francisco police told the McClellan Senate investigations committee that Boyle was letting the Panthers hand out coloring books that showed police as pigs [1]. The Panthers had printed a few but never distributed them. In 1975 the Church Committee revealed that the FBI had planted the books in the church basement as part of its campaign against the party [1]. The episode cost the program liberal support, but it carried on [1]. The parish also hosted anti-war and SF State student activists, and on September 21, 1970 Boyle said Mass there for the United Farm Workers' lettuce boycott, whose San Francisco campaign started at Sacred Heart [1][3].", "people": [{"name": "Father Eugene Boyle", "role": "pastor of Sacred Heart, 1968-1972, civil rights activist"}], "sources": [{"title": "Landmark Designation Report: Sacred Heart Parish Complex (Landmark No. 316)", "publisher": "San Francisco Planning Department", "year": 2016, "url": "https://files.sfplanning.org/documents/preservation/LM316.pdf", "supports": "Boyle's background, 1969 breakfast program, numbers served, coloring-book affair and FBI plant, UFW Mass"}, {"title": "Supervisors Landmark Historic Sacred Heart Parish Complex", "publisher": "Office of Supervisor Dean Preston", "year": 2024, "url": "https://www.deanprestonsf.com/press-releases/supervisors-landmark-historic-sacred-heart-parish-complexnbsp", "supports": "Boyle as pastor 1968-1972 and civil rights activist"}, {"title": "Sacred Heart Church Could Be Designated A Landmark", "publisher": "Hoodline", "year": 2015, "url": "https://hoodline.com/2015/05/sacred-heart-church-could-be-designated-a-landmark/", "supports": "Panther breakfasts, activist meetings, 1970 lettuce boycott launch"}], "photo": null}, {"id": "redevelopment-loren-miller-homes", "theme": "redevelopment", "title": "Co-ops Built on the Square's Formula", "year": 1972, "yearEnd": null, "place": "Loren Miller Homes, 937 McAllister Street", "precision": "building", "c": [1777.3, 638.4], "block": "0782", "hook": "Once St. Francis Square showed that a pension fund could house working families, Black union leaders used the same formula to build co-ops in A-2.", "story": "In 1964, while A-2 was still being planned, the ILWU and its architects sent Mayor Shelley a proposal. Build first on vacant land, it said, and move no family until low- and moderate-income housing was ready for them in the Western Addition. Keep costs down with cheap land, low-interest loans, tax breaks and sponsors willing to forgo profit. \"Basically,\" one co-op historian wrote, \"it was the formula which made St. Francis Square possible\" [1]. The union's plan also gave current residents first priority as new housing was finished, and the ILWU helped local African American groups build their own co-ops modeled on the Square [2]. Three of them are nearby: Loren Miller Homes here at 937 McAllister, Ammel Park at 656 Grove, and Martin Luther King–Marcus Garvey Square at 1680 Eddy [2]. Loren Miller Homes and Amel Park (the spelling varies between sources) were sponsored by the Labor Assembly for Community Action, a group led by Black ILWU leaders including Bill Chester and Leroy King [1]. The Assessor's roll dates the Loren Miller Homes building to 1972 [3]. In 1981 Leroy King became a commissioner of the Redevelopment Agency [4].", "people": [{"name": "Bill Chester", "role": "ILWU leader, Labor Assembly for Community Action"}, {"name": "Leroy King", "role": "ILWU leader; Redevelopment commissioner from 1981"}], "sources": [{"title": "The ILWU and Western Addition Redevelopment A-2 (Carol Cuenod)", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=The_ILWU_and_Western_Addition_Redevelopment_A-2", "supports": "1964 ILWU relocation proposal and its terms; quotation; Labor Assembly for Community Action sponsorship by Bill Chester and Leroy King"}, {"title": "San Francisco African American Citywide Historic Context Statement (Final Draft)", "publisher": "San Francisco Planning Department", "year": 2015, "url": "https://default.sfplanning.org/Preservation/african_american_HCS/HP_AAHCS_Final_Draft_01.08.15.pdf", "supports": "First priority for current residents; co-ops modeled on St. Francis Square at 937 McAllister, 656 Grove and 1680 Eddy"}, {"title": "Assessor Historical Secured Property Tax Rolls (year built)", "publisher": "City and County of San Francisco, DataSF", "year": 2025, "url": "https://data.sf.gov/Housing-and-Buildings/Assessor-Historical-Secured-Property-Tax-Rolls/wv5m-vpq2", "supports": "Parcel 0782036 (937 McAllister) year built 1972"}, {"title": "Redevelopment and Patronage Politics", "publisher": "FoundSF (based on Chester Hartman and John Mollenkopf)", "year": null, "url": "https://www.foundsf.org/index.php?title=Redevelopment_and_Patronage_Politics", "supports": "Leroy King became a Redevelopment Agency commissioner in 1981"}], "photo": null}, {"id": "redevelopment-victorians-beideman-place", "theme": "redevelopment", "title": "Twelve Victorians Roll West", "year": 1974, "yearEnd": null, "place": "33–35 Beideman Street, Beideman Place", "precision": "building", "c": [886.4, 97.7], "block": "1100", "hook": "Over three stormy November weekends, a convoy of condemned Victorians crept a mile west through the Western Addition. Eight of them ended up on this narrow alley.", "story": "In late 1971 the new San Francisco Architectural Heritage group and the city's Landmarks Board picked out the best Victorians still standing in A-2 [1]. The Agency set aside 19 of them to sell for nominal sums, but 13 would have to be moved. Only two sold, and one was knocked down by mistake [1]. To buy time, Heritage entered minimum bids on the 12 that remained. The Agency got a $150,000 grant to cover moving costs, so a buyer needed only about $20,000 [1]. Over three weekends in November 1974 the houses moved west, most of them from the block where Opera Plaza now stands. Crews had to shift phone and power lines and Muni overhead wires along the way [1][2]. Eight of the houses ended up together along Beideman Place, the alley between Scott, Divisadero, Eddy and O'Farrell [1]. One of them, 736–738 Franklin, had been restored by 1977 and renumbered 33–35 Beideman Street [2]. The rescue was bittersweet. Some houses landed on lots where other Victorians had been demolished, and many low-income Black residents resented a rescue led, and bought into, mostly by white, upper-middle-class people [3]. About 2,500 other Victorians were demolished [3].", "people": [{"name": "Charles Hall Page", "role": "Co-founder of San Francisco Architectural Heritage"}, {"name": "Mrs. Ernest Ophuls", "role": "Heritage board member who entered minimum bids"}], "sources": [{"title": "Heritage 50: Moving Days (Christopher VerPlanck)", "publisher": "San Francisco Heritage", "year": 2021, "url": "https://www.sfheritage.org/news/heritage-50-moving-days/", "supports": "1971 selection; 19 houses, 2 sold, 1 demolished; minimum bids on 12; $150,000 grant; ~$20,000 buyer cost; November 1974 moves; eight to Beideman Place"}, {"title": "Heritage 50: On the Move in 1974 (Woody LaBounty)", "publisher": "San Francisco Heritage", "year": 2021, "url": "https://www.sfheritage.org/news/on-the-move-in-1974/", "supports": "Opera Plaza block origin; 736–738 Franklin restored by 1977 as 33–35 Beideman"}, {"title": "Moving Victorians in the Fillmore", "publisher": "FoundSF", "year": null, "url": "https://www.foundsf.org/index.php?title=Moving_Victorians_in_the_Fillmore", "supports": "Houses moved onto lots of demolished Victorians; resentment among low-income Black residents; 2,500 Victorians demolished"}], "photo": null}, {"id": "victorian-722-steiner", "theme": "victorian", "title": "The Corner House That Nearly Fell", "year": 1975, "yearEnd": 2022, "place": "722 Steiner Street, at Grove", "precision": "building", "c": [1274.2, 800.8], "block": "0803", "hook": "The oldest and largest house on Postcard Row came through the 1906 quake and was later marked for demolition. In 1975 someone bought it for $65,000.", "story": "The corner house at 722 Steiner, the oldest of the Postcard Row group, was Matthew Kavanaugh's own home [1][2]. It came through the 1906 earthquake, but by the 1970s it was slated for demolition. It survived that threat too and was restored [2][3]. Michael Shannon bought it in 1975 for $65,000 [4]. By 2010 it was marketed as \"The Shannon-Kavanaugh House\", and it paid its way with movie and TV shoots, advertising, tours, weddings and parties [2]. It was listed that year at just under $4 million and then went through years of cuts, default and scheduled foreclosure auctions [3]. In 2014 it finally sold off-market for $3.1 million [1][4]. The new owners repainted it from its longtime spearmint green to a new palette [4]. When they listed it in 2022 at $5.75 million, the agents said it had also been home to José Sarria, the drag performer and activist who in 1961 became the first openly gay candidate for public office [1].", "people": [{"name": "Matthew Kavanaugh", "role": "builder and first occupant"}, {"name": "Michael Shannon", "role": "owner from 1975"}, {"name": "José Sarria", "role": "reported former resident (per 2022 listing agents)"}], "sources": [{"title": "One of San Francisco's iconic Painted Ladies on Alamo Square could be yours for $5.75M", "publisher": "SFGATE (Anna Marie Erwert)", "year": 2022, "url": "https://www.sfgate.com/realestate/article/Iconic-Painted-Lady-for-sale-17009758.php", "supports": "722 built 1892, oldest and largest, Kavanaugh's home; 2014 purchase at $3.1M; listing agents' statement about José Sarria"}, {"title": "Postcard Row's Postman's Home Hits The Market (722 Steiner)", "publisher": "SocketSite", "year": 2010, "url": "https://socketsite.com/archives/2010/02/722_steiner_postcard_rows_postmans_home_hits_the_market.html", "supports": "Slated for demolition in the 1970s, restored; 'Shannon-Kavanaugh House'; income from films, TV, events"}, {"title": "Postcard Row Home Survives Another Threat, Back On The Market", "publisher": "SocketSite", "year": 2014, "url": "https://socketsite.com/archives/2014/03/a_postcard_row_home_survives_foreclosure_returns_to_the.html", "supports": "Survived 1906; listing and foreclosure history 2010–2014"}, {"title": "Painted Ladies' Corner Cousin Is Yours For $5.75M", "publisher": "The Front Steps", "year": 2022, "url": "https://thefrontsteps.com/2022/03/23/722-steiner-painted-ladies/", "supports": "Michael Shannon bought in 1975 for $65,000; sold 2014 for $3.1M; repainted from spearmint"}], "photo": null}, {"id": "victorian-painted-ladies-book", "theme": "victorian", "title": "The Book That Named the Painted Ladies", "year": 1978, "yearEnd": null, "place": "Postcard Row, 710–720 Steiner Street", "precision": "block", "c": [1286.1, 820.7], "block": "0803", "hook": "By the 1970s, San Francisco's Victorians were blooming into three, four and five colours. In 1978 a photographer and two writers gave the movement its name.", "story": "The colour revolution started with artists. SF Heritage credits the painter Butch Kardum with trying intense blues and greens on his own Italianate house in 1963. His neighbours hated it at first, but soon his whole block had been repainted just as brightly [1]. By the 1970s colour consultants such as Bob Buckter, known as \"Dr. Color\", were leaving their business cards on newly painted houses [1]. In 1978 Dutton published an 80-page book by the photographer Morley Baer and the writers Elizabeth Pomada and Michael Larsen. They called it Painted Ladies: San Francisco's Resplendent Victorians [2]. It celebrated how \"San Francisco's Painted Ladies have enjoyed an astonishing renaissance\" and covered the Western Addition, colour choices and restoration [2]. The name stuck. It came to mean a Victorian or Edwardian house painted in three or more colours to bring out its architectural details [3]. Pomada and Larsen went on to write six books in the series [4].", "people": [{"name": "Morley Baer", "role": "photographer"}, {"name": "Elizabeth Pomada", "role": "co-author"}, {"name": "Michael Larsen", "role": "co-author"}, {"name": "Butch Kardum", "role": "colorist pioneer"}, {"name": "Bob Buckter", "role": "colour consultant"}], "sources": [{"title": "Rainbow Victorians and the Colorist Era in San Francisco", "publisher": "San Francisco Heritage (Kerri Young)", "year": 2020, "url": "https://sfheritage.org/features/colorfully-painted-victorians", "supports": "Kardum 1963; neighbours' reaction; Buckter 'Dr. Color' cards in 1970s"}, {"title": "Painted Ladies: San Francisco's Resplendent Victorians (catalogue record)", "publisher": "Google Books / Dutton", "year": 1978, "url": "https://books.google.com/books/about/Painted_Ladies.html?id=115i0tjS98EC", "supports": "Authors, publisher, year, 80 pages, description quote"}, {"title": "'Painted Lady' for sale for $1.6 million", "publisher": "San Francisco Chronicle / SFGATE (Dana Perrigan)", "year": 2009, "url": "https://www.sfgate.com/realestate/article/Painted-Lady-for-sale-for-1-6-million-3252522.php", "supports": "Definition of a Painted Lady: three or more colours to highlight architectural details"}, {"title": "About Elizabeth Pomada", "publisher": "Larsen Pomada Literary Agents", "year": null, "url": "https://larsen-pomada.com/perspective2.html", "supports": "Six books in the Painted Ladies series"}], "photo": null}, {"id": "victorian-alamo-square-district", "theme": "victorian", "title": "A Visual Reminder: Saving the Square", "year": 1984, "yearEnd": null, "place": "Alamo Square Historic District", "precision": "area", "c": [1124.8, 767.6], "block": "0799", "hook": "In 1984 San Francisco drew a line around Alamo Square's Victorians and declared them, officially, as much a symbol of the city as the cable cars.", "story": "By the time the Board of Supervisors acted in July 1984, the blocks around Alamo Square held a rare, largely intact run of houses built between 1870 and the 1920s [1][2]. The district runs from Golden Gate Avenue to Fell Street and from Webster Street to Divisadero [1]. Its styles vary, but the city found them unified by their \"residential character, relatively small scale, construction type, materials (principally wood), intense ornamentation (especially at entry and cornice)\" [1]. The designation called the district \"a continuum of distinguished residential architecture\" and \"a visual reminder of how businessmen lived two to four generations ago\" [2]. Most of the first owners, it noted, \"were moderately successful businessmen\" [1]. The city also made a bolder claim. It said the Westerfeld House and Postcard Row were \"as identified worldwide with San Francisco as the cable cars and Coit Tower\" [1].", "people": [], "sources": [{"title": "San Francisco Historic District: Alamo Square", "publisher": "NoeHill (quoting the district designation)", "year": 2010, "url": "https://noehill.com/sf/landmarks/sf_alamo_square.asp", "supports": "Boundaries, 1870–1929, July 1984, unifying characteristics quote, businessmen quote, cable cars and Coit Tower quote"}, {"title": "Alamo Square Historic District", "publisher": "LocalWiki San Francisco (with scan of Article 10 Appendix E)", "year": null, "url": "https://localwiki.org/sf/Alamo_Square_Historic_District", "supports": "Board of Supervisors 1984; 'continuum' and 'visual reminder' quotes"}], "photo": null}, {"id": "modern-black-lgbtq-western-addition", "theme": "modern", "title": "Coming Home in the Western Addition", "year": 1988, "yearEnd": null, "place": "Western Addition Cultural Center, 762 Fulton Street", "precision": "building", "c": [1622.0, 656.6], "block": "0781", "hook": "At the height of the AIDS crisis, Black gay and lesbian San Franciscans organised in Western Addition living rooms and shared Thanksgiving dinners.", "story": "On May 16, 1988, Bay Area Black Lesbians and Gays held an organisational kickoff at the Western Addition Cultural Center, 762 Fulton Street. That month the group had voted to become a chapter of the National Coalition of Black Lesbians and Gays again [1]. Its San Francisco meetings took place in members' homes, including Mary Midgett's at 437 Webster Street and the AIDS activist Reggie Williams's at 630 Fillmore Street. Midgett also opened her home for a 1988 holiday party and a Thanksgiving dinner. The city's LGBTQ context statement describes these as important gatherings for people who could not always join their biological families [1]. Williams, born in Cincinnati, had settled in San Francisco in the early 1980s. He saw that AIDS prevention was not reaching Black gay and bisexual men and called a meeting that led to the AIDS task force of Black and White Men Together. That task force grew into the National Task Force on AIDS Prevention, which he ran until 1994 [2]. \"My personal struggle with AIDS has forced me to demand respect and dignity from my people,\" he said. \"Black, gay men need to be able to come home\" [2]. He died in Amsterdam on February 7, 1999, aged 47 [2].", "people": [{"name": "Reggie Williams", "role": "AIDS activist, founding head of the National Task Force on AIDS Prevention"}, {"name": "Mary Midgett", "role": "Hosted Bay Area Black Lesbians and Gays gatherings at her Webster Street home"}], "sources": [{"title": "Citywide Historic Context Statement for LGBTQ History in San Francisco", "publisher": "San Francisco Planning Department (Donna Graves and Shayne Watson)", "year": 2016, "url": "https://default.sfplanning.org/Preservation/lgbt_HCS/FinalLGBTQ_HCS_March2016.pdf", "supports": "May 16, 1988 kickoff at 762 Fulton; NCBLG chapter vote; meetings at 630 Fillmore and 437 Webster; Midgett's holiday party and Thanksgiving"}, {"title": "Reggie Williams, Renowned S.F. AIDS Activist", "publisher": "San Francisco Chronicle (J.L. Pimsleur)", "year": 1999, "url": "https://www.sfgate.com/news/article/Reggie-Williams-Renowned-S-F-AIDS-Activist-2946805.php", "supports": "Williams's background, BWMT AIDS task force, NTFAP leadership to 1994, quotes, death in Amsterdam at 47"}], "photo": null}, {"id": "modern-central-freeway-falls", "theme": "modern", "title": "The Freeway That Split Hayes Valley", "year": 1989, "yearEnd": 2003, "place": "Octavia Street between Oak and Fell (former Central Freeway ramps)", "precision": "block", "c": [1989.7, 1079.5], "block": "0831", "hook": "The 1989 quake cracked a double-decker freeway over Hayes Valley. It took ten years and four ballot measures before the city finally agreed to tear it down.", "story": "The double-deck Central Freeway opened in 1959. It connected western San Francisco to downtown but split Hayes Valley apart, bringing blight and crime to the blocks beneath it [3]. \"The freeway was the border, and you didn't want to go under it,\" remembered longtime resident Madeline Behrens-Brigham. \"We were called 'the bad block'... You couldn't get a pizza, you couldn't get a taxi; the police wouldn't even come here\" [1]. The Loma Prieta earthquake of October 17, 1989 damaged the freeway, and key ramps had to be demolished [1][2]. What came next was a long political fight. \"Half the city wanted the freeway restored, and half wanted it torn down,\" said a Caltrans spokesman, who kept a chunk of the old freeway in a potted plant in his office [2]. In 1997 voters approved Proposition H to rebuild the freeway to Fell Street. In 1998 Proposition E, organised by activists including Robin Levitt, repealed it in favour of a boulevard. In 1999 voters passed Proposition I, which funded the Octavia Boulevard plan, and rejected Proposition J, a compromise with elevated ramps [1]. The ramps to Fell, Oak, Franklin and Gough came down in stages, the last in 2003 [2]. \"When the freeway disappeared, so did a lot of the problems,\" Levitt said [2].", "people": [{"name": "Robin Levitt", "role": "Architect and Hayes Valley Neighborhood Association board member"}, {"name": "Madeline Behrens-Brigham", "role": "Longtime resident"}, {"name": "Patricia Walkup", "role": "Neighborhood activist"}], "sources": [{"title": "The End Of The Central Freeway In Hayes Valley", "publisher": "Hoodline (Jennie Butler)", "year": 2015, "url": "https://hoodline.com/2015/08/the-end-of-the-central-freeway-in-hayes-valley/", "supports": "Quake date, ballot measures 1997-99 and results, Levitt's role, Behrens-Brigham quote"}, {"title": "Boulevard of dreams, the premiere / Hayes Valley freed of freeway", "publisher": "San Francisco Chronicle (Rachel Gordon)", "year": 2005, "url": "https://www.sfgate.com/bayarea/article/SAN-FRANCISCO-Boulevard-of-dreams-the-premiere-2610871.php", "supports": "Quake damage and ramp demolitions, Caltrans quote and potted plant, ramps removed in stages ending 2003, Levitt quote"}, {"title": "An urban success story / Octavia Boulevard an asset to post-Central Freeway area", "publisher": "San Francisco Chronicle (John King)", "year": 2007, "url": "https://www.sfgate.com/bayarea/place/article/SAN-FRANCISCO-An-urban-success-story-Octavia-2659608.php", "supports": "Double-deck freeway opened 1959, split the neighbourhood, blight and crime"}], "photo": null}, {"id": "modern-full-house-postcard-row", "theme": "modern", "title": "The Picnic That Made Postcard Row Famous", "year": 1990, "yearEnd": null, "place": "Postcard Row, 710-720 Steiner Street", "precision": "block", "c": [1283.9, 837.6], "block": "0803", "hook": "The Tanners never lived on Steiner Street. Fans still leave flowers there, and one woman brought a finished jigsaw of the houses all the way from Istanbul.", "story": "\"Full House\" premiered on ABC on September 22, 1987 [3]. For its first three seasons, the adult cast in the opening credits was not filmed in San Francisco. That changed with season four, which premiered in September 1990 [1][3]. From then on, the sequence ended with the cast having a picnic in Alamo Square, with the row of Painted Ladies behind them. The Tanners' house was never one of them, though many people think it was. The house used for the show's exterior was on Broderick Street [1][2]. The Chronicle has noted that the Painted Ladies, now a top-10 tourist attraction, once stood in a zone slated for demolition [4]. George Horsfall lives in the 1894 house at 712 Steiner. When actor Bob Saget died, fans left some 50 bouquets a day on his steps, along with cleaning gloves, because Saget's character was always cleaning [2]. Horsfall told them it wasn't the show's house, but they kept coming [2]. Strangers have married on his stoop. One woman rang his bell to give him a finished, glued jigsaw puzzle of the houses. When he asked where she had put it together, she said, \"Istanbul\" [2].", "people": [{"name": "George Horsfall", "role": "Owner of 712 Steiner Street"}, {"name": "Bob Saget", "role": "Actor who played Danny Tanner"}], "sources": [{"title": "Title Sequence", "publisher": "Full House Forever (full-house.org)", "year": null, "url": "http://www.full-house.org/fullhouse/fullhouse_openingcredits.php", "supports": "Adults not filmed in SF until season four; Alamo Square picnic shot; Tanner house not among the Painted Ladies"}, {"title": "We toured one of the SF homes 'Full House' made famous", "publisher": "SFGATE (Kendra Smith)", "year": 2023, "url": "https://www.sfgate.com/local/article/san-francisco-painted-ladies-tour-17694864.php", "supports": "712 Steiner built 1894, Horsfall, Saget bouquets and gloves, weddings, Istanbul puzzle, real house on Broderick"}, {"title": "List of Full House episodes", "publisher": "Wikipedia (pointer for air dates)", "year": null, "url": "https://en.wikipedia.org/wiki/List_of_Full_House_episodes", "supports": "Premiere Sept. 22, 1987 and season-four premiere Sept. 21, 1990 on ABC"}, {"title": "The strange, psychedelic history of how San Francisco got colorful homes", "publisher": "San Francisco Chronicle (Peter Hartlaub)", "year": 2026, "url": "https://www.sfchronicle.com/totalsf/article/victorian-home-san-francisco-21939697.php", "supports": "Painted Ladies once in a demolition zone; now a top-10 tourist attraction"}], "photo": null}, {"id": "modern-848-divisadero", "theme": "modern", "title": "848: Anything Could Happen", "year": 1991, "yearEnd": 2005, "place": "848 Divisadero Street", "precision": "building", "c": [851.5, 601.9], "block": "1180", "hook": "In a windowless upstairs studio on Divisadero, a few dancers made a home for queer performance, trans art and safer-sex parties during the AIDS years.", "story": "In November 1991, Michael \"Med-O\" Whitson, Todd Eugene and the dancer Keith Hennessy took over a second-floor studio at 848 Divisadero from friends who were moving out, and kept its name [2]. The room was windowless, about 1,100 square feet, with movable risers that seated fewer than 50 people [2]. It held a weekly Contact Improvisation jam and hundreds of performances, concerts and exhibitions [2]. It quickly became a sex-radical space as well. The city's LGBTQ context statement says 848 organised and welcomed sex events partly as a way to address healing around AIDS [1]. \"At 848 we bragged that anything could happen,\" Hennessy remembered. \"For $100 a night we handed the keys to the space to almost anyone\" [1]. Groups including Body Electric, Queen of Heaven, the Radical Faeries and Black Leather Wings held events there, as did the artist Annie Sprinkle [1]. In 1994 it showed Loren Cameron's transgender photography exhibit and David Harrison's performance \"FTM\" [2]. By Hennessy's count, it drew about 10,000 visitors a year in its later years. In 2005 its collective gave rise to CounterPULSE [2].", "people": [{"name": "Keith Hennessy", "role": "Dancer, co-founder"}, {"name": "Michael \"Med-O\" Whitson", "role": "Co-founder"}, {"name": "Todd Eugene", "role": "Co-founder"}, {"name": "Loren Cameron", "role": "Photographer, 1994 exhibit"}], "sources": [{"title": "Citywide Historic Context Statement for LGBTQ History in San Francisco", "publisher": "San Francisco Planning Department", "year": 2016, "url": "https://default.sfplanning.org/Preservation/lgbt_HCS/FinalLGBTQ_HCS_March2016.pdf", "supports": "Opened fall 1991; sex events and AIDS healing; Hennessy quote; list of groups and Annie Sprinkle"}, {"title": "848: queer, sex, performance in 1990s San Francisco (article draft)", "publisher": "Circo Zero (Keith Hennessy)", "year": 2013, "url": "https://circozero.org/writing-rants/2013/05/848-queer-sex-performance-in-1990s-san.html", "supports": "Founders, November 1991, size and seating, Contact jam, 1994 trans shows, visitor numbers, CounterPULSE 2005"}], "photo": null}, {"id": "modern-lower-haight-microbrew-alley", "theme": "modern", "title": "From Needle Alley to Microbrew Alley", "year": 2001, "yearEnd": null, "place": "500 block of Haight Street (Toronado, 547 Haight)", "precision": "block", "c": [1329.8, 1320.8], "block": "0860", "hook": "At the turn of the millennium, the Chronicle called the Lower Haight the city's underground: beer bars, record shops, DJ nights and a dark bar lit by static.", "story": "\"Lower Haight is to the underground what Upper Haight was 30 years ago,\" the Chronicle declared in 2001 [1]. The 500 block of Haight Street, once known as Needle Alley, had become Microbrew Alley. On one side was the Toronado, where owner David \"Big Daddy\" Keene kept a back room lined with hundreds of custom tap handles. Across the street, English fans at the Mad Dog in the Fog watched European football over pints at 6 a.m. [1]. Next door to the Toronado, Noc Noc was lit mostly by old TVs showing static [1]. The strip had five record stores, which supplied the records DJs wheeled into clubs on dollies [1]. At 460 Haight, Nickie's BBQ was one of the Bay Area's oldest destination dance clubs. It hosted Grateful Dead jams by Dark Star Dan on Mondays and Cheb I. Sabbah's global \"Outer National Mix\" on Tuesdays [1]. Nickie's went back to 1948, when it was Nicki's Barbecue. It was later a dancehall and a dive bar, and from 2007 an Irish sports bar [2]. In 2020 a longtime regular, Tom Mills, bought it. He said he and 20 or 30 other regulars thought of it as \"the neighborhood's living room\" [2].", "people": [{"name": "David \"Big Daddy\" Keene", "role": "Owner of the Toronado"}, {"name": "Cheb I. Sabbah", "role": "DJ, Tuesday nights at Nickie's"}, {"name": "Tom Mills", "role": "Bought Nickie's in 2020"}], "sources": [{"title": "High on Haight / Lower Haight, where the trends begin and the beers end", "publisher": "San Francisco Chronicle (Sam Whiting)", "year": 2001, "url": "https://www.sfgate.com/magazine/article/high-on-haight-lower-haight-where-the-trends-2876731.php", "supports": "Underground quote, Needle Alley and Microbrew Alley, Toronado and Keene, Mad Dog, Noc Noc, record stores, Nickie's nights"}, {"title": "New owner aims to restore Nickie's as 'neighborhood living room' for Lower Haight", "publisher": "Hoodline (Alisa Scerrato)", "year": 2020, "url": "https://hoodline.com/2020/08/new-owner-aims-to-restore-nickie-s-as-neighborhood-living-room-for-lower-haight/", "supports": "Nickie's origins in 1948, its later phases, 2007 renovation, Tom Mills's 2020 purchase and quote"}], "photo": null}, {"id": "modern-patricias-green", "theme": "modern", "title": "Patricia's Green", "year": 2005, "yearEnd": 2006, "place": "Patricia's Green, Octavia Boulevard between Fell and Hayes", "precision": "block", "c": [2002.5, 958.3], "block": "0817", "hook": "Where freeway ramps once came down, a small park opened in 2005. Months later it was renamed for the soft-spoken activist who fought to get it built.", "story": "On September 9, 2005, Octavia Boulevard opened with a ribbon-cutting at Market Street [2]. The designers, Allan Jacobs and Elizabeth Macdonald, followed the principle \"No one gets everything, but everyone gets a lot\" [2][3]. The boulevard has four central lanes for commuters and a slower lane on each side for local traffic [2]. It was planted with 261 trees, including evergreen elms, flowering cherries and pears, and Lombardy poplars [1]. At its northern end, between Fell and Hayes, was a new park called Hayes Green. \"This is just an amazing gift for the neighborhood,\" said Patricia Walkup, the activist who helped lead the fight against rebuilding the freeway [1]. \"In a few years, there will be people who will never know a freeway was there\" [1]. Walkup, founder of the Hayes Valley Neighborhood Association, died on June 6, 2006, at 59. That August the Recreation and Park Commission voted unanimously to rename the park \"Patricia's Green in Hayes Valley\" [4]. \"If not for Patricia, that park would not be there,\" said her friend Robin Levitt. \"If she hadn't done that work, we would have a freeway there\" [4]. In December 2006 the American Planning Association gave the project its first award for \"hard-won victories\" [2].", "people": [{"name": "Patricia Walkup", "role": "Founder of the Hayes Valley Neighborhood Association"}, {"name": "Allan Jacobs", "role": "Planner, boulevard designer"}, {"name": "Elizabeth Macdonald", "role": "Planner, boulevard designer"}, {"name": "Robin Levitt", "role": "Architect and neighbour"}], "sources": [{"title": "Boulevard of dreams, the premiere / Hayes Valley freed of freeway", "publisher": "San Francisco Chronicle (Rachel Gordon)", "year": 2005, "url": "https://www.sfgate.com/bayarea/article/SAN-FRANCISCO-Boulevard-of-dreams-the-premiere-2610871.php", "supports": "261 trees and species, Hayes Green between Fell and Hayes, Walkup quotes"}, {"title": "An urban success story / Octavia Boulevard an asset to post-Central Freeway area", "publisher": "San Francisco Chronicle (John King)", "year": 2007, "url": "https://www.sfgate.com/bayarea/place/article/SAN-FRANCISCO-An-urban-success-story-Octavia-2659608.php", "supports": "Sept. 9, 2005 ribbon-cutting, lane layout, Jacobs and Macdonald, APA award"}, {"title": "Everyone Gets A Lot: The Creation Of Octavia Boulevard And Patricia's Green", "publisher": "Hoodline (Jennie Butler)", "year": 2015, "url": "https://hoodline.com/2015/10/central-freeway-octavia-boulevard-patricias-green/", "supports": "'No one gets everything, but everyone gets a lot' design principle"}, {"title": "Hayes Valley park to be named after green activist", "publisher": "San Francisco Examiner", "year": 2006, "url": "https://www.sfexaminer.com/news/hayes-valley-park-to-be-named-after-green-activist/article_ba1af560-f491-5348-b638-59d7527bd1e8.html", "supports": "Walkup's death at 59, unanimous commission vote, new name, Levitt quote"}], "photo": null}, {"id": "modern-whats-nopa", "theme": "modern", "title": "\"Huh? What's NoPa?\"", "year": 2006, "yearEnd": null, "place": "Nopa, 560 Divisadero Street (at Hayes)", "precision": "building", "c": [843.8, 904.8], "block": "1203", "hook": "Realtors get the blame for the name NoPa. It actually came from a neighbourhood newsletter, and a restaurant in an old bank made it stick.", "story": "The North of the Panhandle Neighborhood Association was founded in 1991, as neighbours organised against drug-related crime [2]. At some point in the 1990s the group's newsletter briefly changed its name from \"North Panhandle News\" to \"NoPa News.\" The name didn't stick, according to longtime board member James Cowan. He had also heard that someone proposed \"Parc North\" and residents vetoed it [1]. In 2000 the writer Mat Honan used \"NoPa\" in the Bay Guardian, which may be the first time it appeared in print. He described a neighbourhood \"struggling to define itself as gentrification takes hold\" [1]. The name only caught on after April 11, 2006. That night Jeff Hanak and Allyson and Laurence Jossel opened a restaurant in a grand old bank building at Divisadero and Hayes [3]. When they were choosing a name, a friend pointed out that the address was in NoPa. \"We were like, 'Huh? What's NoPa?'\" Allyson recalled [3]. At the time, only a few restaurants stood on that stretch of Divisadero. On opening night the kitchen ran low on food, and a customer brought in chicken from the Popeyes across the street [3]. As restaurants such as Bi-Rite, Bar Crudo, Ragazza and the Mill opened nearby, a name that needed constant explaining became the neighbourhood's own [1][3].", "people": [{"name": "James Cowan", "role": "NOPNA board member"}, {"name": "Mat Honan", "role": "Writer, San Francisco Bay Guardian"}, {"name": "Laurence Jossel", "role": "Chef and co-owner, Nopa"}, {"name": "Allyson Jossel", "role": "Co-owner, Nopa"}, {"name": "Jeff Hanak", "role": "Co-owner, Nopa"}], "sources": [{"title": "NoPa Vs. Western Addition: What's In A Name?", "publisher": "Hoodline (Nuala Sawyer)", "year": 2014, "url": "https://hoodline.com/2014/07/nopa-vs-western-addition-what-s-in-a-name/", "supports": "'NoPa News' newsletter, Cowan, 'Parc North', Honan's 2000 Bay Guardian usage and quote, restaurant popularising the name"}, {"title": "Meet The North Of The Panhandle Neighborhood Association", "publisher": "Hoodline (Nuala Sawyer)", "year": 2014, "url": "https://hoodline.com/2014/07/meet-the-north-of-the-panhandle-neighborhood-association-nopna/", "supports": "NOPNA founded in 1991 in response to drug-related crime"}, {"title": "Nopa at 10: The restaurant that built a neighborhood (and vice versa)", "publisher": "San Francisco Chronicle (Amanda Gold)", "year": 2016, "url": "https://www.sfchronicle.com/restaurants/article/Nopa-at-10-The-restaurant-that-built-a-6892082.php", "supports": "April 11, 2006 opening, owners, bank building, naming story and quote, Popeyes anecdote, later neighbours"}], "photo": null}, {"id": "modern-hayes-valley-farm", "theme": "modern", "title": "A Farm Where the On-Ramps Were", "year": 2010, "yearEnd": 2013, "place": "Laguna Street between Oak and Fell (Hayes Valley Farm, 450 Laguna)", "precision": "block", "c": [1827.1, 1039.2], "block": "0830", "hook": "For three years, vacant lots left by the demolished freeway ramps grew fava beans and fruit trees, until the condos arrived as planned.", "story": "After the Central Freeway's on-ramps came down, the land on Laguna Street between Oak and Fell stood empty [1][2]. In 2010 Mayor Gavin Newsom's Office of Economic and Workforce Development proposed an interim use and put up a $50,000 first-year grant, paid for with parking revenue from Octavia Boulevard [1]. Volunteers built Hayes Valley Farm on the lots. The soil was tested at 64 points, and only one exceeded federal lead standards [1]. \"Our main yield is education,\" said director Chris Burley [1]. The farm grew a permaculture garden by sheet-mulching cardboard, horse manure and mulch straight onto the old freeway land, and planted fava beans to put nitrogen back into the soil [2]. \"It doesn't take a lot of time, funding, or resources to create biodiversity spaces loved by communities,\" said co-founder Jay Rosenberg [2]. The farm was always meant to be temporary, with the lots set aside for mixed affordable and market-rate housing [1]. By the farm's own count, tens of thousands of visitors took part [3]. It moved off its Oak Street side on March 1, 2013, and its final day was May 31, 2013 [3]. Volunteers went on to start a string of new urban-farming projects around the city [2].", "people": [{"name": "Chris Burley", "role": "Director, Hayes Valley Farm"}, {"name": "Jay Rosenberg", "role": "Co-founder"}], "sources": [{"title": "Building a Farm Where a Freeway Used to Be", "publisher": "Streetsblog San Francisco (Matthew Roth)", "year": 2010, "url": "https://sf.streetsblog.org/2010/02/08/building-a-farm-where-a-freeway-used-to-be", "supports": "Location, former on-ramps, interim-use idea, $50,000 grant from parking revenue, soil tests, Burley quote, housing plans"}, {"title": "The True Story Behind Hayes Valley Farm", "publisher": "Hoodline (Ryan Curran White)", "year": 2013, "url": "https://hoodline.com/2013/06/the-true-story-behind-hayes-valley-farm/", "supports": "Sheet mulching, fava beans, Rosenberg quote, legacy projects"}, {"title": "History", "publisher": "Hayes Valley Farm", "year": null, "url": "https://www.hayesvalleyfarm.org/history/", "supports": "Tens of thousands of visitors, March 1 transition off Oak Street, final day May 31, 2013"}], "photo": null}, {"id": "modern-alamo-square-renovation", "theme": "modern", "title": "The Year the Famous View Closed", "year": 2016, "yearEnd": 2017, "place": "Alamo Square Park (Hayes and Steiner streets)", "precision": "area", "c": [1138.5, 783.0], "block": "0799", "hook": "For a year, chain-link fences surrounded the city's most photographed lawn. When the park reopened, its planners wanted it to become the view itself.", "story": "In May 2016 the 12.7-acre Alamo Square Park closed for a $5.3 million renovation. The work was supposed to take seven months, but it took a year because of a wet winter and extra work that wasn't in the original plan [1][2]. Crews rebuilt the irrigation system, which is controlled by a small device on a nearby flagpole that monitors temperature and rainfall. The park was expected to save more than 2.5 million gallons of water a year, about a third of its use [2]. They repaved the paths, added an all-gender accessible restroom, and planted a rain garden and native plants, using the tennis court as a temporary nursery [1][2]. Neighbours paid for 45 new trees [1]. \"Everyone loves the views out of the park,\" said Recreation and Park project manager Brett Desmarais. \"But we want the park to become the view itself\" [2]. On the last quiet morning before it reopened, the sidewalk by the Painted Ladies, normally crowded, was empty except for a woman in a bathrobe handing her husband a mug of coffee as he set off on his bike [2]. The ribbon was cut on May 24, 2017, and Board of Supervisors President London Breed called the park \"one of the jewels of our city\" [1].", "people": [{"name": "Brett Desmarais", "role": "Recreation and Park Department project manager"}, {"name": "London Breed", "role": "President, Board of Supervisors"}, {"name": "Ed Lee", "role": "Mayor"}], "sources": [{"title": "Alamo Square Park Has Officially Reopened", "publisher": "Hoodline (with Bay City News)", "year": 2017, "url": "https://hoodline.com/2017/05/alamo-square-park-has-officially-reopened/", "supports": "May 2016 closure, seven-month plan and delays, $5.3M, restroom, 45 trees, May 24, 2017 reopening, Breed quote"}, {"title": "Alamo Square Park, neighbor of Painted Ladies, reopening", "publisher": "San Francisco Chronicle (Lizzie Johnson)", "year": 2017, "url": "https://www.sfgate.com/bayarea/article/Alamo-Square-Park-neighbor-of-Painted-Ladies-11168387.php", "supports": "12.7 acres, rain delay, irrigation and flagpole sensor, water savings, rain garden, tennis-court nursery, Desmarais quote, empty sidewalk scene"}], "photo": null}]};
